-- =============================================================================
-- Baseline: the whole schema and its reference data, as one migration.
--
-- Replaces the 270 migrations V20260901000100 .. V20261117000300 (git history up to commit df34c338 keeps them).
-- They were squashed on 2026-11-11, while every database of the project held demo data only: the rescope of
-- November 2026 had to rebuild every database anyway (its migrations refuse to run over pre-rescope data), so no
-- environment needs the upgrade path they encoded, and a fresh database no longer creates tables only to drop them
-- again, nor archives rows it inserted itself.
--
-- How it was made, so it can be made again if ever needed:
--   1. an empty PostgreSQL 16 database (UTF8, locale C) migrated with those 270 files by Flyway 11.7.2;
--   2. pg_dump --no-owner --no-privileges --inserts, without flyway_schema_history and without the rows of
--      platform.legacy_archive (the 323 rows a fresh database archived were seeded grants and carriers the same
--      migrations created and later removed: history of the migrations, not data);
--   3. psql meta-commands and session SETs removed. pg_dump schema-qualifies every name itself, and the
--      `set_config('search_path', '', false)` it starts with would outlive the migration on a pooled connection;
--   4. the 18 CHECK constraints the old migrations added NOT VALID (to spare rows written before them) are created
--      validated here - a fresh database has no such rows. This is contract step C0 of the 2026-09-28 migration plan,
--      which db/pending held until now.
-- A database built from this file was checked against one built from the 270 files: pg_dump of both is the same
-- objects and the same rows, apart from those 18 now being valid and Postgres re-printing a re-parsed CHECK
-- (`x IN (...)` on varchar, chained ANDs) with different casts and parentheses.
--
-- Rows below are pg_dump's, so ids of seeded rows (roles, permissions, grants, transitions, tax rates, carriers) are
-- the ones generated by that one run, and their created_at the moment of it. Nothing may depend on either.
--
-- From here on, every schema change is a NEW migration with a version above V20261111000000.
-- =============================================================================

-- What pg_dump's own header sets, kept to this transaction (LOCAL) so nothing outlives it on a pooled connection:
-- SQL functions are created before the tables their bodies read, and the server's statement limit must not cut
-- the load short.
SET LOCAL check_function_bodies = false;
SET LOCAL statement_timeout = 0;
SET LOCAL lock_timeout = 0;

