-- Name: reject_design_asset_mutation(); Type: FUNCTION; Schema: design; Owner: -
--

CREATE FUNCTION design.reject_design_asset_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
