-- Name: reject_project_event_mutation(); Type: FUNCTION; Schema: design; Owner: -
--

CREATE FUNCTION design.reject_project_event_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'A design project''s history is append-only';
END;
$$;

