    RAISE EXCEPTION 'Confirmed design snapshots are immutable';
END;
$$;

--
-- Name: carrier_event_guard(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.carrier_event_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'fulfillment.carrier_event is never deleted' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.carrier_id IS DISTINCT FROM OLD.carrier_id OR NEW.carrier_code IS DISTINCT FROM OLD.carrier_code
        OR NEW.received_at IS DISTINCT FROM OLD.received_at OR NEW.payload IS DISTINCT FROM OLD.payload
        OR NEW.signature_valid IS DISTINCT FROM OLD.signature_valid THEN
        RAISE EXCEPTION 'What a carrier sent is kept as it came' USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.result <> 'RECEIVED' AND (NEW.result IS DISTINCT FROM OLD.result
        OR NEW.result_note IS DISTINCT FROM OLD.result_note OR NEW.load_id IS DISTINCT FROM OLD.load_id
        OR NEW.shipment_id IS DISTINCT FROM OLD.shipment_id OR NEW.event_kind IS DISTINCT FROM OLD.event_kind
        OR NEW.dedupe_key IS DISTINCT FROM OLD.dedupe_key OR NEW.decided_at IS DISTINCT FROM OLD.decided_at) THEN
        RAISE EXCEPTION 'A carrier event is decided once and never applied again (09 BR-27)'
            USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.resolved_at IS NOT NULL AND (NEW.resolved_at IS DISTINCT FROM OLD.resolved_at
        OR NEW.resolved_by IS DISTINCT FROM OLD.resolved_by
        OR NEW.resolution_note IS DISTINCT FROM OLD.resolution_note) THEN
        RAISE EXCEPTION 'A resolved carrier event stays resolved as it was' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_load_package(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_load_package() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    p fulfillment.package%ROWTYPE;
BEGIN
    IF NOT NEW.active OR (TG_OP = 'UPDATE' AND OLD.active) THEN
        RETURN NEW;
    END IF;
    SELECT * INTO p FROM fulfillment.package WHERE id = NEW.package_id;
    IF p.status NOT IN ('SEALED', 'LABELED') OR p.shipment_id IS DISTINCT FROM NEW.shipment_id THEN
        RAISE EXCEPTION 'package % is not a sealed parcel or labelled carton of shipment %', p.label_code,
            NEW.shipment_id USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM fulfillment.dispatch_load_shipment ls
                    JOIN fulfillment.dispatch_load l ON l.id = ls.load_id
                   WHERE ls.load_id = NEW.load_id AND ls.active AND ls.shipment_id = NEW.shipment_id
                     AND l.status IN ('PLANNED', 'VEHICLE_BOOKED', 'LOADING')) THEN
        RAISE EXCEPTION 'package % is not on an open manifest with its shipment', p.label_code
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_load_placement(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_load_placement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v fulfillment.load_plan_vehicle%ROWTYPE;
    p fulfillment.package%ROWTYPE;
    placed INTEGER[];
    measured INTEGER[];
BEGIN
    SELECT * INTO v FROM fulfillment.load_plan_vehicle WHERE id = NEW.load_plan_vehicle_id;
    IF NOT v.active THEN
        RAISE EXCEPTION 'tg_load_placement_check: vehicle % of the plan was replaced', v.seq
            USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_load_placement_check';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM fulfillment.load_plan_package lp
                    WHERE lp.load_plan_id = NEW.load_plan_id AND lp.package_id = NEW.package_id AND lp.active) THEN
        RAISE EXCEPTION 'tg_load_placement_check: package % is not held by the plan', NEW.package_id
            USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_load_placement_check';
    END IF;
    SELECT * INTO p FROM fulfillment.package WHERE id = NEW.package_id;
    SELECT array_agg(s ORDER BY s) INTO placed FROM unnest(ARRAY[NEW.w_mm, NEW.h_mm, NEW.d_mm]) AS s;
    SELECT array_agg(s ORDER BY s) INTO measured
      FROM unnest(ARRAY[ceil(p.length_cm * 10)::int, ceil(p.width_cm * 10)::int, ceil(p.height_cm * 10)::int]) AS s;
    IF placed <> measured THEN
        RAISE EXCEPTION 'tg_load_placement_check: placed sizes % are not the sizes % of package %', placed, measured,
            p.label_code USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_load_placement_check';
    END IF;
    IF NEW.x_mm + NEW.w_mm > v.inner_width_mm OR NEW.y_mm + NEW.h_mm > v.inner_height_mm
        OR NEW.z_mm + NEW.d_mm > v.inner_length_mm THEN
        RAISE EXCEPTION 'tg_load_placement_check: package % stands out of vehicle %', p.label_code, v.seq
            USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_load_placement_check';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_load_plan_package(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_load_plan_package() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    p    fulfillment.package%ROWTYPE;
    s    fulfillment.shipment%ROWTYPE;
    plan fulfillment.load_plan%ROWTYPE;
BEGIN
    IF NOT NEW.active OR (TG_OP = 'UPDATE' AND OLD.active) THEN
        RETURN NEW;
    END IF;
    SELECT * INTO p FROM fulfillment.package WHERE id = NEW.package_id;
    SELECT * INTO plan FROM fulfillment.load_plan WHERE id = NEW.load_plan_id;
    IF p.status NOT IN ('SEALED', 'LABELED') OR p.weight_kg IS NULL OR p.weight_kg <= 0 OR p.length_cm IS NULL
        OR p.length_cm <= 0 OR p.width_cm IS NULL OR p.width_cm <= 0 OR p.height_cm IS NULL OR p.height_cm <= 0
        OR p.shipment_id IS DISTINCT FROM NEW.shipment_id THEN
        RAISE EXCEPTION 'tg_load_plan_package_check: package % is not a sealed or labelled, measured parcel of its '
            'shipment', p.label_code USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_load_plan_package_check';
    END IF;
    SELECT * INTO s FROM fulfillment.shipment WHERE id = NEW.shipment_id;
    IF s.status <> 'READY_TO_DISPATCH' OR s.warehouse_id <> plan.warehouse_id THEN
        RAISE EXCEPTION 'tg_load_plan_package_check: shipment % is not waiting for dispatch at the plan''s warehouse',
            s.code USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_load_plan_package_check';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_load_shipment(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_load_shipment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    s fulfillment.shipment%ROWTYPE;
    l fulfillment.dispatch_load%ROWTYPE;
    plan_id UUID;
BEGIN
    IF NOT NEW.active OR (TG_OP = 'UPDATE' AND OLD.active) THEN
        RETURN NEW;
    END IF;
    SELECT * INTO l FROM fulfillment.dispatch_load WHERE id = NEW.load_id;
    IF l.status NOT IN ('PLANNED', 'VEHICLE_BOOKED', 'LOADING') THEN
        RAISE EXCEPTION 'load % is %', l.code, l.status USING ERRCODE = 'check_violation';
    END IF;
    SELECT * INTO s FROM fulfillment.shipment WHERE id = NEW.shipment_id;
    IF s.status <> 'READY_TO_DISPATCH' THEN
        RAISE EXCEPTION 'shipment % is %, not waiting for dispatch', s.code, s.status USING ERRCODE = 'check_violation';
    END IF;
    IF s.warehouse_id <> l.warehouse_id THEN
        RAISE EXCEPTION 'shipment % does not belong on load %', s.code, l.code USING ERRCODE = 'check_violation';
    END IF;
    SELECT v.load_plan_id INTO plan_id FROM fulfillment.load_plan_vehicle v WHERE v.id = l.load_plan_vehicle_id;
    IF EXISTS (SELECT 1 FROM fulfillment.dispatch_load_shipment o
                 JOIN fulfillment.dispatch_load ol ON ol.id = o.load_id
                 LEFT JOIN fulfillment.load_plan_vehicle ov ON ov.id = ol.load_plan_vehicle_id
                WHERE o.shipment_id = NEW.shipment_id AND o.active AND o.load_id <> NEW.load_id
                  AND ov.load_plan_id IS DISTINCT FROM plan_id) THEN
        RAISE EXCEPTION 'shipment % is on a load of another plan than load %', s.code, l.code
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_load_unloaded(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_load_unloaded() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'DISPATCHED' AND OLD.status IS DISTINCT FROM 'DISPATCHED'
        AND EXISTS (SELECT 1 FROM fulfillment.dispatch_load_unload u
                     WHERE u.load_id = NEW.id AND u.unloaded_at IS NULL) THEN
        RAISE EXCEPTION 'tg_dispatch_load_unload_pending: load % still carries parcels to unload', NEW.code
            USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_dispatch_load_unload_pending';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_package_carton(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_package_carton() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    line      fulfillment.pick_line%ROWTYPE;
    pack_pick UUID;
BEGIN
    IF TG_OP = 'UPDATE' AND (NEW.pick_line_id IS DISTINCT FROM OLD.pick_line_id OR NEW.lpn IS DISTINCT FROM OLD.lpn
            OR (OLD.pick_line_id IS NOT NULL AND NEW.pack_id IS DISTINCT FROM OLD.pack_id)) THEN
        RAISE EXCEPTION 'tg_package_carton: package % keeps its carton, pick line and check session', OLD.label_code
            USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_package_carton';
    END IF;
    IF NEW.pick_line_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'INSERT' THEN
        SELECT * INTO line FROM fulfillment.pick_line WHERE id = NEW.pick_line_id;
        SELECT pick_id INTO pack_pick FROM fulfillment.pack WHERE id = NEW.pack_id;
        IF line.pick_id IS DISTINCT FROM pack_pick OR line.status IS DISTINCT FROM 'PICKED'
                OR upper(line.lpn) IS DISTINCT FROM upper(NEW.lpn) THEN
            RAISE EXCEPTION 'tg_package_carton: carton % is not a carton picked for this task (08 BR-05)', NEW.lpn
                USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_package_carton';
        END IF;
        IF NEW.status <> 'TO_CHECK' THEN
            RAISE EXCEPTION 'tg_package_carton: carton % starts TO_CHECK, not %', NEW.lpn, NEW.status
                USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_package_carton';
        END IF;
    ELSIF NEW.status IS DISTINCT FROM OLD.status AND NOT (
            (OLD.status = 'TO_CHECK' AND NEW.status IN ('CHECKED', 'REMOVED'))
            OR (OLD.status = 'CHECKED' AND NEW.status IN ('LABELED', 'REMOVED'))
            OR (OLD.status = 'LABELED' AND NEW.status = 'REMOVED')) THEN
        RAISE EXCEPTION 'tg_package_carton: carton % does not go from % to % (08 §5.2)', NEW.lpn, OLD.status, NEW.status
            USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_package_carton';
    ELSIF OLD.status = 'LABELED' AND NEW.status = 'LABELED' AND NEW.label_version < OLD.label_version THEN
        RAISE EXCEPTION 'tg_package_carton: the label of carton % is reprinted forward only', NEW.lpn
            USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_package_carton';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_package_is_carton(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_package_is_carton() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.pick_line_id IS NULL THEN
        RAISE EXCEPTION 'package %: parcels are no longer packed; a shipping carton names its pick line (08 BR-02)',
            NEW.label_code USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_package_label_locks_order(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_package_label_locks_order() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    locked TIMESTAMPTZ;
    order_no VARCHAR;
BEGIN
    SELECT o.first_labeled_at, o.order_number INTO locked, order_no
      FROM fulfillment.pack k
      JOIN fulfillment.pick p ON p.id = k.pick_id
      JOIN ordering.customer_order o ON o.id = p.order_id
     WHERE k.id = NEW.pack_id;
    IF locked IS NULL THEN
        RAISE EXCEPTION 'tg_package_label_locks_order: carton % is labelled but order % is not locked (08 BR-04)',
            NEW.lpn, order_no USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_package_label_locks_order';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_package_line(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_package_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM fulfillment.package pk
          JOIN fulfillment.pack pa ON pa.id = pk.pack_id
          JOIN fulfillment.pick pi ON pi.id = pa.pick_id
          JOIN ordering.order_line l ON l.order_id = pi.order_id
         WHERE pk.id = NEW.package_id AND l.id = NEW.order_line_id) THEN
        RAISE EXCEPTION 'a package holds lines of its own order only'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_package_unloaded(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_package_unloaded() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.active AND (TG_OP = 'INSERT' OR NOT OLD.active)
        AND EXISTS (SELECT 1 FROM fulfillment.dispatch_load_unload u
                     WHERE u.package_id = NEW.package_id AND u.unloaded_at IS NULL) THEN
        RAISE EXCEPTION 'tg_package_awaiting_unload: package % is still to be scanned off a vehicle', NEW.package_id
            USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_package_awaiting_unload';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_pick_delivery_batch(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_pick_delivery_batch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.delivery_batch_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM ordering.delivery_batch_release r
         WHERE r.delivery_batch_id = NEW.delivery_batch_id AND r.order_id = NEW.order_id) THEN
        RAISE EXCEPTION 'pick % of order %: batch % is not a released batch of that order', NEW.id, NEW.order_id,
            NEW.delivery_batch_id USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_pick_line(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_pick_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM fulfillment.pick p
          JOIN ordering.order_line l ON l.order_id = p.order_id
         WHERE p.id = NEW.pick_id AND l.id = NEW.order_line_id AND l.sku = NEW.sku) THEN
        RAISE EXCEPTION 'pick line must pick a line of the pick''s own order, with that line''s sku'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_pick_line_carton(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_pick_line_carton() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    expected VARCHAR(30);
BEGIN
    SELECT p.lpn INTO expected
      FROM inventory.stock_reservation r
      JOIN inventory.stock_item s ON s.id = r.stock_item_id
      LEFT JOIN inventory.stock_package p ON p.id = s.stock_package_id
     WHERE r.id = NEW.reservation_id;
    IF NEW.lpn IS DISTINCT FROM expected THEN
        RAISE EXCEPTION 'pick line % must name carton %, the carton of its hold; it names %',
            NEW.id, coalesce(expected, '(none: loose stock)'), coalesce(NEW.lpn, '(none)')
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_pick_line_carton_removed(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_pick_line_carton_removed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM fulfillment.package p WHERE p.pick_line_id = NEW.id AND p.status <> 'REMOVED') THEN
        RAISE EXCEPTION 'tg_pick_line_carton_removed: carton % is at the check station; remove it there first (08 §4.2 '
            'step 4)', NEW.lpn
            USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_pick_line_carton_removed';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_pick_pending_edits(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.check_pick_pending_edits() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.status <> 'PENDING'
       AND (NEW.assigned_user_id IS DISTINCT FROM OLD.assigned_user_id
            OR NEW.destination IS DISTINCT FROM OLD.destination
            OR NEW.staging_location_code IS DISTINCT FROM OLD.staging_location_code) THEN
        RAISE EXCEPTION 'pick % is %: its assignee and destination change only while it is PENDING', NEW.id, OLD.status
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.staging_location_code IS NOT NULL AND (TG_OP = 'INSERT'
            OR NEW.staging_location_code IS DISTINCT FROM OLD.staging_location_code)
       AND NOT EXISTS (SELECT 1
                         FROM warehouse.storage_location l
                         JOIN warehouse.area a ON a.location_id = l.id
                        WHERE l.location_code = NEW.staging_location_code
                          AND l.warehouse_id = NEW.warehouse_id
                          AND a.type = 'STAGING') THEN
        RAISE EXCEPTION 'pick % names % as its staging area; it is not a staging area of warehouse %', NEW.id,
            NEW.staging_location_code, NEW.warehouse_id USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: guard_package_in_load_plan(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.guard_package_in_load_plan() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status OR NEW.shipment_id IS DISTINCT FROM OLD.shipment_id
        OR NEW.length_cm IS DISTINCT FROM OLD.length_cm OR NEW.width_cm IS DISTINCT FROM OLD.width_cm
        OR NEW.height_cm IS DISTINCT FROM OLD.height_cm OR NEW.weight_kg IS DISTINCT FROM OLD.weight_kg
        OR NEW.rotatable IS DISTINCT FROM OLD.rotatable THEN
        IF EXISTS (SELECT 1 FROM fulfillment.load_plan_package lp WHERE lp.package_id = OLD.id AND lp.active) THEN
            RAISE EXCEPTION 'tg_package_in_load_plan: package % is in a load plan', OLD.label_code
                USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_package_in_load_plan';
        END IF;
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: vehicle_type_guard_preset(); Type: FUNCTION; Schema: fulfillment; Owner: -
--

CREATE FUNCTION fulfillment.vehicle_type_guard_preset() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.is_preset THEN
            RAISE EXCEPTION 'vehicle type % is a preset and cannot be deleted', OLD.code USING ERRCODE = '23514';
        END IF;
        RETURN OLD;
    END IF;
    IF NEW.code <> OLD.code THEN
        RAISE EXCEPTION 'the code of vehicle type % cannot change', OLD.code USING ERRCODE = '23514';
    END IF;
    IF OLD.is_preset AND NEW.kind <> OLD.kind THEN
        RAISE EXCEPTION 'the kind of preset vehicle type % cannot change', OLD.code USING ERRCODE = '23514';
    END IF;
    IF NEW.is_preset <> OLD.is_preset THEN
        RAISE EXCEPTION 'vehicle type % cannot become or stop being a preset', OLD.code USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_allocation_whole_carton(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_allocation_whole_carton() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    row_package UUID;
    row_on_hand INTEGER;
BEGIN
    SELECT stock_package_id, on_hand INTO row_package, row_on_hand
      FROM inventory.stock_item WHERE id = NEW.stock_item_id;
    IF FOUND AND row_package IS NOT NULL AND NEW.quantity <> row_on_hand THEN
        RAISE EXCEPTION 'allocation % holds % of a carton row holding %; a carton is allocated whole', NEW.id,
            NEW.quantity, row_on_hand USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_cycle_count_line(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_cycle_count_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM inventory.cycle_count c
          JOIN warehouse.storage_location s ON s.warehouse_id = c.warehouse_id
         WHERE c.id = NEW.cycle_count_id AND s.location_code = NEW.location_code) THEN
        RAISE EXCEPTION 'location % is not in the warehouse being counted', NEW.location_code
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_cycle_count_line_carton(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_cycle_count_line_carton() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    standard INTEGER;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.stock_package_id IS NOT DISTINCT FROM OLD.stock_package_id
       AND NEW.expected_qty IS NOT DISTINCT FROM OLD.expected_qty
       AND NEW.counted_qty IS NOT DISTINCT FROM OLD.counted_qty THEN
        RETURN NEW;
    END IF;
    IF NEW.stock_package_id IS NULL THEN
        RAISE EXCEPTION 'count line % names no carton; a count states cartons present or not found', NEW.id
            USING ERRCODE = 'check_violation';
    END IF;
    -- BR-12: at most 500 cartons on one count, lines found on the shelf included. The count row is locked by every
    -- writer of its lines (CycleCountRepository.findByIdForUpdate), so the tally cannot race.
    IF TG_OP = 'INSERT'
       AND (SELECT count(*) FROM inventory.cycle_count_line WHERE cycle_count_id = NEW.cycle_count_id) >= 500 THEN
        RAISE EXCEPTION 'count % already has 500 lines; kltn-docs 20 BR-12 allows no more', NEW.cycle_count_id
            USING ERRCODE = 'check_violation';
    END IF;
    SELECT nominal_qty INTO standard FROM inventory.stock_package WHERE id = NEW.stock_package_id;
    IF NOT FOUND THEN
        RETURN NEW; -- the foreign key reports it
    END IF;
    IF NEW.expected_qty NOT IN (0, standard) OR NEW.counted_qty NOT IN (0, standard) THEN
        RAISE EXCEPTION 'count line % records % expected and % found of a carton of %; a carton is counted whole',
            NEW.id, NEW.expected_qty, NEW.counted_qty, standard USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: FUNCTION check_cycle_count_line_carton(); Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON FUNCTION inventory.check_cycle_count_line_carton() IS 'kltn-docs 20 §4.2, BR-14: a count line written since V20261113000300 names a carton and records it whole (0 or its standard count, booked and found). Lines of the history keep what they say.';

--
-- Name: check_document_stock_package(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_document_stock_package() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    pkg_sku      VARCHAR(64);
    pkg_location VARCHAR(64);
    pkg_status   VARCHAR(16);
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.stock_package_id IS NOT DISTINCT FROM OLD.stock_package_id
       AND NEW.sku IS NOT DISTINCT FROM OLD.sku AND NEW.location_code IS NOT DISTINCT FROM OLD.location_code THEN
        RETURN NEW;
    END IF;
    SELECT i.sku, p.location_code, p.status INTO pkg_sku, pkg_location, pkg_status
      FROM inventory.stock_package p JOIN inventory.inventory_items i ON i.id = p.inventory_item_id
     WHERE p.id = NEW.stock_package_id;
    IF NOT FOUND THEN
        RETURN NEW; -- the foreign key reports it
    END IF;
    IF pkg_sku <> NEW.sku THEN
        RAISE EXCEPTION '% names a carton of %, not %', TG_TABLE_NAME, pkg_sku, NEW.sku
            USING ERRCODE = 'check_violation';
    END IF;
    IF pkg_location <> NEW.location_code THEN
        RAISE EXCEPTION '% at % names a carton at %', TG_TABLE_NAME, NEW.location_code, pkg_location
            USING ERRCODE = 'check_violation';
    END IF;
    IF pkg_status NOT IN ('IN_STOCK', 'LOST') THEN
        RAISE EXCEPTION '% names a carton that is %', TG_TABLE_NAME, pkg_status
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_receivable_item(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_receivable_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    item inventory.inventory_items%ROWTYPE;
BEGIN
    SELECT * INTO item FROM inventory.inventory_items WHERE id = NEW.inventory_item_id;
    IF item.weight_kg IS NULL OR item.length_cm IS NULL OR item.width_cm IS NULL OR item.height_cm IS NULL THEN
        RAISE EXCEPTION 'inventory item % has no weight/dimensions yet; complete it before receiving (BR-03)', item.sku
            USING ERRCODE = 'check_violation';
    END IF;
    IF nullif(btrim(NEW.lot_number), '') IS NULL THEN
        RAISE EXCEPTION 'inventory item % is lot-tracked; the receipt line needs a lot number', item.sku
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_sku_reservation_covered(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_sku_reservation_covered() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    free BIGINT;
    held BIGINT;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(NEW.sku, 701));
    SELECT COALESCE(SUM(on_hand - reserved), 0) INTO free
      FROM inventory.stock_item WHERE sku = NEW.sku AND status = 'AVAILABLE';
    SELECT COALESCE(SUM(quantity), 0) INTO held
      FROM inventory.stock_reservation WHERE sku = NEW.sku AND stock_item_id IS NULL AND status = 'HELD';
    IF held > free THEN
        RAISE EXCEPTION 'SKU reservations of % (%) exceed its unheld available stock (%)', NEW.sku, held, free
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.warehouse_code IS NOT NULL THEN
        SELECT COALESCE(SUM(on_hand - reserved), 0) INTO free
          FROM inventory.stock_item
         WHERE sku = NEW.sku AND status = 'AVAILABLE' AND split_part(location_code, '-', 1) = NEW.warehouse_code;
        SELECT COALESCE(SUM(quantity), 0) INTO held
          FROM inventory.stock_reservation
         WHERE sku = NEW.sku AND stock_item_id IS NULL AND status = 'HELD' AND warehouse_code = NEW.warehouse_code;
        IF held > free THEN
            RAISE EXCEPTION 'SKU reservations of % at % (%) exceed its unheld available stock there (%) (20 BR-17)',
                NEW.sku, NEW.warehouse_code, held, free USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NULL;
END
$$;

--
-- Name: check_staging_movement(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_staging_movement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- A count or an adjustment only writes a staging area down (out of it), never up: the place it may touch is the
    -- one it takes from. Every other line touches both of its places.
    touched TEXT[] := CASE WHEN NEW.movement_type IN ('ADJUSTMENT', 'COUNT_CORRECTION')
                           THEN ARRAY[NEW.to_location_code]
                           ELSE ARRAY[NEW.from_location_code, NEW.to_location_code] END;
BEGIN
    IF NOT ((NEW.movement_type = 'MOVE' AND NEW.reference_type = 'PICK_LINE') OR NEW.movement_type = 'PICK')
       AND EXISTS (SELECT 1
                     FROM warehouse.area a
                     JOIN warehouse.storage_location l ON l.id = a.location_id
                    WHERE a.type = 'STAGING'
                      AND l.location_code = ANY (touched)) THEN
        RAISE EXCEPTION 'a % (reference %) cannot % staging area %: stock enters it only by picking, and leaves it by '
            'picking or a write-down (kltn-docs 11 BR-09, 20 BR-20)', NEW.movement_type, NEW.reference_type,
            CASE WHEN NEW.movement_type IN ('ADJUSTMENT', 'COUNT_CORRECTION') THEN 'add to' ELSE 'touch' END,
            coalesce(NEW.to_location_code, NEW.from_location_code) USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_stock_adjustment_whole_carton(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_stock_adjustment_whole_carton() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    standard INTEGER;
BEGIN
    IF NEW.reason_code = 'COUNT_VARIANCE' AND NEW.stock_package_id IS NULL THEN
        RAISE EXCEPTION 'adjustment % is a count variance of no carton; a count states cartons', NEW.adjustment_number
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.stock_package_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF NEW.reason_code NOT IN ('DAMAGED', 'LOST', 'FOUND', 'DATA_CORRECTION', 'OTHER', 'COUNT_VARIANCE') THEN
        RAISE EXCEPTION 'adjustment % of a carton gives reason %; kltn-docs 20 BR-04 lists six', NEW.adjustment_number,
            NEW.reason_code USING ERRCODE = 'check_violation';
    END IF;
    SELECT nominal_qty INTO standard FROM inventory.stock_package WHERE id = NEW.stock_package_id;
    IF FOUND AND abs(NEW.quantity_delta) <> standard THEN
        RAISE EXCEPTION 'adjustment % moves % of a carton of %; a carton is adjusted whole', NEW.adjustment_number,
            NEW.quantity_delta, standard USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: FUNCTION check_stock_adjustment_whole_carton(); Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON FUNCTION inventory.check_stock_adjustment_whole_carton() IS 'kltn-docs 20 §4.3, BR-04, BR-14: an adjustment asked since V20261113000300 writes a carton off whole or restocks it whole, for one of the six reasons; a count variance names its carton. On INSERT only: pending adjustments of the history are decided as they were asked.';

--
-- Name: check_stock_item_package(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_stock_item_package() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.stock_package_id IS NOT NULL THEN
        PERFORM inventory.check_stock_package_contents(NEW.stock_package_id);
    END IF;
    IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.stock_package_id IS NOT NULL
       AND (TG_OP = 'DELETE' OR OLD.stock_package_id IS DISTINCT FROM NEW.stock_package_id) THEN
        PERFORM inventory.check_stock_package_contents(OLD.stock_package_id);
    END IF;
    RETURN NULL;
END
$$;

--
-- Name: check_stock_lot_production_order(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_stock_lot_production_order() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM ordering.production_order p
                     JOIN ordering.production_order_line l ON l.production_order_id = p.id
                    WHERE p.id = NEW.production_order_id AND p.code = NEW.production_order_code AND l.sku = NEW.sku) THEN
        RAISE EXCEPTION 'stock lot %: production order % makes no %', NEW.id, NEW.production_order_code, NEW.sku
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_stock_movement_manual_move(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_stock_movement_manual_move() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    held_lpn VARCHAR(30);
BEGIN
    SELECT p.lpn INTO held_lpn
      FROM inventory.stock_package p
     WHERE p.id = NEW.from_stock_package_id
       AND EXISTS (SELECT 1 FROM inventory.stock_item s WHERE s.stock_package_id = p.id AND s.reserved > 0);
    IF FOUND THEN
        RAISE EXCEPTION 'stock package % is held for an order; it is not moved by hand', held_lpn
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_stock_movement_package(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_stock_movement_package() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    side_package UUID;
    pkg_sku      VARCHAR(64);
    pkg_location VARCHAR(64);
BEGIN
    FOREACH side_package IN ARRAY ARRAY[NEW.from_stock_package_id, NEW.to_stock_package_id] LOOP
        CONTINUE WHEN side_package IS NULL;
        SELECT i.sku, p.location_code INTO pkg_sku, pkg_location
          FROM inventory.stock_package p JOIN inventory.inventory_items i ON i.id = p.inventory_item_id
         WHERE p.id = side_package;
        CONTINUE WHEN NOT FOUND; -- the foreign key reports it
        IF pkg_sku <> NEW.sku THEN
            RAISE EXCEPTION 'a % movement names a stock package of %', NEW.sku, pkg_sku
                USING ERRCODE = 'check_violation';
        END IF;
        IF pkg_location IS DISTINCT FROM NEW.from_location_code
           AND pkg_location IS DISTINCT FROM NEW.to_location_code THEN
            RAISE EXCEPTION 'a movement from % to % names a stock package at %', NEW.from_location_code,
                NEW.to_location_code, pkg_location USING ERRCODE = 'check_violation';
        END IF;
    END LOOP;
    RETURN NEW;
END
$$;

--
-- Name: check_stock_package_contents(uuid); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_stock_package_contents(package_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    pkg       inventory.stock_package%ROWTYPE;
    item_sku  VARCHAR(64);
    wrong_sku INTEGER;
    elsewhere INTEGER;
    lots      INTEGER;
    held      BIGINT;
BEGIN
    SELECT * INTO pkg FROM inventory.stock_package WHERE id = package_id;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    SELECT sku INTO item_sku FROM inventory.inventory_items WHERE id = pkg.inventory_item_id;

    SELECT count(*) FILTER (WHERE s.sku <> item_sku),
           count(*) FILTER (WHERE s.on_hand > 0 AND s.location_code <> pkg.location_code),
           count(DISTINCT s.lot_number) FILTER (WHERE s.on_hand > 0),
           COALESCE(sum(s.on_hand), 0)
      INTO wrong_sku, elsewhere, lots, held
      FROM inventory.stock_item s
     WHERE s.stock_package_id = package_id;

    IF wrong_sku > 0 THEN
        RAISE EXCEPTION 'stock package % holds stock of another SKU than %', pkg.lpn, item_sku
            USING ERRCODE = 'check_violation';
    END IF;
    IF elsewhere > 0 THEN
        RAISE EXCEPTION 'stock package % is at % but some of its stock is not', pkg.lpn, pkg.location_code
            USING ERRCODE = 'check_violation';
    END IF;
    IF lots > 1 THEN
        RAISE EXCEPTION 'stock package % holds more than one lot', pkg.lpn USING ERRCODE = 'check_violation';
    END IF;
    IF pkg.status = 'IN_STOCK' AND held <> pkg.received_qty THEN
        RAISE EXCEPTION 'stock package % was counted in at % but holds %; a carton in stock is whole', pkg.lpn,
            pkg.received_qty, held USING ERRCODE = 'check_violation';
    END IF;
    IF pkg.status <> 'IN_STOCK' AND held > 0 THEN
        RAISE EXCEPTION 'stock package % is % but holds %', pkg.lpn, pkg.status, held
            USING ERRCODE = 'check_violation';
    END IF;
END
$$;

--
-- Name: FUNCTION check_stock_package_contents(package_id uuid); Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON FUNCTION inventory.check_stock_package_contents(package_id uuid) IS 'A stock package and its stock row agree: its SKU, its place, one lot, and exactly its count while IN_STOCK, nothing otherwise. Run at commit by the constraint triggers.';

--
-- Name: check_stock_package_created(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_stock_package_created() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    unit inventory.uom_conversions%ROWTYPE;
BEGIN
    IF NEW.status NOT IN ('RECEIVING', 'IN_STOCK') THEN
        RAISE EXCEPTION 'stock package % is created RECEIVING or IN_STOCK, not %', NEW.lpn, NEW.status
            USING ERRCODE = 'check_violation';
    END IF;
    PERFORM pg_advisory_xact_lock_shared(inventory.unit_lock_key(NEW.uom_conversion_id));
    SELECT * INTO unit FROM inventory.uom_conversions WHERE id = NEW.uom_conversion_id;
    IF NOT FOUND THEN
        RETURN NEW; -- fk_stock_package_unit reports it
    END IF;
    IF unit.inventory_item_id <> NEW.inventory_item_id THEN
        RAISE EXCEPTION 'stock package %: unit % is not a unit of its item', NEW.lpn, unit.unit_of_measure
            USING ERRCODE = 'check_violation';
    END IF;
    IF unit.is_base THEN
        RAISE EXCEPTION 'stock package % must be made in a packing unit, not the base unit %', NEW.lpn,
            unit.unit_of_measure USING ERRCODE = 'check_violation';
    END IF;
    IF NOT unit.active AND NOT EXISTS (SELECT 1 FROM procurement.goods_receipt_lines
                                        WHERE id = NEW.goods_receipt_line_id
                                          AND uom_conversion_id = NEW.uom_conversion_id) THEN
        RAISE EXCEPTION 'stock package %: unit % is retired; only goods received in it are still packed in it',
            NEW.lpn, unit.unit_of_measure USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.nominal_qty <> unit.factor THEN
        RAISE EXCEPTION 'stock package % holds % per %, not %', NEW.lpn, unit.factor, unit.unit_of_measure,
            NEW.nominal_qty USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_stock_package_fits_bin(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_stock_package_fits_bin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    c_length   NUMERIC;
    c_width    NUMERIC;
    c_height   NUMERIC;
    c_turnable BOOLEAN;
    b_width    NUMERIC;
    b_length   NUMERIC;
    b_height   NUMERIC;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.location_code IS NOT DISTINCT FROM OLD.location_code THEN
        RETURN NEW;
    END IF;
    SELECT b.width, b.length, lv.usable_height
      INTO b_width, b_length, b_height
      FROM warehouse.storage_location l
      JOIN warehouse.bin b ON b.location_id = l.id
      JOIN warehouse.shelf_level lv ON lv.id = b.level_id
     WHERE l.location_code = NEW.location_code;
    IF NOT FOUND THEN
        RETURN NEW;  -- an area, or a code the foreign keys of the stock rows will judge
    END IF;
    SELECT u.length_cm / 100, u.width_cm / 100, u.height_cm / 100, i.rotatable
      INTO c_length, c_width, c_height, c_turnable
      FROM inventory.uom_conversions u
      JOIN inventory.inventory_items i ON i.id = NEW.inventory_item_id
     WHERE u.id = NEW.uom_conversion_id;
    IF c_length IS NULL OR c_width IS NULL OR c_height IS NULL THEN
        RETURN NEW;  -- not fully measured: nothing to judge it by
    END IF;
    IF b_height IS NOT NULL AND c_height > b_height THEN
        RAISE EXCEPTION 'Carton % is taller than the clear height of bin %', NEW.lpn, NEW.location_code
            USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_stock_package_fits_bin';
    END IF;
    IF (c_length <= b_length AND c_width <= b_width)
        OR (c_turnable AND c_width <= b_length AND c_length <= b_width) THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'Carton % does not fit bin %', NEW.lpn, NEW.location_code
        USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_stock_package_fits_bin';
END;
$$;

--
-- Name: FUNCTION check_stock_package_fits_bin(); Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON FUNCTION inventory.check_stock_package_fits_bin() IS 'kltn-docs 06 BR-01, 11 BR-10: a carton coming into a bin fits it dimension by dimension, turned on the horizontal when its item is rotatable. The service (CartonFit) checks first; this is the last line.';

--
-- Name: check_stock_package_receipt_line(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_stock_package_receipt_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM procurement.goods_receipt_lines
                    WHERE id = NEW.goods_receipt_line_id AND inventory_item_id = NEW.inventory_item_id) THEN
        RAISE EXCEPTION 'stock package % names a receipt line of another item', NEW.lpn
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_stock_package_rows(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_stock_package_rows() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM inventory.check_stock_package_contents(NEW.id);
    RETURN NULL;
END
$$;

--
-- Name: check_stock_package_transition(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_stock_package_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
           (OLD.status = 'RECEIVING' AND NEW.status IN ('IN_STOCK', 'VOID'))
        OR (OLD.status = 'IN_STOCK' AND NEW.status IN ('CONSUMED', 'LOST'))
        OR (OLD.status = 'CONSUMED' AND NEW.status = 'IN_STOCK')
        OR (OLD.status = 'LOST' AND NEW.status = 'IN_STOCK')) THEN
        RAISE EXCEPTION 'stock package % cannot go from % to %', NEW.lpn, OLD.status, NEW.status
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.received_qty IS DISTINCT FROM OLD.received_qty AND OLD.status <> 'RECEIVING' THEN
        RAISE EXCEPTION 'stock package % was counted in at %; a later difference is an adjustment', NEW.lpn,
            OLD.received_qty USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: FUNCTION check_stock_package_transition(); Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON FUNCTION inventory.check_stock_package_transition() IS 'Carton lifecycle (kltn-docs 20 §5.5): RECEIVING->IN_STOCK|VOID, IN_STOCK->CONSUMED|LOST, CONSUMED|LOST->IN_STOCK; counted only while RECEIVING. The standard count is ck_stock_package_standard_count.';

--
-- Name: check_stock_reservation_sku(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_stock_reservation_sku() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    item_sku   VARCHAR(64);
    parent     inventory.stock_reservation%ROWTYPE;
BEGIN
    IF NEW.stock_item_id IS NOT NULL THEN
        SELECT sku INTO item_sku FROM inventory.stock_item WHERE id = NEW.stock_item_id;
        IF NEW.sku IS NULL THEN
            NEW.sku := item_sku;
        ELSIF NEW.sku IS DISTINCT FROM item_sku THEN
            RAISE EXCEPTION 'reservation % holds % but stock item % is %', NEW.id, NEW.sku, NEW.stock_item_id, item_sku
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    IF NEW.allocated_from_id IS NOT NULL THEN
        SELECT * INTO parent FROM inventory.stock_reservation WHERE id = NEW.allocated_from_id;
        IF parent.sku IS DISTINCT FROM NEW.sku OR parent.order_id IS DISTINCT FROM NEW.order_id THEN
            RAISE EXCEPTION 'allocation % must hold the SKU of reservation % for the same order', NEW.id,
                NEW.allocated_from_id USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_stock_reservation_warehouse(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.check_stock_reservation_warehouse() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_warehouse VARCHAR;
    item_location    VARCHAR;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.warehouse_code IS DISTINCT FROM OLD.warehouse_code THEN
        RAISE EXCEPTION 'reservation %: the warehouse it is held at does not change (20 BR-17)', NEW.id
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.allocated_from_id IS NOT NULL AND NEW.stock_item_id IS NOT NULL THEN
        SELECT r.warehouse_code INTO parent_warehouse FROM inventory.stock_reservation r
         WHERE r.id = NEW.allocated_from_id;
        IF parent_warehouse IS NOT NULL THEN
            SELECT s.location_code INTO item_location FROM inventory.stock_item s WHERE s.id = NEW.stock_item_id;
            IF split_part(item_location, '-', 1) <> parent_warehouse THEN
                RAISE EXCEPTION 'allocation %: reservation % is held at %, the stock is at % (20 BR-17)', NEW.id,
                    NEW.allocated_from_id, parent_warehouse, item_location USING ERRCODE = 'check_violation';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: create_base_uom(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.create_base_uom() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO inventory.uom_conversions (id, inventory_item_id, unit_of_measure, factor, is_base,
                                           default_purchase, created_by)
    VALUES (gen_random_uuid(), NEW.id, NEW.unit_of_measure, 1, TRUE, TRUE, NEW.created_by);
    RETURN NEW;
END $$;

--
-- Name: create_variant_item(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.create_variant_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO inventory.inventory_items(id,sku,created_by)
    VALUES (gen_random_uuid(),NEW.sku,NEW.created_by) ON CONFLICT (sku) DO NOTHING;
    RETURN NEW;
END $$;

--
-- Name: enforce_sku_policy(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.enforce_sku_policy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Holds and consumption lock individual rows in id order. Taking a SKU-wide lock for them would invert that order
    -- when two reservations span different rows of the same SKU: nothing here concerns a row that only shrinks.
    IF TG_OP = 'UPDATE' AND NEW.sku IS NOT DISTINCT FROM OLD.sku
       AND NEW.received_at IS NOT DISTINCT FROM OLD.received_at
       AND NEW.lot_number IS NOT DISTINCT FROM OLD.lot_number
       AND NEW.on_hand <= OLD.on_hand THEN
        RETURN NEW;
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(NEW.sku, 701));
    IF TG_OP = 'UPDATE' THEN
        IF NEW.sku IS DISTINCT FROM OLD.sku OR NEW.received_at IS DISTINCT FROM OLD.received_at
           OR NEW.lot_number IS DISTINCT FROM OLD.lot_number THEN
            RAISE EXCEPTION 'Receipt identity is immutable; reconcile via a new stock layer' USING ERRCODE = '23514';
        END IF;
        IF NEW.on_hand <= OLD.on_hand THEN
            RETURN NEW;
        END IF;
        -- First in, first out (01 BR-17): replenishment is a new layer, or FIFO loses the age of the incoming units.
        -- Units of this very receipt moved in from another place (identity unchanged, checked just above) are not
        -- replenishment: the application names the row it merges into for that one statement.
        IF current_setting('stockflow.same_receipt_merge', true) IS DISTINCT FROM NEW.id::text THEN
            RAISE EXCEPTION 'FIFO replenishment requires a new receipt layer' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF NEW.on_hand = 0 THEN
        RETURN NEW;
    END IF;
    -- Every SKU is lot-tracked (01 BR-17): live stock carries its lot.
    IF nullif(btrim(NEW.lot_number), '') IS NULL THEN
        RAISE EXCEPTION 'Stock of % needs a lot number: every SKU is lot-tracked', NEW.sku USING ERRCODE = '23514';
    END IF;
    IF NEW.received_at > clock_timestamp() + interval '1 minute' THEN
        RAISE EXCEPTION 'Invalid receipt date' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: FUNCTION enforce_sku_policy(); Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON FUNCTION inventory.enforce_sku_policy() IS 'The one stock policy of every SKU (kltn-docs 01 BR-17, team plan 5-5): live stock carries a lot, a row keeps its receipt identity, a layer grows only by its own receipt (stockflow.same_receipt_merge), no receipt time in the future. No serial numbers.';

--
-- Name: follow_base_uom(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.follow_base_uom() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE inventory.uom_conversions
    SET unit_of_measure = NEW.unit_of_measure, version = version + 1, last_modified_at = NOW()
    WHERE inventory_item_id = NEW.id AND is_base AND unit_of_measure <> NEW.unit_of_measure;
    RETURN NEW;
END $$;

--
-- Name: guard_item_sku_rename(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_item_sku_rename() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.sku IS NOT DISTINCT FROM OLD.sku THEN RETURN NEW; END IF;
    -- The old parent disappears only during its FK cascade; direct item reassignment is refused.
    IF EXISTS (SELECT 1 FROM product.variants WHERE sku = OLD.sku)
       OR NOT EXISTS (SELECT 1 FROM product.variants WHERE sku = NEW.sku AND status = 'DRAFT')
       OR inventory.item_in_use(OLD.id, OLD.sku) THEN
        RAISE EXCEPTION 'Only an unused DRAFT variant can rename its inventory SKU'
            USING ERRCODE = '23514';
    END IF;
    NEW.version := OLD.version + 1;
    NEW.last_modified_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END $$;

--
-- Name: guard_unit_in_use_change(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.guard_unit_in_use_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT pg_try_advisory_xact_lock(inventory.unit_lock_key(OLD.id)) THEN
        RAISE EXCEPTION 'unit % (factor %) is being written onto a document; declare a new unit and retire this one (BR-10)',
            OLD.unit_of_measure, OLD.factor USING ERRCODE = 'check_violation';
    END IF;
    IF inventory.unit_in_use(OLD.id) THEN
        RAISE EXCEPTION 'unit % (factor %) is used by a document; declare a new unit and retire this one (BR-10)',
            OLD.unit_of_measure, OLD.factor USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: item_in_use(uuid, character varying); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.item_in_use(p_item_id uuid, p_sku character varying) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (SELECT 1 FROM inventory.stock_item WHERE sku = p_sku)
        OR EXISTS (SELECT 1 FROM inventory.stock_movement WHERE sku = p_sku)
        OR EXISTS (SELECT 1 FROM inventory.stock_adjustment WHERE sku = p_sku)
        OR EXISTS (SELECT 1 FROM inventory.cycle_count_line WHERE sku = p_sku)
        OR EXISTS (SELECT 1 FROM inventory.stock_package WHERE inventory_item_id = p_item_id)
        OR EXISTS (SELECT 1 FROM warehouse.putaway_task WHERE sku = p_sku)
        OR EXISTS (SELECT 1 FROM warehouse.move_task WHERE sku = p_sku)
        OR EXISTS (SELECT 1 FROM fulfillment.pick_line WHERE sku = p_sku)
        OR EXISTS (SELECT 1 FROM procurement.goods_receipt_lines WHERE inventory_item_id = p_item_id)
        OR EXISTS (SELECT 1 FROM ordering.production_order_line WHERE sku = p_sku)
        OR EXISTS (SELECT 1 FROM catalog.customer_price WHERE sku = p_sku)
        OR EXISTS (SELECT 1 FROM ordering.quote_line WHERE blank_sku = p_sku OR sku = p_sku)
        OR EXISTS (SELECT 1 FROM inventory.stock_reservation WHERE sku = p_sku)
        OR EXISTS (SELECT 1 FROM inventory.stock_lot WHERE sku = p_sku)
$$;

--
-- Name: FUNCTION item_in_use(p_item_id uuid, p_sku character varying); Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON FUNCTION inventory.item_in_use(p_item_id uuid, p_sku character varying) IS 'Whether a document uses this inventory item: such an item is neither renamed nor deleted. Stock alerts do not count (they follow the item).';

--
-- Name: refuse_new_expired_adjustment(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.refuse_new_expired_adjustment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.reason_code = 'EXPIRED' AND (TG_OP = 'INSERT' OR OLD.reason_code IS DISTINCT FROM 'EXPIRED') THEN
        RAISE EXCEPTION 'stock adjustment % cannot be for EXPIRED stock: stock has no expiry date (20 BR-13)', NEW.id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: refuse_new_expired_stock(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.refuse_new_expired_stock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'EXPIRED' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'EXPIRED') THEN
        RAISE EXCEPTION 'stock item % cannot become EXPIRED: stock has no expiry date (20 BR-13)', NEW.id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: resolve_stock_item_lot(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.resolve_stock_item_lot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    lot inventory.stock_lot%ROWTYPE;
BEGIN
    IF NEW.lot_id IS NULL THEN
        SELECT id INTO NEW.lot_id FROM inventory.stock_lot l
         WHERE l.sku = NEW.sku AND l.lot_number IS NOT DISTINCT FROM NEW.lot_number
           AND l.received_at IS NOT DISTINCT FROM NEW.received_at
         ORDER BY l.created_at, l.id LIMIT 1;
        IF NEW.lot_id IS NULL THEN
            NEW.lot_id := gen_random_uuid();
            INSERT INTO inventory.stock_lot (id, sku, lot_number, received_at, origin_type, created_at, created_by)
            VALUES (NEW.lot_id, NEW.sku, NEW.lot_number, NEW.received_at, 'UNTRACED', NOW(), NEW.created_by);
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP = 'INSERT' OR NEW.lot_id IS DISTINCT FROM OLD.lot_id THEN
        SELECT * INTO lot FROM inventory.stock_lot WHERE id = NEW.lot_id;
        IF lot.sku IS DISTINCT FROM NEW.sku OR lot.lot_number IS DISTINCT FROM NEW.lot_number THEN
            RAISE EXCEPTION 'stock item % (%, lot %) cannot belong to lot % (%, lot %)', NEW.id, NEW.sku,
                NEW.lot_number, NEW.lot_id, lot.sku, lot.lot_number USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: resolve_stock_movement_lot(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.resolve_stock_movement_lot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    lots UUID[];
BEGIN
    IF NEW.lot_id IS NULL THEN
        SELECT array_agg(DISTINCT lot_id) INTO lots FROM inventory.stock_item
         WHERE sku = NEW.sku AND lot_number IS NOT DISTINCT FROM NEW.lot_number AND lot_id IS NOT NULL
           AND location_code IN (NEW.from_location_code, NEW.to_location_code);
        IF array_length(lots, 1) = 1 THEN
            NEW.lot_id := lots[1];
        END IF;
    ELSE
        IF NOT EXISTS (SELECT 1 FROM inventory.stock_lot l WHERE l.id = NEW.lot_id AND l.sku = NEW.sku
                         AND l.lot_number IS NOT DISTINCT FROM NEW.lot_number) THEN
            RAISE EXCEPTION 'ledger line % moves % lot % but names lot %', NEW.id, NEW.sku, NEW.lot_number,
                NEW.lot_id USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: snapshot_order_number(); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.snapshot_order_number() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.order_id IS NOT NULL AND NEW.order_number IS NULL THEN
        SELECT order_number INTO NEW.order_number FROM ordering.customer_order WHERE id = NEW.order_id;
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: unit_in_use(uuid); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.unit_in_use(p_uom_conversion_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (SELECT 1 FROM inventory.stock_package WHERE uom_conversion_id = p_uom_conversion_id)
        OR EXISTS (SELECT 1 FROM procurement.goods_receipt_lines WHERE uom_conversion_id = p_uom_conversion_id)
        OR EXISTS (SELECT 1 FROM ordering.quote_line WHERE uom_conversion_id = p_uom_conversion_id)
        OR EXISTS (SELECT 1 FROM ordering.order_line WHERE uom_conversion_id = p_uom_conversion_id)
$$;

--
-- Name: FUNCTION unit_in_use(p_uom_conversion_id uuid); Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON FUNCTION inventory.unit_in_use(p_uom_conversion_id uuid) IS 'Whether a document counts in this unit: such a unit keeps its factor and is retired, never deleted (BR-10).';

--
-- Name: unit_lock_key(uuid); Type: FUNCTION; Schema: inventory; Owner: -
--

CREATE FUNCTION inventory.unit_lock_key(p_uom_conversion_id uuid) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT hashtextextended(p_uom_conversion_id::text, 703)
$$;

--
-- Name: check_delay_alert(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_delay_alert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    owner UUID;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.id IS DISTINCT FROM OLD.id OR NEW.type IS DISTINCT FROM OLD.type
            OR NEW.production_order_id IS DISTINCT FROM OLD.production_order_id
            OR NEW.delivery_batch_id IS DISTINCT FROM OLD.delivery_batch_id
            OR NEW.sales_order_id IS DISTINCT FROM OLD.sales_order_id OR NEW.opened_at IS DISTINCT FROM OLD.opened_at THEN
            RAISE EXCEPTION 'delay alert %: what it is about does not change', OLD.id USING ERRCODE = 'check_violation';
        END IF;
        IF OLD.closed_at IS NOT NULL AND NEW.closed_at IS DISTINCT FROM OLD.closed_at THEN
            RAISE EXCEPTION 'delay alert %: closed once, never reopened', OLD.id USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.production_order_id IS NOT NULL THEN
        SELECT p.sales_order_id INTO owner FROM ordering.production_order p WHERE p.id = NEW.production_order_id;
    ELSE
        SELECT c.order_id INTO owner
          FROM ordering.delivery_batch b JOIN ordering.sales_contract c ON c.id = b.contract_id
         WHERE b.id = NEW.delivery_batch_id;
    END IF;
    IF owner IS DISTINCT FROM NEW.sales_order_id THEN
        RAISE EXCEPTION 'delay alert %: its subject is of its sales order', NEW.id USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_delivery_batch_hold_reservation(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_delivery_batch_hold_reservation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM inventory.stock_reservation r
                    WHERE r.id = NEW.reservation_id AND r.order_id = NEW.order_id) THEN
        RAISE EXCEPTION 'hold % is not a reservation of order %', NEW.reservation_id, NEW.order_id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END
$$;

--
-- Name: check_delivery_batch_of_order(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_delivery_batch_of_order() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    the_batch   RECORD;
    the_order   RECORD;
    previous      UUID;
    bad_seq       INTEGER;
    wanted_units  BIGINT;
    shipped_units BIGINT;
    starts_on    DATE;
BEGIN
    IF NEW.delivery_batch_id IS NULL THEN
        RETURN NEW;
    END IF;
    SELECT b.id, b.seq, b.window_start, b.window_end, c.order_id, c.status AS contract_status, c.contract_number
      INTO the_batch
      FROM ordering.delivery_batch b JOIN ordering.sales_contract c ON c.id = b.contract_id
     WHERE b.id = NEW.delivery_batch_id;
    IF NOT FOUND OR the_batch.order_id <> NEW.order_id OR the_batch.contract_status NOT IN ('SIGNED', 'COMPLETED') THEN
        RAISE EXCEPTION 'delivery batch % is not of the signed contract of order %', NEW.delivery_batch_id, NEW.order_id
            USING ERRCODE = 'check_violation';
    END IF;

    IF TG_TABLE_NAME = 'delivery_batch_hold' THEN
        -- A hold stands for a line the batch carries.
        IF NOT EXISTS (SELECT 1 FROM ordering.delivery_batch_line l
                        WHERE l.delivery_batch_id = NEW.delivery_batch_id AND l.order_line_id = NEW.order_line_id) THEN
            RAISE EXCEPTION 'hold % of order %: batch % carries no cartons of line %', NEW.reservation_id, NEW.order_id,
                the_batch.seq, NEW.order_line_id USING ERRCODE = 'check_violation';
        END IF;
    ELSIF TG_TABLE_NAME = 'delivery_batch_release' THEN
        SELECT o.shipping_warehouse_id INTO the_order FROM ordering.customer_order o WHERE o.id = NEW.order_id;
        IF NEW.seq <> the_batch.seq THEN
            RAISE EXCEPTION 'release of batch %: seq % is not the batch''s %', NEW.delivery_batch_id, NEW.seq,
                the_batch.seq USING ERRCODE = 'check_violation';
        END IF;
        IF the_order.shipping_warehouse_id IS DISTINCT FROM NEW.warehouse_id THEN
            RAISE EXCEPTION 'release of batch % of order %: not at the order''s shipping warehouse (17 BR-22)',
                the_batch.seq, NEW.order_id USING ERRCODE = 'check_violation';
        END IF;
        IF the_batch.seq > 1 THEN
            SELECT b.id INTO previous FROM ordering.delivery_batch b
              JOIN ordering.sales_contract c ON c.id = b.contract_id
             WHERE c.order_id = NEW.order_id AND c.status IN ('SIGNED', 'COMPLETED') AND b.seq = the_batch.seq - 1;
            -- Handed over in full: the units of its shipments not returned reach the units it carries (its cartons in
            -- pieces, a line without a carton count as one piece per carton) - as DeliveryBatchService.nextToRelease.
            SELECT coalesce(sum(l.cartons * coalesce(ol.units_per_carton, 1)), 0) INTO wanted_units
              FROM ordering.delivery_batch_line l JOIN ordering.order_line ol ON ol.id = l.order_line_id
             WHERE l.delivery_batch_id = previous;
            SELECT coalesce(sum(sl.quantity), 0) INTO shipped_units
              FROM ordering.order_shipment s JOIN ordering.order_shipment_line sl ON sl.shipment_id = s.id
             WHERE s.delivery_batch_id = previous AND s.status <> 'RETURNED';
            IF NOT EXISTS (SELECT 1 FROM ordering.delivery_batch_release r WHERE r.delivery_batch_id = previous)
                OR shipped_units < wanted_units OR wanted_units = 0 THEN
                RAISE EXCEPTION 'batch % of order % is released once batch % is handed over in full (% of % units, 17 BR-29)',
                    the_batch.seq, NEW.order_id, the_batch.seq - 1, shipped_units, wanted_units
                    USING ERRCODE = 'check_violation';
            END IF;
        END IF;
    ELSIF TG_TABLE_NAME = 'order_shipment' THEN
        IF NOT EXISTS (SELECT 1 FROM ordering.delivery_batch_release r WHERE r.delivery_batch_id = NEW.delivery_batch_id)
        THEN
            RAISE EXCEPTION 'a shipment of order % names batch %, which is not released', NEW.order_id, the_batch.seq
                USING ERRCODE = 'check_violation';
        END IF;
        -- 09 BR-04: not handed over before the first day of the batch's window in force.
        starts_on := coalesce((SELECT w.new_window_start FROM ordering.delivery_batch_window_change w
                                   WHERE w.delivery_batch_id = NEW.delivery_batch_id
                                   ORDER BY w.changed_at DESC, w.id DESC LIMIT 1), the_batch.window_start);
        IF TG_OP = 'INSERT' AND starts_on IS NOT NULL
            AND (NEW.handed_over_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date < starts_on THEN
            RAISE EXCEPTION 'batch % of order % is handed over from %, its window in force (09 BR-04)', the_batch.seq,
                NEW.order_id, starts_on USING ERRCODE = 'check_violation';
        END IF;
    ELSIF TG_TABLE_NAME = 'delivery_batch_window_change' THEN
        IF EXISTS (SELECT 1 FROM ordering.order_shipment s WHERE s.delivery_batch_id = NEW.delivery_batch_id) THEN
            RAISE EXCEPTION 'batch % of order %: a carton of it was handed over; its window no longer moves (17 BR-28)',
                the_batch.seq, NEW.order_id USING ERRCODE = 'check_violation';
        END IF;
        -- The customer's consent in a chat message: one the customer sent, in their own conversation, about this order
        -- or about none (DeliveryBatchService.check, through chat's ConsentMessages).
        IF NEW.evidence_message_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM chat.message m
              JOIN chat.conversation v ON v.id = m.conversation_id
              JOIN ordering.customer_order o ON o.id = NEW.order_id
             WHERE m.id = NEW.evidence_message_id AND m.sender_type = 'CUSTOMER' AND v.customer_id = o.customer_id
               AND (v.order_id IS NULL OR v.order_id = NEW.order_id)) THEN
            RAISE EXCEPTION 'order %: chat message % is not the customer''s own word in their conversation (17 BR-28)',
                NEW.order_id, NEW.evidence_message_id USING ERRCODE = 'check_violation';
        END IF;
        -- The windows in force after this change, batch by batch: none starts before the batch before it.
        WITH in_force AS (
            SELECT b.seq,
                   coalesce(CASE WHEN b.id = NEW.delivery_batch_id THEN NEW.new_window_start END,
                            (SELECT w.new_window_start FROM ordering.delivery_batch_window_change w
                              WHERE w.delivery_batch_id = b.id ORDER BY w.changed_at DESC, w.id DESC LIMIT 1),
                            b.window_start) AS window_start
              FROM ordering.delivery_batch b
              JOIN ordering.sales_contract c ON c.id = b.contract_id
             WHERE c.order_id = NEW.order_id AND c.status IN ('SIGNED', 'COMPLETED')
        )
        SELECT later.seq INTO bad_seq
          FROM in_force later JOIN in_force earlier ON earlier.seq = later.seq - 1
         WHERE later.window_start < earlier.window_start
         LIMIT 1;
        IF bad_seq IS NOT NULL THEN
            RAISE EXCEPTION 'order %: batch % would start before batch % (17 BR-28); move the later batches too',
                NEW.order_id, bad_seq, bad_seq - 1 USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_line_carton_unit(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_line_carton_unit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    unit      inventory.uom_conversions%ROWTYPE;
    item_sku  VARCHAR(64);
    new_unit  BOOLEAN;
    owner     UUID;
    customer  UUID;
BEGIN
    PERFORM pg_advisory_xact_lock_shared(inventory.unit_lock_key(NEW.uom_conversion_id));
    SELECT * INTO unit FROM inventory.uom_conversions WHERE id = NEW.uom_conversion_id;
    IF NOT FOUND THEN
        RETURN NEW; -- the foreign key reports it
    END IF;
    SELECT i.sku INTO item_sku FROM inventory.inventory_items i WHERE i.id = unit.inventory_item_id;
    IF item_sku IS DISTINCT FROM NEW.sku THEN
        RAISE EXCEPTION '% line: unit % is not a unit of %', TG_TABLE_NAME, unit.unit_of_measure, NEW.sku
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.units_per_carton <> unit.factor THEN
        RAISE EXCEPTION '% line: % holds % pieces, not %', TG_TABLE_NAME, unit.unit_of_measure, unit.factor,
            NEW.units_per_carton USING ERRCODE = 'check_violation';
    END IF;
    -- 14 BR-04: the customer's own SKU.
    SELECT v.owner_customer_id INTO owner FROM product.variants v WHERE v.sku = NEW.sku;
    IF TG_TABLE_NAME = 'quote_line' THEN
        SELECT q.customer_id INTO customer FROM ordering.quote q WHERE q.id = NEW.quote_id;
    ELSE
        SELECT o.customer_id INTO customer FROM ordering.customer_order o WHERE o.id = NEW.order_id;
    END IF;
    IF owner IS DISTINCT FROM customer THEN
        RAISE EXCEPTION '% line: % is not a SKU of customer % (14 BR-04)', TG_TABLE_NAME, NEW.sku, customer
            USING ERRCODE = 'check_violation';
    END IF;
    -- A new quote line takes an active unit; an order line copies the unit of its accepted quote line.
    IF TG_TABLE_NAME = 'order_line' THEN
        new_unit := FALSE;
    ELSIF TG_OP = 'INSERT' THEN
        new_unit := TRUE;
    ELSE
        new_unit := NEW.uom_conversion_id IS DISTINCT FROM OLD.uom_conversion_id;
    END IF;
    IF new_unit AND NOT unit.active THEN
        RAISE EXCEPTION '% line: unit % of % is retired', TG_TABLE_NAME, unit.unit_of_measure, NEW.sku
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_order_contract(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_order_contract() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    the_order    UUID;
    order_status VARCHAR(32);
    order_number VARCHAR(32);
    contract     VARCHAR(16);
BEGIN
    -- IF, not CASE: PL/pgSQL resolves every field a CASE names on NEW, and each table has only one of the two.
    IF TG_TABLE_NAME = 'customer_order' THEN
        the_order := NEW.id;
    ELSE
        the_order := NEW.order_id;
    END IF;
    SELECT o.status, o.order_number INTO order_status, order_number
      FROM ordering.customer_order o WHERE o.id = the_order;
    SELECT c.status INTO contract
      FROM ordering.sales_contract c WHERE c.order_id = the_order AND c.status <> 'CANCELLED';
    IF contract IN ('SIGNED', 'COMPLETED') AND order_status IN ('DRAFT', 'PENDING_CONTRACT') THEN
        RAISE EXCEPTION 'Order % has a signed contract, but is still % (14 §4.3 step 15)', order_number,
            order_status USING ERRCODE = 'check_violation';
    END IF;
    IF order_status = 'PENDING_CONTRACT' AND contract IS DISTINCT FROM 'SENT' THEN
        RAISE EXCEPTION 'Order % waits for its contract to be signed, but has no contract sent (14 §5.3)',
            order_number USING ERRCODE = 'check_violation';
    END IF;
    IF contract = 'SENT' AND order_status <> 'PENDING_CONTRACT' THEN
        RAISE EXCEPTION 'Order % has a contract sent for signing, but is % (14 §5.3)', order_number, order_status
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END
$$;

--
-- Name: check_production_order(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_production_order() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    sales_order RECORD;
    batch_order UUID;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'production order %: production orders are kept', OLD.code USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'INSERT' AND NEW.status <> 'DRAFT' THEN
        RAISE EXCEPTION 'production order %: drawn up as a draft (17 §5.3)', NEW.code USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'UPDATE' THEN
        IF NEW.code IS DISTINCT FROM OLD.code OR NEW.sales_order_id IS DISTINCT FROM OLD.sales_order_id
            OR NEW.delivery_batch_id IS DISTINCT FROM OLD.delivery_batch_id
            OR NEW.customer_id IS DISTINCT FROM OLD.customer_id OR NEW.drawn_up_by IS DISTINCT FROM OLD.drawn_up_by THEN
            RAISE EXCEPTION 'production order %: what it is for does not change', OLD.code
                USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.status <> OLD.status AND NOT EXISTS (SELECT 1 FROM ordering.production_order_status_transition t
                                                     WHERE t.from_status = OLD.status AND t.to_status = NEW.status) THEN
            RAISE EXCEPTION 'production order %: % -> % is not a transition (17 §5.3)', OLD.code, OLD.status,
                NEW.status USING ERRCODE = 'check_violation';
        END IF;
        -- What the coordinator edits is settled once it is submitted (B33; the warehouse moves with the order's
        -- shipping warehouse while it is not yet sent).
        IF OLD.status NOT IN ('DRAFT') AND (NEW.producer_id IS DISTINCT FROM OLD.producer_id
            OR NEW.need_by_date IS DISTINCT FROM OLD.need_by_date
            OR NEW.sample_approval_required IS DISTINCT FROM OLD.sample_approval_required
            OR NEW.sample_waiver_reason IS DISTINCT FROM OLD.sample_waiver_reason
            OR NEW.unit_price IS DISTINCT FROM OLD.unit_price OR NEW.note IS DISTINCT FROM OLD.note) THEN
            RAISE EXCEPTION 'production order %: a % production order is not edited', OLD.code, OLD.status
                USING ERRCODE = 'check_violation';
        END IF;
        -- Who approved and sent it, and when, is written once (BR-23).
        IF OLD.approved_at IS NOT NULL AND (NEW.approved_by IS DISTINCT FROM OLD.approved_by
            OR NEW.approved_at IS DISTINCT FROM OLD.approved_at OR NEW.sent_at IS DISTINCT FROM OLD.sent_at
            OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at) THEN
            RAISE EXCEPTION 'production order %: its approval is kept as written', OLD.code
                USING ERRCODE = 'check_violation';
        END IF;
        IF OLD.status NOT IN ('DRAFT', 'PENDING_APPROVAL')
            AND NEW.receiving_warehouse_id IS DISTINCT FROM OLD.receiving_warehouse_id THEN
            RAISE EXCEPTION 'production order %: sent, it is received where it was sent to', OLD.code
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    SELECT o.customer_id, o.shipping_warehouse_id, o.contract_signed_at INTO sales_order
      FROM ordering.customer_order o WHERE o.id = NEW.sales_order_id;
    SELECT c.order_id INTO batch_order
      FROM ordering.delivery_batch b JOIN ordering.sales_contract c ON c.id = b.contract_id
     WHERE b.id = NEW.delivery_batch_id;
    IF sales_order.contract_signed_at IS NULL OR batch_order IS DISTINCT FROM NEW.sales_order_id THEN
        RAISE EXCEPTION 'production order %: for a delivery batch of a signed order''s contract (17 BR-05)', NEW.code
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.customer_id IS DISTINCT FROM sales_order.customer_id THEN
        RAISE EXCEPTION 'production order %: for its order''s customer', NEW.code USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status IN ('DRAFT', 'PENDING_APPROVAL')
        AND NEW.receiving_warehouse_id IS DISTINCT FROM sales_order.shipping_warehouse_id THEN
        RAISE EXCEPTION 'production order %: received at its order''s shipping warehouse (17 BR-22)', NEW.code
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_production_order_draft_receipts(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_production_order_draft_receipts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    drafts TEXT;
BEGIN
    SELECT string_agg(r.receipt_number, ', ' ORDER BY r.receipt_number) INTO drafts
      FROM ordering.production_order_receipt r
     WHERE r.production_order_id = NEW.id AND r.status = 'DRAFT';
    IF drafts IS NOT NULL THEN
        RAISE EXCEPTION 'production order %: draft receipt(s) % are confirmed or cancelled first (03 edge cases)',
            NEW.code, drafts USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_production_order_has_lines(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_production_order_has_lines() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    the_order UUID;
BEGIN
    -- Separate statements: each table's row is read only by the branch for that table (PL/pgSQL plans every operand of
    -- one expression, and the production order has no production_order_id).
    IF TG_TABLE_NAME = 'production_order' THEN
        the_order := NEW.id;
    ELSE
        the_order := OLD.production_order_id;
    END IF;
    IF EXISTS (SELECT 1 FROM ordering.production_order p WHERE p.id = the_order)
        AND NOT EXISTS (SELECT 1 FROM ordering.production_order_line l WHERE l.production_order_id = the_order) THEN
        RAISE EXCEPTION 'production order %: it makes at least one line', the_order USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END;
$$;

--
-- Name: check_production_order_line(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_production_order_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    po          RECORD;
    line        RECORD;
BEGIN
    SELECT p.code, p.status, p.sales_order_id, p.delivery_batch_id INTO po FROM ordering.production_order p
     WHERE p.id = CASE WHEN TG_OP = 'DELETE' THEN OLD.production_order_id ELSE NEW.production_order_id END;
    IF TG_OP = 'DELETE' THEN
        IF po.status IS NOT NULL AND po.status <> 'DRAFT' THEN
            RAISE EXCEPTION 'production order %: a % production order keeps its lines', po.code, po.status
                USING ERRCODE = 'check_violation';
        END IF;
        RETURN OLD;
    END IF;
    IF TG_OP = 'UPDATE' AND po.status <> 'DRAFT' AND (NEW.order_line_id IS DISTINCT FROM OLD.order_line_id
        OR NEW.sku IS DISTINCT FROM OLD.sku OR NEW.cartons IS DISTINCT FROM OLD.cartons
        OR NEW.units_per_carton IS DISTINCT FROM OLD.units_per_carton
        OR NEW.design_snapshot_id IS DISTINCT FROM OLD.design_snapshot_id
        OR NEW.print_file_checksum IS DISTINCT FROM OLD.print_file_checksum
        OR NEW.packing_requirements IS DISTINCT FROM OLD.packing_requirements) THEN
        RAISE EXCEPTION 'production order %: a % production order''s lines are not edited', po.code, po.status
            USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'INSERT' AND po.status <> 'DRAFT' THEN
        RAISE EXCEPTION 'production order %: lines are drawn up while it is a draft', po.code
            USING ERRCODE = 'check_violation';
    END IF;
    SELECT l.order_id, l.sku, l.units_per_carton INTO line FROM ordering.order_line l WHERE l.id = NEW.order_line_id;
    IF line.order_id IS DISTINCT FROM po.sales_order_id OR line.sku IS DISTINCT FROM NEW.sku
        OR line.units_per_carton IS DISTINCT FROM NEW.units_per_carton THEN
        RAISE EXCEPTION 'production order %: a line is one of its order''s lines, with its SKU and carton (17 BR-05)',
            po.code USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ordering.delivery_batch_line b
                    WHERE b.delivery_batch_id = po.delivery_batch_id AND b.order_line_id = NEW.order_line_id
                      AND b.cartons >= NEW.cartons) THEN
        RAISE EXCEPTION 'production order %: a line is of its delivery batch, never above its cartons (17 BR-05)',
            po.code USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_production_order_receipt(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_production_order_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    receipt_status VARCHAR(16);
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'production order receipt %: kept', OLD.receipt_number USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'DRAFT' THEN
            RAISE EXCEPTION 'production order receipt %: registered as a draft', NEW.receipt_number
                USING ERRCODE = 'check_violation';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM procurement.goods_receipts g
                        WHERE g.id = NEW.goods_receipt_id AND g.production_order_id = NEW.production_order_id
                          AND g.receipt_number = NEW.receipt_number) THEN
            RAISE EXCEPTION 'receipt % is not a receipt against this production order', NEW.receipt_number
                USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.production_order_id IS DISTINCT FROM OLD.production_order_id
        OR NEW.goods_receipt_id IS DISTINCT FROM OLD.goods_receipt_id
        OR NEW.receipt_number IS DISTINCT FROM OLD.receipt_number OR NEW.opened_at IS DISTINCT FROM OLD.opened_at THEN
        RAISE EXCEPTION 'production order receipt %: what it registers does not change', OLD.receipt_number
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status THEN
        IF OLD.status <> 'DRAFT' THEN
            RAISE EXCEPTION 'production order receipt %: settled once, % already', OLD.receipt_number, OLD.status
                USING ERRCODE = 'check_violation';
        END IF;
        SELECT g.status INTO receipt_status FROM procurement.goods_receipts g WHERE g.id = NEW.goods_receipt_id;
        IF (NEW.status = 'CANCELLED') <> (receipt_status = 'CANCELLED')
            OR receipt_status IN ('DRAFT', 'PENDING_APPROVAL') THEN
            RAISE EXCEPTION 'production order receipt %: % while the receipt is %', OLD.receipt_number, NEW.status,
                receipt_status USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_production_order_sample(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_production_order_sample() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        RETURN NEW;
    END IF;
    IF NEW.status = 'SAMPLE_PENDING' AND NOT EXISTS (SELECT 1 FROM ordering.production_order_sample_round r
                                                      WHERE r.production_order_id = NEW.id AND r.round_no = 1) THEN
        RAISE EXCEPTION 'production order %: its sample is pending once round 1 is uploaded (17 §4.3 step 9)', NEW.code
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'IN_PRODUCTION' AND NEW.sample_approval_required THEN
        IF OLD.status <> 'SAMPLE_PENDING' THEN
            RAISE EXCEPTION 'production order %: with a print sample to approve, mass printing starts when the customer approves it (BR-24)',
                NEW.code USING ERRCODE = 'check_violation';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM ordering.production_order_sample_round r
                        WHERE r.production_order_id = NEW.id AND r.result = 'APPROVED') THEN
            RAISE EXCEPTION 'production order %: no round of its print sample is approved (BR-24)', NEW.code
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_production_order_sample_media(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_production_order_sample_media() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    answered TEXT;
    po_status TEXT;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'sample media %: kept as uploaded', OLD.id USING ERRCODE = 'check_violation';
    END IF;
    SELECT r.result, p.status INTO answered, po_status
      FROM ordering.production_order_sample_round r JOIN ordering.production_order p ON p.id = r.production_order_id
     WHERE r.id = NEW.sample_round_id;
    -- Round 1's photos come with it, while the production order is still ACCEPTED; later ones while it is pending.
    IF po_status NOT IN ('ACCEPTED', 'SAMPLE_PENDING') THEN
        RAISE EXCEPTION 'sample round %: photos and videos are added while its sample is pending', NEW.sample_round_id
            USING ERRCODE = 'check_violation';
    END IF;
    IF answered IS NOT NULL THEN
        RAISE EXCEPTION 'sample round %: answered, its photos and videos are those the customer saw',
            NEW.sample_round_id USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_production_order_sample_round(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_production_order_sample_round() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    po       RECORD;
    previous TEXT;
    owner    UUID;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'sample round %: rounds are kept', OLD.id USING ERRCODE = 'check_violation';
    END IF;
    SELECT p.code, p.status, p.sample_approval_required, p.customer_id INTO po
      FROM ordering.production_order p WHERE p.id = NEW.production_order_id;
    IF TG_OP = 'INSERT' THEN
        IF NOT po.sample_approval_required THEN
            RAISE EXCEPTION 'production order %: it has no print sample to approve (BR-24)', po.code
                USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.result IS NOT NULL THEN
            RAISE EXCEPTION 'production order %: a round opens waiting for the customer', po.code
                USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.round_no = 1 AND po.status <> 'ACCEPTED' THEN
            RAISE EXCEPTION 'production order %: round 1 is uploaded once the producer accepted it (17 §5.3)', po.code
                USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.round_no > 1 THEN
            IF po.status <> 'SAMPLE_PENDING' THEN
                RAISE EXCEPTION 'production order %: a new round is opened while its sample is pending', po.code
                    USING ERRCODE = 'check_violation';
            END IF;
            SELECT r.result INTO previous FROM ordering.production_order_sample_round r
             WHERE r.production_order_id = NEW.production_order_id AND r.round_no = NEW.round_no - 1;
            IF previous IS DISTINCT FROM 'REPRINT_REQUESTED' THEN
                RAISE EXCEPTION 'production order %: round % follows a reprint request of the round before', po.code,
                    NEW.round_no USING ERRCODE = 'check_violation';
            END IF;
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.production_order_id IS DISTINCT FROM OLD.production_order_id
        OR NEW.round_no IS DISTINCT FROM OLD.round_no OR NEW.reprint_reason IS DISTINCT FROM OLD.reprint_reason
        OR NEW.opened_by IS DISTINCT FROM OLD.opened_by OR NEW.opened_at IS DISTINCT FROM OLD.opened_at THEN
        RAISE EXCEPTION 'production order %: what a sample round is does not change', po.code
            USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.result IS NOT NULL AND (NEW.result IS DISTINCT FROM OLD.result
        OR NEW.customer_note IS DISTINCT FROM OLD.customer_note OR NEW.answered_by IS DISTINCT FROM OLD.answered_by
        OR NEW.answered_at IS DISTINCT FROM OLD.answered_at
        OR NEW.physical_sample_sent_on IS DISTINCT FROM OLD.physical_sample_sent_on) THEN
        RAISE EXCEPTION 'production order %: round % is answered, once (13 BR-13)', po.code, OLD.round_no
            USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.result IS NULL AND NEW.physical_sample_sent_on IS DISTINCT FROM OLD.physical_sample_sent_on
        AND po.status <> 'SAMPLE_PENDING' THEN
        RAISE EXCEPTION 'production order %: a physical sample is recorded while its sample is pending', po.code
            USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.result IS NULL AND NEW.result IS NOT NULL THEN
        IF po.status <> 'SAMPLE_PENDING' THEN
            RAISE EXCEPTION 'production order %: its sample is answered while it is pending (13 BR-13)', po.code
                USING ERRCODE = 'check_violation';
        END IF;
        SELECT c.user_id INTO owner FROM customer.customer c WHERE c.id = po.customer_id;
        IF owner IS NULL OR NEW.answered_by IS DISTINCT FROM owner THEN
            RAISE EXCEPTION 'production order %: its sample is answered by the customer who owns it (13 BR-13)',
                po.code USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_production_order_sample_round_has_media(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_production_order_sample_round_has_media() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM ordering.production_order_sample_media m WHERE m.sample_round_id = NEW.id) THEN
        RAISE EXCEPTION 'sample round %: it shows at least one photo or video', NEW.id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END;
$$;

--
-- Name: check_production_order_slip_kept(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_production_order_slip_kept() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'production order slip %: a slip is kept as it was sent', OLD.production_order_id
        USING ERRCODE = 'check_violation';
END;
$$;

--
-- Name: check_production_order_slip_sent(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_production_order_slip_sent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM ordering.production_order p
                    WHERE p.id = NEW.production_order_id AND p.sent_at IS NOT NULL) THEN
        RAISE EXCEPTION 'production order slip %: only a sent production order has a slip', NEW.production_order_id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END;
$$;

--
-- Name: check_quote_line_kinds(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_quote_line_kinds() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    the_quote UUID;
BEGIN
    the_quote := CASE WHEN TG_OP = 'DELETE' THEN OLD.quote_id ELSE NEW.quote_id END;
    IF EXISTS (SELECT 1 FROM ordering.quote_line WHERE quote_id = the_quote AND sku IS NULL)
        AND EXISTS (SELECT 1 FROM ordering.quote_line WHERE quote_id = the_quote AND sku IS NOT NULL) THEN
        RAISE EXCEPTION 'quote %: its lines are all cartons of the customer''s SKUs or all drafted before (QD-16)',
            the_quote USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END
$$;

--
-- Name: check_quote_plate_fee(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_quote_plate_fee() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    the_quote UUID;
BEGIN
    the_quote := CASE WHEN TG_OP = 'DELETE' THEN OLD.quote_id ELSE NEW.quote_id END;
    IF EXISTS (SELECT 1 FROM ordering.quote_fee_line f
                WHERE f.quote_id = the_quote AND f.kind = 'PLATE_FEE'
                  AND NOT EXISTS (SELECT 1 FROM ordering.quote_line l WHERE l.quote_id = f.quote_id AND l.sku = f.sku))
    THEN
        RAISE EXCEPTION 'quote %: a plate fee is for a SKU on the quote (14 BR-17)', the_quote
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END
$$;

--
-- Name: check_return_request_goods_receipt(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_return_request_goods_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.goods_receipt_id IS NOT NULL
        AND NEW.goods_receipt_id IS DISTINCT FROM OLD.goods_receipt_id THEN
        RAISE EXCEPTION 'return %: the receipt that brought its goods does not change', OLD.rma_number
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.goods_receipt_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM procurement.goods_receipts g
             WHERE g.id = NEW.goods_receipt_id AND g.receipt_type = 'RETURN' AND g.status = 'CLOSED'
               AND g.return_request_id = NEW.id) THEN
        RAISE EXCEPTION 'return %: its goods come back on a confirmed return receipt against it (03 §4.2)',
            NEW.rma_number USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_return_request_line(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_return_request_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    deliverable    INTEGER;
    claimed        INTEGER;
    open_elsewhere BOOLEAN;
BEGIN
    SELECT l.quantity - l.cancelled_quantity INTO deliverable
      FROM ordering.order_line l
      JOIN ordering.return_request r ON r.order_id = l.order_id
     WHERE l.id = NEW.order_line_id AND r.id = NEW.return_request_id
       FOR UPDATE OF l;
    IF deliverable IS NULL THEN
        RAISE EXCEPTION 'return line must be a line of the returned order' USING ERRCODE = 'check_violation';
    END IF;
    -- ReturnLine.claimedUnits: asked for, approved while open, refunded once resolved.
    SELECT COALESCE(SUM(CASE
                            WHEN r.status = 'REQUESTED' THEN x.quantity
                            WHEN r.status IN ('AWAITING_RETURN', 'RECEIVED', 'SETTLEMENT_PENDING')
                                THEN x.approved_quantity
                            WHEN r.status = 'RESOLVED' THEN x.refund_quantity
                            ELSE 0 END), 0),
           COALESCE(bool_or(r.status IN ('REQUESTED', 'AWAITING_RETURN', 'RECEIVED', 'SETTLEMENT_PENDING')), FALSE)
      INTO claimed, open_elsewhere
      FROM ordering.return_request_line x
      JOIN ordering.return_request r ON r.id = x.return_request_id
     WHERE x.order_line_id = NEW.order_line_id AND x.return_request_id <> NEW.return_request_id;
    IF TG_OP = 'INSERT' AND open_elsewhere THEN
        RAISE EXCEPTION 'order line % already has an open return', NEW.order_line_id
            USING ERRCODE = 'check_violation';
    END IF;
    -- BR-RMA-002: goods printed to the customer's design come back for a named defect only (ReturnReason.isNamedFault).
    IF TG_OP = 'INSERT' AND NEW.custom_printed AND EXISTS (SELECT 1 FROM ordering.return_request r
                                                           WHERE r.id = NEW.return_request_id
                                                             AND r.reason_code IN ('CHANGED_MIND', 'OTHER')) THEN
        RAISE EXCEPTION 'printed goods come back for a named defect only (BR-RMA-002)' USING ERRCODE = 'check_violation';
    END IF;
    IF claimed + COALESCE(NEW.approved_quantity, NEW.quantity) > deliverable THEN
        RAISE EXCEPTION 'would claim % of the % unit(s) delivered',
            claimed + COALESCE(NEW.approved_quantity, NEW.quantity), deliverable USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_return_request_refund(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_return_request_refund() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    r         RECORD;
    lines     NUMERIC;
    return_id UUID;
BEGIN
    -- One function for both tables: each branch names only the columns its own table has.
    IF TG_TABLE_NAME = 'return_request_line' THEN
        return_id := NEW.return_request_id;
    ELSE
        return_id := NEW.id;
    END IF;
    SELECT id, rma_number, status, settlement_amount INTO r FROM ordering.return_request WHERE id = return_id;
    IF NOT FOUND OR r.status NOT IN ('SETTLEMENT_PENDING', 'RESOLVED') THEN
        RETURN NULL;
    END IF;
    SELECT COALESCE(SUM(refund_amount), 0) INTO lines FROM ordering.return_request_line WHERE return_request_id = r.id;
    IF lines <> r.settlement_amount THEN
        RAISE EXCEPTION 'return %: its lines refund % but it settles %', r.rma_number, lines, r.settlement_amount
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END
$$;

--
-- Name: check_sales_contract_draft(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_sales_contract_draft() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    the_contract UUID;
    the_status   VARCHAR(16);
    the_number   VARCHAR(40);
BEGIN
    IF TG_TABLE_NAME = 'delivery_batch_line' THEN
        SELECT b.contract_id INTO the_contract FROM ordering.delivery_batch b
         WHERE b.id = CASE WHEN TG_OP = 'DELETE' THEN OLD.delivery_batch_id ELSE NEW.delivery_batch_id END;
    ELSE
        the_contract := CASE WHEN TG_OP = 'DELETE' THEN OLD.contract_id ELSE NEW.contract_id END;
    END IF;
    SELECT c.status, c.contract_number INTO the_status, the_number
      FROM ordering.sales_contract c WHERE c.id = the_contract;
    IF FOUND AND the_status <> 'DRAFT' THEN
        RAISE EXCEPTION 'sales contract %: the schedule and payment plan of a % contract do not change (14 BR-14)',
            the_number, the_status USING ERRCODE = 'check_violation';
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;

--
-- Name: check_sales_contract_terms(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_sales_contract_terms() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    the_contract UUID;
    contract     RECORD;
    order_total  NUMERIC;
    planned      NUMERIC;
    batches      INTEGER;
    installments INTEGER;
    bad          TEXT;
    credit_ok    BOOLEAN;
    sending      BOOLEAN := false;
BEGIN
    IF TG_TABLE_NAME = 'sales_contract' THEN
        the_contract := NEW.id;
        -- Only the contract's own row has a status: PL/pgSQL does not stop at the first false operand.
        IF TG_OP = 'UPDATE' THEN
            sending := OLD.status = 'DRAFT' AND NEW.status = 'SENT';
        END IF;
    ELSIF TG_TABLE_NAME = 'delivery_batch_line' THEN
        SELECT b.contract_id INTO the_contract FROM ordering.delivery_batch b
         WHERE b.id = CASE WHEN TG_OP = 'DELETE' THEN OLD.delivery_batch_id ELSE NEW.delivery_batch_id END;
    ELSE
        the_contract := CASE WHEN TG_OP = 'DELETE' THEN OLD.contract_id ELSE NEW.contract_id END;
    END IF;
    SELECT c.id, c.contract_number, c.order_id, c.status INTO contract
      FROM ordering.sales_contract c WHERE c.id = the_contract;
    IF NOT FOUND OR contract.status = 'CANCELLED' THEN
        -- Gone with its contract, or cancelled: a cancelled contract binds nobody.
        RETURN NULL;
    END IF;

    -- BR-23: batches 1..n, each with cartons; the cartons of every order line over the batches make the line; a batch
    -- starts no earlier than the one before.
    SELECT count(*) INTO batches FROM ordering.delivery_batch b WHERE b.contract_id = the_contract;
    IF batches = 0 OR batches <> (SELECT max(seq) FROM ordering.delivery_batch WHERE contract_id = the_contract) THEN
        RAISE EXCEPTION 'sales contract %: the delivery batches are numbered 1 to n, at least one (14 BR-23)',
            contract.contract_number USING ERRCODE = 'check_violation';
    END IF;
    SELECT string_agg(b.seq::text, ', ') INTO bad FROM ordering.delivery_batch b
     WHERE b.contract_id = the_contract
       AND NOT EXISTS (SELECT 1 FROM ordering.delivery_batch_line l WHERE l.delivery_batch_id = b.id);
    IF bad IS NOT NULL THEN
        RAISE EXCEPTION 'sales contract %: delivery batch % carries no cartons (14 BR-23)', contract.contract_number,
            bad USING ERRCODE = 'check_violation';
    END IF;
    SELECT string_agg(ol.sku, ', ') INTO bad
      FROM ordering.order_line ol
      LEFT JOIN (SELECT l.order_line_id, sum(l.cartons) AS cartons
                   FROM ordering.delivery_batch_line l
                   JOIN ordering.delivery_batch b ON b.id = l.delivery_batch_id
                  WHERE b.contract_id = the_contract
                  GROUP BY l.order_line_id) s ON s.order_line_id = ol.id
     WHERE ol.order_id = contract.order_id
       AND ol.cartons IS DISTINCT FROM s.cartons;
    IF bad IS NOT NULL THEN
        RAISE EXCEPTION 'sales contract %: the cartons over the batches are not the order''s for % (14 BR-23)',
            contract.contract_number, bad USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM ordering.delivery_batch_line l
                 JOIN ordering.delivery_batch b ON b.id = l.delivery_batch_id
                 JOIN ordering.order_line ol ON ol.id = l.order_line_id
                WHERE b.contract_id = the_contract AND ol.order_id <> contract.order_id) THEN
        RAISE EXCEPTION 'sales contract %: a delivery batch names a line of another order', contract.contract_number
            USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM ordering.delivery_batch b
                 JOIN ordering.delivery_batch p ON p.contract_id = b.contract_id AND p.seq = b.seq - 1
                WHERE b.contract_id = the_contract AND b.window_start < p.window_start) THEN
        RAISE EXCEPTION 'sales contract %: a delivery batch starts before the one before it (14 BR-23)',
            contract.contract_number USING ERRCODE = 'check_violation';
    END IF;
    IF contract.status <> 'DRAFT' AND EXISTS (SELECT 1 FROM ordering.delivery_batch b
                                                WHERE b.contract_id = the_contract AND b.window_start IS NULL) THEN
        RAISE EXCEPTION 'sales contract %: every delivery batch has its window once sent (14 BR-23)',
            contract.contract_number USING ERRCODE = 'check_violation';
    END IF;

    -- BR-13: installments 1..n adding up to the order's total with tax; a batch named is one of this contract's.
    SELECT count(*), coalesce(sum(i.amount), 0) INTO installments, planned
      FROM ordering.contract_payment_installment i WHERE i.contract_id = the_contract;
    SELECT o.total_amount INTO order_total FROM ordering.customer_order o WHERE o.id = contract.order_id;
    IF installments = 0
        OR installments <> (SELECT max(seq) FROM ordering.contract_payment_installment WHERE contract_id = the_contract)
    THEN
        RAISE EXCEPTION 'sales contract %: the installments are numbered 1 to n, at least one (14 BR-13)',
            contract.contract_number USING ERRCODE = 'check_violation';
    END IF;
    IF planned <> order_total THEN
        RAISE EXCEPTION 'sales contract %: the installments add up to %, the order''s total with tax is % (14 BR-13)',
            contract.contract_number, planned, order_total USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM ordering.contract_payment_installment i
                 JOIN ordering.delivery_batch b ON b.id = i.delivery_batch_id
                WHERE i.contract_id = the_contract AND b.contract_id <> the_contract) THEN
        RAISE EXCEPTION 'sales contract %: an installment names a delivery batch of another contract',
            contract.contract_number USING ERRCODE = 'check_violation';
    END IF;
    -- 15 BR-12: paying after delivery is credit, and only accounting grants credit. Checked while the plan can change,
    -- and when the contract is sent: the customer is offered no credit accounting took back meanwhile.
    IF (contract.status = 'DRAFT' OR sending)
        AND EXISTS (SELECT 1 FROM ordering.contract_payment_installment i
                     WHERE i.contract_id = the_contract AND i.milestone = 'AFTER_DELIVERY')
    THEN
        SELECT bool_or(cp.credit_limit > 0) INTO credit_ok
          FROM (SELECT p.credit_limit FROM customer.credit_profile p
                  JOIN ordering.customer_order o ON o.customer_id = p.customer_id
                 WHERE o.id = contract.order_id FOR SHARE OF p) AS cp;
        IF NOT coalesce(credit_ok, false) THEN
            RAISE EXCEPTION 'sales contract %: an installment after delivery needs credit accounting approved (15 BR-12)',
                contract.contract_number USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NULL;
END
$$;

--
-- Name: check_sales_contract_transition(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.check_sales_contract_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.contract_number IS DISTINCT FROM OLD.contract_number THEN
        RAISE EXCEPTION 'sales contract %: a contract keeps its number and stays with its order', OLD.contract_number
            USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.status <> 'DRAFT' AND (NEW.seller_name, NEW.seller_tax_code, NEW.seller_address, NEW.seller_representative,
            NEW.seller_representative_title, NEW.buyer_name, NEW.buyer_tax_code, NEW.buyer_address,
            NEW.buyer_representative, NEW.buyer_representative_title, NEW.free_sample_rounds, NEW.sent_at,
            NEW.sent_by, NEW.sent_document_key)
        IS DISTINCT FROM (OLD.seller_name, OLD.seller_tax_code, OLD.seller_address, OLD.seller_representative,
            OLD.seller_representative_title, OLD.buyer_name, OLD.buyer_tax_code, OLD.buyer_address,
            OLD.buyer_representative, OLD.buyer_representative_title, OLD.free_sample_rounds, OLD.sent_at,
            OLD.sent_by, OLD.sent_document_key)
    THEN
        RAISE EXCEPTION 'sales contract %: a % contract does not change (14 BR-14)', OLD.contract_number,
            OLD.status USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.status IN ('SIGNED', 'COMPLETED') AND (NEW.signed_on, NEW.signed_file_key, NEW.signed_file_name,
            NEW.signed_at, NEW.signed_by)
        IS DISTINCT FROM (OLD.signed_on, OLD.signed_file_key, OLD.signed_file_name, OLD.signed_at, OLD.signed_by)
    THEN
        RAISE EXCEPTION 'sales contract %: a % contract does not change (14 BR-14)', OLD.contract_number,
            OLD.status USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.status IN ('CANCELLED', 'COMPLETED') AND (NEW.cancelled_at, NEW.cancelled_by, NEW.cancellation_reason,
            NEW.completed_at)
        IS DISTINCT FROM (OLD.cancelled_at, OLD.cancelled_by, OLD.cancellation_reason, OLD.completed_at)
    THEN
        RAISE EXCEPTION 'sales contract %: a % contract does not change', OLD.contract_number, OLD.status
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = OLD.status THEN
        RETURN NEW;
    END IF;
    IF NOT ((OLD.status = 'DRAFT' AND NEW.status IN ('SENT', 'CANCELLED'))
         OR (OLD.status = 'SENT' AND NEW.status IN ('SIGNED', 'CANCELLED'))
         OR (OLD.status = 'SIGNED' AND NEW.status = 'COMPLETED')) THEN
        RAISE EXCEPTION 'sales contract %: % -> % is not a transition (14 §5.2)', OLD.contract_number, OLD.status,
            NEW.status USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: enforce_order_transition(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.enforce_order_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = OLD.status THEN
        RETURN NEW;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ordering.order_status_transition t
                    WHERE t.from_status = OLD.status AND t.to_status = NEW.status) THEN
        RAISE EXCEPTION 'Order % cannot move from % to %', OLD.order_number, OLD.status, NEW.status
            USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.status = 'ON_HOLD' AND NEW.status <> 'CANCELLED'
       AND NEW.status IS DISTINCT FROM OLD.status_before_hold
       AND NOT (OLD.hold_reason = 'CREDIT' AND NEW.status IN ('CONFIRMED', 'PENDING_PAYMENT')) THEN
        RAISE EXCEPTION 'Order % leaves its hold for %, not for % where it was held from', OLD.order_number,
            NEW.status, COALESCE(OLD.status_before_hold, 'a credit decision')
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: forbid_production_order_history_change(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.forbid_production_order_history_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'production order history is kept as written' USING ERRCODE = 'check_violation';
END;
$$;

--
-- Name: guard_order_label_lock(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.guard_order_label_lock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.first_labeled_at IS NULL THEN
        IF NEW.first_labeled_at IS NOT NULL AND NEW.status = 'ON_HOLD' THEN
            RAISE EXCEPTION 'tg_order_label_lock: order % is on hold; its first carton is labelled once the hold is '
                'resolved (kltn-docs 08 BR-04)', OLD.order_number
                USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_order_label_lock';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.first_labeled_at IS DISTINCT FROM OLD.first_labeled_at THEN
        RAISE EXCEPTION 'tg_order_label_lock: order % was first labelled at %; that does not change',
            OLD.order_number, OLD.first_labeled_at
            USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_order_label_lock';
    END IF;
    IF ROW(NEW.shipping_recipient_name, NEW.shipping_phone, NEW.shipping_line1, NEW.shipping_line2,
           NEW.shipping_ward_code, NEW.shipping_ward_name, NEW.shipping_province_code, NEW.shipping_province_name,
           NEW.shipping_country_code, NEW.shipping_postal_code)
       IS DISTINCT FROM
       ROW(OLD.shipping_recipient_name, OLD.shipping_phone, OLD.shipping_line1, OLD.shipping_line2,
           OLD.shipping_ward_code, OLD.shipping_ward_name, OLD.shipping_province_code, OLD.shipping_province_name,
           OLD.shipping_country_code, OLD.shipping_postal_code) THEN
        RAISE EXCEPTION 'tg_order_label_lock: order % has a labelled carton; its delivery address does not change '
            '(kltn-docs 17 BR-16)', OLD.order_number
            USING ERRCODE = 'check_violation', CONSTRAINT = 'tg_order_label_lock';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: keep_printing_started(); Type: FUNCTION; Schema: ordering; Owner: -
--

CREATE FUNCTION ordering.keep_printing_started() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.printing_started_at IS NOT NULL AND NEW.printing_started_at IS DISTINCT FROM OLD.printing_started_at THEN
        RAISE EXCEPTION 'Order %: printing started at %, and that stays (17 BR-11)', OLD.order_number,
            OLD.printing_started_at USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: assert_fee_item(uuid); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.assert_fee_item(installment uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    i RECORD;
BEGIN
    SELECT f.milestone, f.seq, f.contract_number INTO i FROM payment.installment f WHERE f.id = installment;
    IF NOT FOUND OR i.milestone <> 'CANCELLATION_FEE' THEN
        RETURN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM payment.order_settlement s WHERE s.fee_installment_id = installment) THEN
        RAISE EXCEPTION 'cancellation fee item % of contract %: no settlement owes it (15 §4.6 step 18)', i.seq,
            i.contract_number USING ERRCODE = 'check_violation';
    END IF;
END;
$$;

--
-- Name: assert_installment_paid(uuid); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.assert_installment_paid(installment uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    paid   NUMERIC;
    held   NUMERIC;
    seq    SMALLINT;
    number VARCHAR;
BEGIN
    SELECT i.paid_amount, i.seq, i.contract_number INTO held, seq, number FROM payment.installment i
     WHERE i.id = installment;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    SELECT COALESCE(SUM(l.amount), 0) INTO paid
      FROM payment.payment_receipt_line l
      JOIN payment.payment_receipt r ON r.id = l.receipt_id
     WHERE l.installment_id = installment AND r.status = 'RECORDED';
    IF paid <> held THEN
        RAISE EXCEPTION 'installment % of contract %: paid % on record, its recorded receipts pay % (15 §4.2 step 7)',
            seq, number, held, paid USING ERRCODE = 'check_violation';
    END IF;
END;
$$;

--
-- Name: assert_installment_reduced(uuid); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.assert_installment_reduced(installment uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    taken  NUMERIC;
    held   NUMERIC;
    seq    SMALLINT;
    number VARCHAR;
BEGIN
    SELECT i.reduced_amount, i.seq, i.contract_number INTO held, seq, number FROM payment.installment i
     WHERE i.id = installment;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    SELECT COALESCE(SUM(r.amount), 0) INTO taken FROM payment.installment_reduction r
     WHERE r.installment_id = installment;
    IF taken <> held THEN
        RAISE EXCEPTION 'installment % of contract %: % taken off on record, its reductions take % (15 §4.6 step 19)',
            seq, number, held, taken USING ERRCODE = 'check_violation';
    END IF;
END;
$$;

--
-- Name: assert_order_settlement(uuid); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.assert_order_settlement(settlement uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    s      RECORD;
    taken  NUMERIC;
    fee    RECORD;
    status VARCHAR;
BEGIN
    SELECT * INTO s FROM payment.order_settlement WHERE id = settlement;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    SELECT COALESCE(SUM(r.amount), 0) INTO taken FROM payment.installment_reduction r WHERE r.settlement_id = settlement;
    IF taken <> s.reduced_amount THEN
        RAISE EXCEPTION 'settlement of order %: % taken off on record, its reductions take %', s.order_number,
            s.reduced_amount, taken USING ERRCODE = 'check_violation';
    END IF;
    IF s.fee_installment_id IS NOT NULL THEN
        SELECT i.order_id, i.milestone, i.amount INTO fee FROM payment.installment i WHERE i.id = s.fee_installment_id;
        IF fee.order_id <> s.order_id OR fee.milestone <> 'CANCELLATION_FEE' OR fee.amount <> s.fee_owed_amount THEN
            RAISE EXCEPTION 'settlement of order %: its fee item owes the % the money did not cover (15 §4.6 step 18)',
                s.order_number, s.fee_owed_amount USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    IF s.kind = 'ORDER_CANCELLED' THEN
        SELECT o.status INTO status FROM ordering.customer_order o WHERE o.id = s.order_id;
        IF status <> 'CANCELLED' THEN
            RAISE EXCEPTION 'order % is %: only a cancelled order is settled as cancelled', s.order_number, status
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
END;
$$;

--
-- Name: assert_payment_receipt(uuid); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.assert_payment_receipt(receipt uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    total     NUMERIC;
    lines     BIGINT;
    recorded  NUMERIC;
    reference VARCHAR;
BEGIN
    SELECT r.amount, r.reference INTO recorded, reference FROM payment.payment_receipt r WHERE r.id = receipt;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    SELECT COALESCE(SUM(l.amount), 0), COUNT(*) INTO total, lines
      FROM payment.payment_receipt_line l WHERE l.receipt_id = receipt;
    IF lines = 0 OR total <> recorded THEN
        RAISE EXCEPTION 'payment receipt %: % recorded, its % line(s) add up to % (15 §3)', reference, recorded, lines,
            total USING ERRCODE = 'check_violation';
    END IF;
END;
$$;

--
-- Name: check_installment_matches_plan(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_installment_matches_plan() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    plan     RECORD;
    contract RECORD;
BEGIN
    IF NEW.contract_installment_id IS NULL THEN
        SELECT c.contract_number, c.status AS contract_status, c.order_id, o.customer_id, o.order_number, o.currency
          INTO contract
          FROM ordering.sales_contract c
          JOIN ordering.customer_order o ON o.id = c.order_id
         WHERE c.id = NEW.contract_id;
        IF NOT FOUND OR contract.contract_status NOT IN ('SIGNED', 'COMPLETED') THEN
            RAISE EXCEPTION 'cancellation fee item %: contract % is not a signed one (15 §4.6)', NEW.id, NEW.contract_id
                USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.order_id IS DISTINCT FROM contract.order_id OR NEW.customer_id IS DISTINCT FROM contract.customer_id
            OR NEW.contract_number IS DISTINCT FROM contract.contract_number
            OR NEW.order_number IS DISTINCT FROM contract.order_number OR NEW.currency IS DISTINCT FROM contract.currency
        THEN
            RAISE EXCEPTION 'cancellation fee item of contract %: it is that contract''s order''s, in its currency',
                contract.contract_number USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END IF;
    SELECT p.contract_id, p.seq, p.name, p.milestone, p.amount, p.due_days, p.delivery_batch_id, b.seq AS batch_seq,
           c.contract_number, c.status AS contract_status, c.order_id, o.customer_id, o.order_number, o.currency
      INTO plan
      FROM ordering.contract_payment_installment p
      JOIN ordering.sales_contract c ON c.id = p.contract_id
      JOIN ordering.customer_order o ON o.id = c.order_id
      LEFT JOIN ordering.delivery_batch b ON b.id = p.delivery_batch_id
     WHERE p.id = NEW.contract_installment_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'installment %: no plan row %', NEW.id, NEW.contract_installment_id
            USING ERRCODE = 'check_violation';
    END IF;
    IF plan.contract_status NOT IN ('SIGNED', 'COMPLETED') THEN
        RAISE EXCEPTION 'installment of contract %: the contract is %, installments come with its signature (15 §4.1)',
            plan.contract_number, plan.contract_status USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.contract_id IS DISTINCT FROM plan.contract_id OR NEW.order_id IS DISTINCT FROM plan.order_id
        OR NEW.customer_id IS DISTINCT FROM plan.customer_id OR NEW.contract_number IS DISTINCT FROM plan.contract_number
        OR NEW.order_number IS DISTINCT FROM plan.order_number OR NEW.currency IS DISTINCT FROM plan.currency
        OR NEW.seq IS DISTINCT FROM plan.seq OR NEW.name IS DISTINCT FROM plan.name
        OR NEW.milestone IS DISTINCT FROM plan.milestone OR NEW.amount IS DISTINCT FROM plan.amount
        OR NEW.due_days IS DISTINCT FROM plan.due_days OR NEW.delivery_batch_id IS DISTINCT FROM plan.delivery_batch_id
        OR NEW.delivery_batch_seq IS DISTINCT FROM plan.batch_seq THEN
        RAISE EXCEPTION 'installment % of contract %: it is the signed plan''s row, as signed (14 BR-14)', NEW.seq,
            plan.contract_number USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_installment_paid(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_installment_paid() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM payment.assert_installment_paid(NEW.id);
    RETURN NULL;
END;
$$;

--
-- Name: check_installment_reduction(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_installment_reduction() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    settlement  RECORD;
    installment RECORD;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'installment reduction %: kept as written', OLD.id USING ERRCODE = 'check_violation';
    END IF;
    SELECT s.kind, s.order_id, s.order_number INTO settlement FROM payment.order_settlement s
     WHERE s.id = NEW.settlement_id;
    SELECT i.order_id, i.milestone, i.seq INTO installment FROM payment.installment i WHERE i.id = NEW.installment_id;
    -- A closure of the rest, or goods returned and refunded (4D-3), takes off its own order's installments.
    IF settlement.kind NOT IN ('REMAINDER_CLOSED', 'GOODS_RETURNED') OR installment.order_id <> settlement.order_id
        OR installment.milestone = 'CANCELLATION_FEE' THEN
        RAISE EXCEPTION 'order %: a closure takes off its own order''s installments, never a fee item (15 §4.6 step 19)',
            settlement.order_number USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_installment_reduction_totals(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_installment_reduction_totals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM payment.assert_installment_reduced(NEW.installment_id);
    PERFORM payment.assert_order_settlement(NEW.settlement_id);
    RETURN NULL;
END;
$$;

--
-- Name: check_installment_settled(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_installment_settled() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM payment.assert_installment_reduced(NEW.id);
    IF TG_OP = 'INSERT' THEN
        PERFORM payment.assert_fee_item(NEW.id);
    END IF;
    RETURN NULL;
END;
$$;

--
-- Name: check_installment_transition(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_installment_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'installment % of contract %: installments are kept', OLD.seq, OLD.contract_number
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.contract_id IS DISTINCT FROM OLD.contract_id
        OR NEW.contract_installment_id IS DISTINCT FROM OLD.contract_installment_id
        OR NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
        OR NEW.contract_number IS DISTINCT FROM OLD.contract_number
        OR NEW.order_number IS DISTINCT FROM OLD.order_number OR NEW.seq IS DISTINCT FROM OLD.seq
        OR NEW.name IS DISTINCT FROM OLD.name OR NEW.milestone IS DISTINCT FROM OLD.milestone
        OR NEW.delivery_batch_id IS DISTINCT FROM OLD.delivery_batch_id
        OR NEW.delivery_batch_seq IS DISTINCT FROM OLD.delivery_batch_seq OR NEW.amount IS DISTINCT FROM OLD.amount
        OR NEW.currency IS DISTINCT FROM OLD.currency OR NEW.due_days IS DISTINCT FROM OLD.due_days THEN
        RAISE EXCEPTION 'installment % of contract %: what it is does not change (14 BR-14)', OLD.seq,
            OLD.contract_number USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.reduced_amount < OLD.reduced_amount THEN
        RAISE EXCEPTION 'installment % of contract %: what a closure took off is not given back (15 §4.6 step 19)',
            OLD.seq, OLD.contract_number USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.reached_at IS NOT NULL AND (NEW.reached_at IS DISTINCT FROM OLD.reached_at
                                       OR NEW.due_date IS DISTINCT FROM OLD.due_date) THEN
        RAISE EXCEPTION 'installment % of contract %: its milestone came on %; that does not change', OLD.seq,
            OLD.contract_number, OLD.reached_at USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.status = 'CANCELLED' THEN
        RAISE EXCEPTION 'installment % of contract %: a CANCELLED installment does not change', OLD.seq,
            OLD.contract_number USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
           (OLD.status = 'NOT_DUE' AND NEW.status IN ('DUE', 'PARTIALLY_PAID', 'PAID', 'CANCELLED'))
        OR (OLD.status = 'DUE' AND NEW.status IN ('PARTIALLY_PAID', 'PAID', 'OVERDUE', 'CANCELLED'))
        -- Back to DUE / NOT_DUE only by a receipt voided (15 §4.4 step 12).
        OR (OLD.status = 'PARTIALLY_PAID' AND NEW.status IN ('PAID', 'OVERDUE', 'CANCELLED', 'DUE', 'NOT_DUE'))
        OR (OLD.status = 'OVERDUE' AND NEW.status IN ('PAID', 'CANCELLED'))
        OR (OLD.status = 'PAID' AND NEW.status IN ('PARTIALLY_PAID', 'DUE', 'NOT_DUE', 'OVERDUE'))) THEN
        RAISE EXCEPTION 'installment % of contract %: % -> % is not a transition (15 §5.1)', OLD.seq,
            OLD.contract_number, OLD.status, NEW.status USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_order_settlement(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_order_settlement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    o         RECORD;
    collected NUMERIC;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'settlement % of order %: a settlement is kept as it was made', OLD.kind, OLD.order_number
            USING ERRCODE = 'check_violation';
    END IF;
    SELECT co.order_number, co.customer_id, co.currency, co.total_amount, co.closed_amount, co.printing_started_at,
           c.contract_number, c.status AS contract_status, c.order_id AS contract_order_id
      INTO o
      FROM ordering.customer_order co
      JOIN ordering.sales_contract c ON c.id = NEW.contract_id
     WHERE co.id = NEW.order_id;
    IF NOT FOUND OR o.contract_order_id <> NEW.order_id OR o.contract_status NOT IN ('SIGNED', 'COMPLETED') THEN
        RAISE EXCEPTION 'settlement of order %: contract % is not its signed one', NEW.order_number, NEW.contract_number
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.customer_id IS DISTINCT FROM o.customer_id OR NEW.order_number IS DISTINCT FROM o.order_number
        OR NEW.contract_number IS DISTINCT FROM o.contract_number OR NEW.currency IS DISTINCT FROM o.currency THEN
        RAISE EXCEPTION 'settlement of order %: it is that order''s, of its customer, in its currency', o.order_number
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.fee_amount > 0 AND o.printing_started_at IS NULL THEN
        RAISE EXCEPTION 'settlement of order %: no fee before mass printing started (17 BR-11)', o.order_number
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.kind = 'ORDER_CANCELLED' AND NEW.fee_amount > o.total_amount - o.closed_amount THEN
        RAISE EXCEPTION 'settlement of order %: a fee of % is above what the order is worth (17 §4.8 step 30)',
            o.order_number, NEW.fee_amount USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.kind = 'REMAINDER_CLOSED' AND NEW.fee_amount > NEW.closed_amount THEN
        RAISE EXCEPTION 'settlement of order %: a fee of % is above the goods closed (17 §4.8 step 33)',
            o.order_number, NEW.fee_amount USING ERRCODE = 'check_violation';
    END IF;
    -- 4D-3: a return's refund settles the return of this order whose refund was proposed at this value.
    IF NEW.kind = 'GOODS_RETURNED' AND NOT EXISTS (
            SELECT 1 FROM ordering.return_request r
             WHERE r.id = NEW.source_id AND r.order_id = NEW.order_id
               AND r.status IN ('SETTLEMENT_PENDING', 'RESOLVED') AND r.settlement_amount = NEW.closed_amount) THEN
        RAISE EXCEPTION 'settlement of order %: goods returned are settled for a return of the order whose refund is '
            'proposed at %', o.order_number, NEW.closed_amount USING ERRCODE = 'check_violation';
    END IF;
    SELECT COALESCE(SUM(i.paid_amount), 0) INTO collected
      FROM payment.installment i
     WHERE i.order_id = NEW.order_id AND i.milestone <> 'CANCELLATION_FEE';
    IF collected <> NEW.collected_amount THEN
        RAISE EXCEPTION 'settlement of order %: % collected on record, its installments were paid % (15 BR-14)',
            o.order_number, NEW.collected_amount, collected USING ERRCODE = 'check_violation';
    END IF;
    -- 15 BR-14: what the order's settlements make refundable, this one with them, never exceeds what was collected.
    IF NEW.refundable_amount + (SELECT COALESCE(SUM(s.refundable_amount), 0) FROM payment.order_settlement s
                                 WHERE s.order_id = NEW.order_id) > collected THEN
        RAISE EXCEPTION 'settlement of order %: more to refund than the % collected (15 BR-14)', o.order_number,
            collected USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_order_settlement_totals(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_order_settlement_totals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM payment.assert_order_settlement(NEW.id);
    RETURN NULL;
END;
$$;

--
-- Name: check_payment_receipt(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_payment_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    line RECORD;
BEGIN
    PERFORM payment.assert_payment_receipt(NEW.id);
    -- Voided, its lines no longer pay their installments: each must have been put back.
    FOR line IN SELECT l.installment_id FROM payment.payment_receipt_line l WHERE l.receipt_id = NEW.id LOOP
        PERFORM payment.assert_installment_paid(line.installment_id);
    END LOOP;
    RETURN NULL;
END;
$$;

--
-- Name: check_payment_receipt_immutable(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_payment_receipt_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'payment receipt %: receipts are kept (15 BR-04)', OLD.reference
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.customer_id IS DISTINCT FROM OLD.customer_id OR NEW.reference IS DISTINCT FROM OLD.reference
        OR NEW.received_on IS DISTINCT FROM OLD.received_on OR NEW.amount IS DISTINCT FROM OLD.amount
        OR NEW.currency IS DISTINCT FROM OLD.currency OR NEW.note IS DISTINCT FROM OLD.note
        OR NEW.recorded_by IS DISTINCT FROM OLD.recorded_by OR NEW.recorded_at IS DISTINCT FROM OLD.recorded_at THEN
        RAISE EXCEPTION 'payment receipt %: a receipt is not edited; void it and record the right one (15 BR-04)',
            OLD.reference USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.status = 'VOIDED' AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.voided_by IS DISTINCT FROM OLD.voided_by
                                  OR NEW.voided_at IS DISTINCT FROM OLD.voided_at
                                  OR NEW.void_reason IS DISTINCT FROM OLD.void_reason) THEN
        RAISE EXCEPTION 'payment receipt %: a voided receipt stays as it was voided', OLD.reference
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_payment_receipt_line(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_payment_receipt_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    receipt     RECORD;
    installment RECORD;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'payment receipt line %: receipt lines are kept as recorded (15 BR-04)', OLD.id
            USING ERRCODE = 'check_violation';
    END IF;
    SELECT r.status, r.customer_id, r.currency, r.reference INTO receipt
      FROM payment.payment_receipt r WHERE r.id = NEW.receipt_id;
    SELECT i.status, i.customer_id, i.currency, i.seq, i.contract_number INTO installment
      FROM payment.installment i WHERE i.id = NEW.installment_id;
    IF receipt.status <> 'RECORDED' THEN
        RAISE EXCEPTION 'payment receipt %: a voided receipt takes no line', receipt.reference
            USING ERRCODE = 'check_violation';
    END IF;
    IF installment.status = 'CANCELLED' THEN
        RAISE EXCEPTION 'payment receipt %: installment % of contract % is CANCELLED (15 BR-05)', receipt.reference,
            installment.seq, installment.contract_number USING ERRCODE = 'check_violation';
    END IF;
    IF installment.customer_id <> receipt.customer_id OR installment.currency <> receipt.currency THEN
        RAISE EXCEPTION 'payment receipt %: installment % of contract % is another customer''s, or in another currency '
            '(15 BR-05)', receipt.reference, installment.seq, installment.contract_number
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_payment_receipt_line_totals(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_payment_receipt_line_totals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM payment.assert_payment_receipt(NEW.receipt_id);
    PERFORM payment.assert_installment_paid(NEW.installment_id);
    RETURN NULL;
END;
$$;

--
-- Name: check_payment_receipt_void(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_payment_receipt_void() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    settled VARCHAR;
BEGIN
    IF NEW.status = 'VOIDED' AND OLD.status = 'RECORDED' THEN
        SELECT s.order_number INTO settled
          FROM payment.payment_receipt_line l
          JOIN payment.installment i ON i.id = l.installment_id
          JOIN payment.order_settlement s ON s.order_id = i.order_id
         WHERE l.receipt_id = NEW.id AND i.milestone <> 'CANCELLATION_FEE' AND OLD.recorded_at <= s.settled_at
           AND (s.kind = 'ORDER_CANCELLED' OR s.surplus_amount > 0)
         LIMIT 1;
        IF FOUND THEN
            RAISE EXCEPTION 'payment receipt %: order % was settled on what it paid (15 §4.4 step 13)', OLD.reference,
                settled USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_refund_record(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_refund_record() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    o RECORD;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'refund record %: refund records are kept (15 §4.5)', OLD.reference
            USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'INSERT' THEN
        SELECT co.customer_id, co.order_number, co.currency INTO o FROM ordering.customer_order co
         WHERE co.id = NEW.order_id;
        IF NEW.status <> 'RECORDED' OR NEW.customer_id IS DISTINCT FROM o.customer_id
            OR NEW.order_number IS DISTINCT FROM o.order_number OR NEW.currency IS DISTINCT FROM o.currency THEN
            RAISE EXCEPTION 'refund record %: recorded for order %, its customer, in its currency', NEW.reference,
                o.order_number USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
        OR NEW.order_number IS DISTINCT FROM OLD.order_number OR NEW.amount IS DISTINCT FROM OLD.amount
        OR NEW.currency IS DISTINCT FROM OLD.currency OR NEW.refunded_on IS DISTINCT FROM OLD.refunded_on
        OR NEW.reference IS DISTINCT FROM OLD.reference OR NEW.note IS DISTINCT FROM OLD.note
        OR NEW.recorded_by IS DISTINCT FROM OLD.recorded_by OR NEW.recorded_at IS DISTINCT FROM OLD.recorded_at THEN
        RAISE EXCEPTION 'refund record %: a record is not edited; void it and record the right one (15 §4.5)',
            OLD.reference USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.status = 'VOIDED' AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.voided_by IS DISTINCT FROM OLD.voided_by
                                  OR NEW.voided_at IS DISTINCT FROM OLD.voided_at
                                  OR NEW.void_reason IS DISTINCT FROM OLD.void_reason) THEN
        RAISE EXCEPTION 'refund record %: a voided record stays as it was voided', OLD.reference
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

--
-- Name: check_refund_record_total(); Type: FUNCTION; Schema: payment; Owner: -
--

CREATE FUNCTION payment.check_refund_record_total() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    refundable NUMERIC;
    refunded   NUMERIC;
BEGIN
    SELECT COALESCE(SUM(s.refundable_amount), 0) INTO refundable FROM payment.order_settlement s
     WHERE s.order_id = NEW.order_id;
    SELECT COALESCE(SUM(r.amount), 0) INTO refunded FROM payment.refund_record r
     WHERE r.order_id = NEW.order_id AND r.status = 'RECORDED';
    IF refunded > refundable THEN
        RAISE EXCEPTION 'order %: % recorded refunded, only % is to refund (15 BR-14)', NEW.order_number, refunded,
            refundable USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END;
$$;

--
-- Name: append_only(); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION platform.append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    i INTEGER := 0;
    parent_exists BOOLEAN;
BEGIN
    IF TG_OP = 'UPDATE' OR TG_NARGS = 0 THEN
        RAISE EXCEPTION '%.% is append-only', TG_TABLE_SCHEMA, TG_TABLE_NAME
            USING ERRCODE = 'check_violation';
    END IF;
    WHILE i < TG_NARGS LOOP
        EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s WHERE id = ($1 ->> %L)::uuid)',
                       TG_ARGV[i], TG_ARGV[i + 1])
           INTO parent_exists USING to_jsonb(OLD);
        IF NOT parent_exists THEN
            RETURN OLD;                  -- cascade from a deleted parent
        END IF;
        i := i + 2;
    END LOOP;
    RAISE EXCEPTION '%.% is append-only: rows leave only with their parent', TG_TABLE_SCHEMA, TG_TABLE_NAME
        USING ERRCODE = 'check_violation';
END
$_$;

--
-- Name: FUNCTION append_only(); Type: COMMENT; Schema: platform; Owner: -
--

COMMENT ON FUNCTION platform.append_only() IS 'BEFORE UPDATE OR DELETE trigger: refuses both, except a DELETE cascading from a parent named in the arguments.';

--
-- Name: forbid_update_of(); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION platform.forbid_update_of() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    col TEXT;
    old_value TEXT;
BEGIN
    FOREACH col IN ARRAY TG_ARGV LOOP
        old_value := to_jsonb(OLD) ->> col;
        IF old_value IS NOT NULL AND old_value IS DISTINCT FROM (to_jsonb(NEW) ->> col) THEN
            RAISE EXCEPTION '%.%.% is immutable once set (was %)',
                TG_TABLE_SCHEMA, TG_TABLE_NAME, col, old_value
                USING ERRCODE = 'check_violation';
        END IF;
    END LOOP;
    RETURN NEW;
END
$$;

--
-- Name: FUNCTION forbid_update_of(); Type: COMMENT; Schema: platform; Owner: -
--

COMMENT ON FUNCTION platform.forbid_update_of() IS 'BEFORE UPDATE trigger: the columns named as trigger arguments may go from NULL to a value, never change after.';

--
-- Name: check_goods_receipt(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.check_goods_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    production RECORD;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.receipt_type IS DISTINCT FROM OLD.receipt_type
            OR NEW.production_order_id IS DISTINCT FROM OLD.production_order_id THEN
            RAISE EXCEPTION 'receipt %: what it is against does not change', OLD.receipt_number
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    IF TG_OP = 'INSERT' AND NEW.receipt_type = 'PURCHASE' THEN
        RAISE EXCEPTION 'receipt %: purchasing was removed, goods are received against a production order',
            NEW.receipt_number USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.production_order_id IS NOT NULL THEN
        SELECT p.code, p.status, p.sample_approval_required, p.receiving_warehouse_id INTO production
          FROM ordering.production_order p WHERE p.id = NEW.production_order_id;
        IF NOT FOUND THEN
            RETURN NEW; -- fk_goods_receipts_production_order reports it
        END IF;
        IF NEW.warehouse_id IS DISTINCT FROM production.receiving_warehouse_id THEN
            RAISE EXCEPTION 'receipt % is into another warehouse than production order % is received at (03 BR-01)',
                NEW.receipt_number, production.code USING ERRCODE = 'check_violation';
        END IF;
        IF TG_OP = 'INSERT' AND NOT (production.status IN ('IN_PRODUCTION', 'PARTIALLY_RECEIVED')
            OR (production.status IN ('SENT', 'ACCEPTED') AND NOT production.sample_approval_required)) THEN
            RAISE EXCEPTION 'production order % is %: goods are not received against it (03 BR-01, BR-15)',
                production.code, production.status USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_goods_receipt_line(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.check_goods_receipt_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    receipt    procurement.goods_receipts%ROWTYPE;
    production RECORD;
BEGIN
    SELECT * INTO receipt FROM procurement.goods_receipts WHERE id = NEW.receipt_id;
    IF (NEW.production_order_line_id IS NULL) <> (receipt.production_order_id IS NULL) THEN
        RAISE EXCEPTION 'a receipt line names a production order line exactly when its receipt is against a production order'
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.production_order_line_id IS NOT NULL THEN
        SELECT l.production_order_id, l.sku, l.units_per_carton, p.code INTO production
          FROM ordering.production_order_line l
          JOIN ordering.production_order p ON p.id = l.production_order_id
         WHERE l.id = NEW.production_order_line_id
           FOR UPDATE OF l;
        IF NOT FOUND THEN
            RETURN NEW; -- fk_goods_receipt_lines_production_order_line reports it
        END IF;
        IF production.production_order_id IS DISTINCT FROM receipt.production_order_id THEN
            RAISE EXCEPTION 'receipt line is for a line of another production order (03 BR-01)'
                USING ERRCODE = 'check_violation';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM inventory.inventory_items i
                        WHERE i.id = NEW.inventory_item_id AND i.sku = production.sku) THEN
            RAISE EXCEPTION 'received item differs from SKU % of the production order line (03 BR-11)', production.sku
                USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.lot_number IS DISTINCT FROM production.code OR to_jsonb(NEW) ->> 'expiry_date' IS NOT NULL THEN
            RAISE EXCEPTION 'receipt line: the lot is production order %''s code, with no expiry date (03 BR-03, BR-06)',
                production.code USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.received_qty % production.units_per_carton <> 0 THEN
            RAISE EXCEPTION 'receipt line: % units are not whole cartons of % (03 BR-12, BR-13)',
                trim_scale(NEW.received_qty), production.units_per_carton USING ERRCODE = 'check_violation';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM inventory.uom_conversions u
                        WHERE u.id = NEW.uom_conversion_id AND NOT u.is_base
                          AND u.factor = production.units_per_carton) THEN
            RAISE EXCEPTION 'receipt line: counted in cartons holding the line''s % units (03 BR-12, BR-13)',
                production.units_per_carton USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM warehouse.storage_location s
                    WHERE s.id = NEW.location_id AND s.warehouse_id = receipt.warehouse_id) THEN
        RAISE EXCEPTION 'receipt location is not in the receiving warehouse' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_goods_receipt_line_frozen(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.check_goods_receipt_line_frozen() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    receipt_status VARCHAR(16);
BEGIN
    SELECT status INTO receipt_status FROM procurement.goods_receipts
     WHERE id = COALESCE(NEW.receipt_id, OLD.receipt_id);
    IF receipt_status IS NULL OR receipt_status = 'DRAFT' THEN
        RETURN COALESCE(NEW, OLD);
    END IF;
    IF TG_OP = 'UPDATE'
       AND NEW.receipt_id = OLD.receipt_id
       AND NEW.production_order_line_id IS NOT DISTINCT FROM OLD.production_order_line_id
       AND NEW.inventory_item_id = OLD.inventory_item_id AND NEW.location_id = OLD.location_id
       AND NEW.received_qty = OLD.received_qty
       AND NEW.lot_number IS NOT DISTINCT FROM OLD.lot_number
       AND (to_jsonb(NEW) -> 'expiry_date') IS NOT DISTINCT FROM (to_jsonb(OLD) -> 'expiry_date')
       AND NEW.uom_conversion_id IS NOT DISTINCT FROM OLD.uom_conversion_id THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'receipt is %: its lines keep what was counted (BR-05)', receipt_status
        USING ERRCODE = 'check_violation';
END
$$;

--
-- Name: check_goods_receipt_line_unit(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.check_goods_receipt_line_unit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    unit     inventory.uom_conversions%ROWTYPE;
    new_unit BOOLEAN;
BEGIN
    PERFORM pg_advisory_xact_lock_shared(inventory.unit_lock_key(NEW.uom_conversion_id));
    SELECT * INTO unit FROM inventory.uom_conversions WHERE id = NEW.uom_conversion_id;
    IF NOT FOUND THEN
        RETURN NEW; -- the foreign key reports it
    END IF;
    IF unit.inventory_item_id <> NEW.inventory_item_id THEN
        RAISE EXCEPTION 'receipt line: the unit is not a unit of the received item'
            USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'INSERT' THEN
        new_unit := TRUE;
    ELSE
        new_unit := NEW.uom_conversion_id IS DISTINCT FROM OLD.uom_conversion_id;
    END IF;
    IF new_unit AND NOT unit.active THEN
        RAISE EXCEPTION 'receipt line: unit % is retired; nothing new is received in it', unit.unit_of_measure
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_goods_receipt_photo_line(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.check_goods_receipt_photo_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.receipt_line_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM procurement.goods_receipt_lines
             WHERE id = NEW.receipt_line_id AND receipt_id = NEW.receipt_id) THEN
        RAISE EXCEPTION 'receipt line % is not a line of receipt %', NEW.receipt_line_id, NEW.receipt_id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_production_receipt_cartons(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.check_production_receipt_cartons() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    line     RECORD;
    received NUMERIC;
BEGIN
    SELECT l.cartons, l.units_per_carton, l.sku, p.code INTO line
      FROM ordering.production_order_line l
      JOIN ordering.production_order p ON p.id = l.production_order_id
     WHERE l.id = NEW.production_order_line_id;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    SELECT COALESCE(SUM(g.received_qty), 0) INTO received
      FROM procurement.goods_receipt_lines g
      JOIN procurement.goods_receipts r ON r.id = g.receipt_id
     WHERE g.production_order_line_id = NEW.production_order_line_id AND r.status <> 'CANCELLED';
    IF received > line.cartons * line.units_per_carton THEN
        RAISE EXCEPTION 'production order % line %: % carton(s) on receipts not cancelled, % ordered (03 BR-02)',
            line.code, line.sku, trunc(received / line.units_per_carton), line.cartons
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END
$$;

--
-- Name: check_production_receipt_registered(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.check_production_receipt_registered() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    expected VARCHAR(16);
BEGIN
    IF NEW.status = 'DRAFT' THEN
        expected := 'DRAFT';
    ELSIF NEW.status = 'CANCELLED' THEN
        expected := 'CANCELLED';
    ELSE
        expected := 'CONFIRMED';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ordering.production_order_receipt r
                    WHERE r.goods_receipt_id = NEW.id AND r.production_order_id = NEW.production_order_id
                      AND r.status = expected) THEN
        RAISE EXCEPTION 'receipt % is % but not registered % with its production order', NEW.receipt_number,
            NEW.status, expected USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END
$$;

--
-- Name: check_return_receipt(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.check_return_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    source_order     UUID;
    source_status    VARCHAR(32);
    source_warehouse UUID;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.receipt_type IS DISTINCT FROM OLD.receipt_type
            OR NEW.customer_order_id IS DISTINCT FROM OLD.customer_order_id
            OR NEW.return_shipment_id IS DISTINCT FROM OLD.return_shipment_id
            OR NEW.return_request_id IS DISTINCT FROM OLD.return_request_id
            OR NEW.quarantine_location_id IS DISTINCT FROM OLD.quarantine_location_id THEN
            RAISE EXCEPTION 'return receipt %: what it is against and where its goods go do not change',
                OLD.receipt_number USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.return_shipment_id IS NOT NULL THEN
        SELECT s.order_id, s.status, s.warehouse_id INTO source_order, source_status, source_warehouse
          FROM fulfillment.shipment s WHERE s.id = NEW.return_shipment_id;
        IF NOT FOUND THEN
            RETURN NEW; -- fk_goods_receipts_return_shipment reports it
        END IF;
        IF source_status <> 'RETURNED' THEN
            RAISE EXCEPTION 'return receipt %: the shipment is %, not RETURNED (kltn-docs 09 BR-06)',
                NEW.receipt_number, source_status USING ERRCODE = 'check_violation';
        END IF;
    ELSE
        SELECT r.order_id, r.status, o.warehouse_id INTO source_order, source_status, source_warehouse
          FROM ordering.return_request r JOIN ordering.customer_order o ON o.id = r.order_id
         WHERE r.id = NEW.return_request_id;
        IF NOT FOUND THEN
            RETURN NEW; -- fk_goods_receipts_return_request reports it
        END IF;
        IF source_status <> 'AWAITING_RETURN' THEN
            RAISE EXCEPTION 'return receipt %: the return request is %, not approved and awaiting its goods',
                NEW.receipt_number, source_status USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    IF source_order IS DISTINCT FROM NEW.customer_order_id THEN
        RAISE EXCEPTION 'return receipt %: its order is not the order of the shipment or return request',
            NEW.receipt_number USING ERRCODE = 'check_violation';
    END IF;
    IF source_warehouse IS DISTINCT FROM NEW.warehouse_id THEN
        RAISE EXCEPTION 'return receipt %: goods come back to the warehouse they left from (kltn-docs 03 §4.2)',
            NEW.receipt_number USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM warehouse.storage_location s JOIN warehouse.area a ON a.location_id = s.id
                    WHERE s.id = NEW.quarantine_location_id AND s.warehouse_id = NEW.warehouse_id
                      AND a.type = 'QUARANTINE' AND s.status = 'ACTIVE' AND a.status = 'ACTIVE') THEN
        RAISE EXCEPTION 'return receipt %: goods come back into an active QUARANTINE area of its warehouse (BR-14)',
            NEW.receipt_number USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_return_receipt_carton(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.check_return_receipt_carton() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    receipt procurement.goods_receipts%ROWTYPE;
    pkg     RECORD;
BEGIN
    SELECT * INTO receipt FROM procurement.goods_receipts WHERE id = COALESCE(NEW.receipt_id, OLD.receipt_id);
    IF receipt.receipt_type IS DISTINCT FROM 'RETURN' THEN
        RAISE EXCEPTION 'cartons are scanned on a RETURN receipt only' USING ERRCODE = 'check_violation';
    END IF;
    IF receipt.status <> 'DRAFT' THEN
        RAISE EXCEPTION 'return receipt % is %: its cartons are kept as they were confirmed', receipt.receipt_number,
            receipt.status USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    IF TG_OP = 'UPDATE' AND (NEW.receipt_id IS DISTINCT FROM OLD.receipt_id
        OR NEW.stock_package_id IS DISTINCT FROM OLD.stock_package_id OR NEW.lpn IS DISTINCT FROM OLD.lpn
        OR NEW.sku IS DISTINCT FROM OLD.sku OR NEW.lot_number IS DISTINCT FROM OLD.lot_number
        OR NEW.quantity IS DISTINCT FROM OLD.quantity OR NEW.scanned_by IS DISTINCT FROM OLD.scanned_by) THEN
        RAISE EXCEPTION 'return receipt %: only the condition of a scanned carton is changed', receipt.receipt_number
            USING ERRCODE = 'check_violation';
    END IF;
    SELECT p.lpn, i.sku, p.received_qty INTO pkg
      FROM inventory.stock_package p JOIN inventory.inventory_items i ON i.id = p.inventory_item_id
     WHERE p.id = NEW.stock_package_id;
    IF NOT FOUND THEN
        RETURN NEW; -- fk_goods_receipt_return_cartons_package reports it
    END IF;
    IF pkg.lpn <> NEW.lpn OR pkg.sku <> NEW.sku OR pkg.received_qty IS DISTINCT FROM NEW.quantity
       OR NOT EXISTS (SELECT 1 FROM inventory.stock_item s
                       WHERE s.stock_package_id = NEW.stock_package_id
                         AND s.lot_number IS NOT DISTINCT FROM NEW.lot_number) THEN
        RAISE EXCEPTION 'return receipt %: carton % is named as it was shipped - its LPN, SKU, count and lot (BR-03)',
            receipt.receipt_number, NEW.lpn USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM fulfillment.pick_line l JOIN fulfillment.pick k ON k.id = l.pick_id
                    WHERE k.order_id = receipt.customer_order_id AND l.lpn = NEW.lpn
                      AND l.picked_qty > l.put_back_qty) THEN
        RAISE EXCEPTION 'return receipt %: carton % was not shipped on its order (BR-14)', receipt.receipt_number,
            NEW.lpn USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_return_receipt_closed(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.check_return_receipt_closed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    area_code VARCHAR(64);
    cartons   BIGINT;
    received  BIGINT;
    missing   TEXT;
BEGIN
    SELECT location_code INTO area_code FROM warehouse.storage_location WHERE id = NEW.quarantine_location_id;
    SELECT count(*) INTO cartons FROM procurement.goods_receipt_return_cartons WHERE receipt_id = NEW.id;
    IF cartons = 0 THEN
        RAISE EXCEPTION 'return receipt % is closed with no carton', NEW.receipt_number
            USING ERRCODE = 'check_violation';
    END IF;
    SELECT string_agg(c.lpn, ', ' ORDER BY c.lpn) INTO missing
      FROM procurement.goods_receipt_return_cartons c
     WHERE c.receipt_id = NEW.id
       AND NOT EXISTS (SELECT 1 FROM inventory.stock_movement m
                        WHERE m.reference_type = 'GOODS_RECEIPT' AND m.reference_id = NEW.id
                          AND m.to_stock_package_id = c.stock_package_id AND m.to_location_code = area_code);
    IF missing IS NOT NULL THEN
        RAISE EXCEPTION 'return receipt % is closed but carton(s) % were not received into %', NEW.receipt_number,
            missing, area_code USING ERRCODE = 'check_violation';
    END IF;
    SELECT count(*) INTO received FROM inventory.stock_movement
     WHERE reference_type = 'GOODS_RECEIPT' AND reference_id = NEW.id;
    IF received <> cartons THEN
        RAISE EXCEPTION 'return receipt % lists % carton(s) but received %', NEW.receipt_number, cartons, received
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END
$$;

--
-- Name: goods_receipt_photo_unlink_only(); Type: FUNCTION; Schema: procurement; Owner: -
--

CREATE FUNCTION procurement.goods_receipt_photo_unlink_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Only the cascade: the line is already gone when its ON DELETE SET NULL runs; a hand-written UPDATE of a photo
    -- whose line still exists is refused.
    IF OLD.receipt_line_id IS NOT NULL AND NEW.receipt_line_id IS NULL AND OLD.stage = 'RECEIPT'
       AND (to_jsonb(NEW) - 'receipt_line_id') = (to_jsonb(OLD) - 'receipt_line_id')
       AND NOT EXISTS (SELECT 1 FROM procurement.goods_receipt_lines WHERE id = OLD.receipt_line_id) THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION '%.% is append-only', TG_TABLE_SCHEMA, TG_TABLE_NAME USING ERRCODE = 'check_violation';
END
$$;

--
-- Name: check_category_tree(); Type: FUNCTION; Schema: product; Owner: -
--

CREATE FUNCTION product.check_category_tree() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent product.categories%ROWTYPE;
BEGIN
    IF NEW.parent_id IS NULL THEN
        IF NEW.path <> '/' || NEW.code THEN
            RAISE EXCEPTION 'root category path must be /%', NEW.code USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END IF;

    SELECT * INTO parent FROM product.categories WHERE id = NEW.parent_id;
    IF TG_OP = 'UPDATE' AND parent.path LIKE OLD.path || '/%' THEN
        RAISE EXCEPTION 'category % cannot move under its own subtree', NEW.code
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.depth <> parent.depth + 1 OR NEW.path <> parent.path || '/' || NEW.code THEN
        RAISE EXCEPTION 'category % must have depth % and path %/%',
            NEW.code, parent.depth + 1, parent.path, NEW.code USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_customer_sku(); Type: FUNCTION; Schema: product; Owner: -
--

CREATE FUNCTION product.check_customer_sku() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND (NEW.owner_customer_id IS DISTINCT FROM OLD.owner_customer_id
        OR NEW.design_snapshot_id IS DISTINCT FROM OLD.design_snapshot_id
        OR NEW.source_variant_id IS DISTINCT FROM OLD.source_variant_id) THEN
        RAISE EXCEPTION 'a customer SKU keeps its owner, design snapshot and source variant (variant %)', NEW.id
            USING ERRCODE = '23514';
    END IF;
    IF NEW.source_variant_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM product.variants s
        WHERE s.id = NEW.source_variant_id AND s.product_id = NEW.product_id AND s.owner_customer_id IS NULL) THEN
        RAISE EXCEPTION 'a customer SKU is drawn on an ordinary variant of its own product (variant %)', NEW.id
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;

--
-- Name: check_descriptive_value(); Type: FUNCTION; Schema: product; Owner: -
--

CREATE FUNCTION product.check_descriptive_value() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    pa        product.product_attributes%ROWTYPE;
    data_type TEXT;
BEGIN
    SELECT * INTO pa FROM product.product_attributes WHERE id = NEW.product_attribute_id;
    SELECT a.data_type INTO data_type FROM product.attributes a WHERE a.id = pa.attribute_id;

    IF pa.role <> 'DESCRIPTIVE' THEN
        RAISE EXCEPTION 'descriptive values exist only for DESCRIPTIVE attributes'
            USING ERRCODE = 'check_violation';
    END IF;

    IF data_type IN ('SELECT', 'MULTISELECT', 'COLOR') THEN
        IF NEW.attribute_value_id IS NULL OR NOT EXISTS (
            SELECT 1 FROM product.attribute_values v
             WHERE v.id = NEW.attribute_value_id AND v.attribute_id = pa.attribute_id) THEN
            RAISE EXCEPTION 'a % attribute takes a value of its own dictionary', data_type
                USING ERRCODE = 'check_violation';
        END IF;
        IF data_type <> 'MULTISELECT' AND EXISTS (
            SELECT 1 FROM product.product_descriptive_values d
             WHERE d.product_attribute_id = NEW.product_attribute_id AND d.id <> NEW.id) THEN
            RAISE EXCEPTION 'a % attribute holds one value; only MULTISELECT holds several', data_type
                USING ERRCODE = 'check_violation';
        END IF;
    ELSIF (data_type = 'TEXT' AND NEW.value_text IS NULL)
       OR (data_type = 'NUMBER' AND NEW.value_number IS NULL)
       OR (data_type = 'BOOLEAN' AND NEW.value_boolean IS NULL) THEN
        RAISE EXCEPTION 'a % attribute takes its value in the matching value_* column', data_type
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_product_attribute(); Type: FUNCTION; Schema: product; Owner: -
--

CREATE FUNCTION product.check_product_attribute() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.role = 'VARIANT_AXIS' AND NOT EXISTS (
        SELECT 1 FROM product.attributes a
         WHERE a.id = NEW.attribute_id AND a.data_type IN ('SELECT', 'COLOR')) THEN
        RAISE EXCEPTION 'a VARIANT_AXIS attribute must be of type SELECT or COLOR'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_product_attribute_option(); Type: FUNCTION; Schema: product; Owner: -
--

CREATE FUNCTION product.check_product_attribute_option() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    pa product.product_attributes%ROWTYPE;
BEGIN
    SELECT * INTO pa FROM product.product_attributes WHERE id = NEW.product_attribute_id;
    IF pa.role <> 'VARIANT_AXIS' THEN
        RAISE EXCEPTION 'options exist only for VARIANT_AXIS attributes; use product_descriptive_values'
            USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM product.attribute_values v
                    WHERE v.id = NEW.attribute_value_id AND v.attribute_id = pa.attribute_id) THEN
        RAISE EXCEPTION 'attribute value % does not belong to the attribute of this axis', NEW.attribute_value_id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_sales_unit_of_item(); Type: FUNCTION; Schema: product; Owner: -
--

CREATE FUNCTION product.check_sales_unit_of_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM product.variants v
                   JOIN inventory.inventory_items i ON i.sku = v.sku
                   JOIN inventory.uom_conversions c ON c.inventory_item_id = i.id
                   WHERE v.id = NEW.variant_id AND c.id = NEW.uom_conversion_id) THEN
        RAISE EXCEPTION 'unit % is not a unit of the inventory item of variant %', NEW.uom_conversion_id,
            NEW.variant_id USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;

--
-- Name: check_template_customizable(); Type: FUNCTION; Schema: product; Owner: -
--

CREATE FUNCTION product.check_template_customizable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM product.variants v JOIN product.products p ON p.id = v.product_id
         WHERE v.id = NEW.variant_id AND p.kind = 'CUSTOMIZABLE') THEN
        RAISE EXCEPTION 'customization templates belong to variants of CUSTOMIZABLE products only'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_variant_attribute_value(); Type: FUNCTION; Schema: product; Owner: -
--

CREATE FUNCTION product.check_variant_attribute_value() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    variant_product UUID;
    option_product  UUID;
    option_axis     UUID;
BEGIN
    SELECT v.product_id INTO variant_product FROM product.variants v WHERE v.id = NEW.variant_id;
    SELECT pa.product_id, pa.id INTO option_product, option_axis
      FROM product.product_attribute_options o
      JOIN product.product_attributes pa ON pa.id = o.product_attribute_id
     WHERE o.id = NEW.product_attribute_option_id;

    IF option_product IS DISTINCT FROM variant_product THEN
        RAISE EXCEPTION 'option % belongs to another product than variant %',
            NEW.product_attribute_option_id, NEW.variant_id USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (
        SELECT 1 FROM product.variant_attribute_values x
          JOIN product.product_attribute_options o ON o.id = x.product_attribute_option_id
         WHERE x.variant_id = NEW.variant_id AND x.id <> NEW.id
           AND o.product_attribute_id = option_axis) THEN
        RAISE EXCEPTION 'variant % already has an option on this axis', NEW.variant_id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_variant_sku_frozen(); Type: FUNCTION; Schema: product; Owner: -
--

CREATE FUNCTION product.check_variant_sku_frozen() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status <> 'DRAFT' AND NEW.sku IS DISTINCT FROM OLD.sku THEN
        RAISE EXCEPTION 'sku % cannot change after the variant left DRAFT', OLD.sku
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: lock_inventory_sku_rename(); Type: FUNCTION; Schema: product; Owner: -
--

CREATE FUNCTION product.lock_inventory_sku_rename() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE code text;
BEGIN
    IF NEW.sku IS DISTINCT FROM OLD.sku THEN
        FOR code IN SELECT unnest(ARRAY[OLD.sku, NEW.sku]) ORDER BY 1 LOOP
            PERFORM pg_advisory_xact_lock(hashtextextended(code, 701));
        END LOOP;
    END IF;
    RETURN NEW;
END $$;

--
-- Name: preserve_commerce_slug(); Type: FUNCTION; Schema: product; Owner: -
--

CREATE FUNCTION product.preserve_commerce_slug() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.ever_published AND (NEW.slug IS DISTINCT FROM OLD.slug OR NOT NEW.ever_published) THEN
        RAISE EXCEPTION 'A published canonical slug is immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.status='PUBLISHED' OR NEW.published_at IS NOT NULL THEN NEW.ever_published := true; END IF;
    RETURN NEW;
END $$;

--
-- Name: refuse_delete_unless_draft(); Type: FUNCTION; Schema: product; Owner: -
--

CREATE FUNCTION product.refuse_delete_unless_draft() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status <> 'DRAFT' THEN
        RAISE EXCEPTION 'product % is %: only a DRAFT product is deleted (kltn-docs 01 BR-02)', OLD.code, OLD.status
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
END
$$;

--
-- Name: check_area_location(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.check_area_location() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    loc    warehouse.storage_location%ROWTYPE;
    prefix TEXT;
BEGIN
    IF NEW.location_id IS NULL THEN
        RETURN NEW;                       -- NON_STORAGE, see ck_area_storage
    END IF;
    SELECT * INTO loc FROM warehouse.storage_location WHERE id = NEW.location_id;
    SELECT w.prefix INTO prefix FROM warehouse.warehouse w WHERE w.id = NEW.warehouse_id;

    IF loc.kind IS DISTINCT FROM 'AREA' THEN
        RAISE EXCEPTION 'area % must point at a storage_location of kind AREA, got %', NEW.code, loc.kind
            USING ERRCODE = 'check_violation';
    END IF;
    IF loc.warehouse_id IS DISTINCT FROM NEW.warehouse_id THEN
        RAISE EXCEPTION 'area % and its storage_location are in different warehouses', NEW.code
            USING ERRCODE = 'check_violation';
    END IF;
    IF prefix IS NOT NULL AND loc.location_code IS DISTINCT FROM prefix || '-' || NEW.code THEN
        RAISE EXCEPTION 'area location_code must be %, got %', prefix || '-' || NEW.code, loc.location_code
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_bin_location(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.check_bin_location() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    loc    warehouse.storage_location%ROWTYPE;
    wh_id  UUID;
    prefix TEXT;
    shelf_code TEXT;
    level_no   INTEGER;
BEGIN
    SELECT * INTO loc FROM warehouse.storage_location WHERE id = NEW.location_id;
    SELECT s.warehouse_id, w.prefix, s.code, l.level_index
      INTO wh_id, prefix, shelf_code, level_no
      FROM warehouse.shelf_level l
      JOIN warehouse.shelf s ON s.id = l.shelf_id
      LEFT JOIN warehouse.warehouse w ON w.id = s.warehouse_id
     WHERE l.id = NEW.level_id;

    IF loc.kind IS DISTINCT FROM 'BIN' THEN
        RAISE EXCEPTION 'bin % must point at a storage_location of kind BIN, got %', NEW.code, loc.kind
            USING ERRCODE = 'check_violation';
    END IF;
    IF loc.warehouse_id IS DISTINCT FROM wh_id THEN
        RAISE EXCEPTION 'bin % and its storage_location are in different warehouses', NEW.code
            USING ERRCODE = 'check_violation';
    END IF;
    IF prefix IS NOT NULL
       AND loc.location_code IS DISTINCT FROM prefix || '-' || shelf_code || '-' || level_no || '-' || NEW.code THEN
        RAISE EXCEPTION 'bin location_code must be %, got %',
            prefix || '-' || shelf_code || '-' || level_no || '-' || NEW.code, loc.location_code
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_move_task_locations(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.check_move_task_locations() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (SELECT count(*) FROM warehouse.storage_location s
         WHERE s.id IN (NEW.from_location_id, NEW.to_location_id)
           AND s.warehouse_id = NEW.warehouse_id) <> 2 THEN
        RAISE EXCEPTION 'move task % must move between two locations of its own warehouse', NEW.task_number
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_putaway_task_package(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.check_putaway_task_package() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    pkg_status VARCHAR(16);
    newly_set  BOOLEAN;
BEGIN
    SELECT p.status INTO pkg_status
      FROM inventory.stock_package p JOIN inventory.inventory_items i ON i.id = p.inventory_item_id
     WHERE p.id = NEW.stock_package_id AND i.sku = NEW.sku;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'putaway task for % names a stock package of another SKU', NEW.sku
            USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'INSERT' THEN
        newly_set := TRUE;
    ELSE
        newly_set := NEW.stock_package_id IS DISTINCT FROM OLD.stock_package_id;
    END IF;
    IF newly_set AND pkg_status NOT IN ('RECEIVING', 'IN_STOCK') THEN
        RAISE EXCEPTION 'putaway task for % names a stock package that is %', NEW.sku, pkg_status
            USING ERRCODE = 'check_violation';
    END IF;
    IF newly_set AND NEW.source = 'QUARANTINE_RELEASE' THEN
        IF pkg_status <> 'IN_STOCK'
           OR NOT EXISTS (SELECT 1 FROM inventory.stock_item s
                           WHERE s.stock_package_id = NEW.stock_package_id AND s.on_hand > 0)
           OR EXISTS (SELECT 1 FROM inventory.stock_item s
                       WHERE s.stock_package_id = NEW.stock_package_id AND s.on_hand > 0
                         AND s.status <> 'QUARANTINE') THEN
            RAISE EXCEPTION 'a quarantine release puts away a carton in stock whose units are all QUARANTINE'
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_shelf_zone(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.check_shelf_zone() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.zone_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM warehouse.zone z WHERE z.id = NEW.zone_id AND z.warehouse_id = NEW.warehouse_id) THEN
        RAISE EXCEPTION 'shelf % is assigned to a zone of another warehouse', NEW.code
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_staging_area(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.check_staging_area() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    loc warehouse.storage_location%ROWTYPE;
BEGIN
    IF NEW.location_id IS NULL THEN
        RETURN NEW;
    END IF;
    SELECT * INTO loc FROM warehouse.storage_location WHERE id = NEW.location_id;
    IF NEW.type = 'STAGING' AND (loc.is_pickable OR loc.is_putaway_target) THEN
        RAISE EXCEPTION 'staging area % (%) is neither pickable nor a putaway target', NEW.code, loc.location_code
            USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'UPDATE' AND (OLD.type = 'STAGING') <> (NEW.type = 'STAGING')
       AND EXISTS (SELECT 1 FROM inventory.stock_item s WHERE s.location_code = loc.location_code AND s.on_hand > 0) THEN
        RAISE EXCEPTION 'area % (%) holds stock; it does not turn % a staging area while it does', NEW.code,
            loc.location_code, CASE WHEN NEW.type = 'STAGING' THEN 'into' ELSE 'out of' END
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_staging_location_flags(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.check_staging_location_flags() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (NEW.is_pickable OR NEW.is_putaway_target)
       AND EXISTS (SELECT 1 FROM warehouse.area a WHERE a.location_id = NEW.id AND a.type = 'STAGING') THEN
        RAISE EXCEPTION 'location % is a staging area: neither pickable nor a putaway target', NEW.location_code
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

--
-- Name: check_storage_location_owned(); Type: FUNCTION; Schema: warehouse; Owner: -
--

CREATE FUNCTION warehouse.check_storage_location_owned() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM warehouse.storage_location WHERE id = NEW.id)
       AND NOT EXISTS (SELECT 1 FROM warehouse.bin WHERE location_id = NEW.id)
       AND NOT EXISTS (SELECT 1 FROM warehouse.area WHERE location_id = NEW.id) THEN
        RAISE EXCEPTION 'storage_location % is owned by no bin and no area', NEW.location_code
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END
$$;

