    last_attempt_at timestamp with time zone,
    search_document tsvector GENERATED ALWAYS AS ((setweight(to_tsvector('simple'::regconfig, catalog.immutable_unaccent((COALESCE(published_title, ''::character varying))::text)), 'A'::"char") || setweight(to_tsvector('simple'::regconfig, catalog.immutable_unaccent(COALESCE(published_description, ''::text))), 'C'::"char"))) STORED,
    CONSTRAINT ck_listing_enabled CHECK (((NOT enabled) OR ever_published)),
    CONSTRAINT ck_listing_revision CHECK (((projected_revision >= '-1'::integer) AND (projected_revision <= revision))),
    CONSTRAINT ck_listing_slug CHECK (((slug)::text ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text)),
