    CONSTRAINT ck_customer_status_history_to CHECK (((to_status)::text = ANY ((ARRAY['PENDING_ACTIVATION'::character varying, 'ACTIVE'::character varying, 'INACTIVE'::character varying, 'BLOCKED'::character varying])::text[]))),
