);

--
-- Name: carrier; Type: TABLE; Schema: fulfillment; Owner: -
--

CREATE TABLE fulfillment.carrier (
    id uuid NOT NULL,
    code character varying(32) NOT NULL,
    name character varying(120) NOT NULL,
    contact_name character varying(120),
    contact_phone character varying(32),
    status character varying(16) DEFAULT 'ACTIVE'::character varying NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    connection_type character varying(16) DEFAULT 'MANUAL'::character varying NOT NULL,
    webhook_enabled boolean DEFAULT false NOT NULL,
    webhook_secret_sealed text,
    webhook_auth_header character varying(64),
    webhook_auth_value_sealed text,
    api_environment character varying(16),
    api_account character varying(64),
    api_key_sealed text,
    failure_reason_map jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT ck_carrier_api_account CHECK (((api_account IS NULL) OR ((api_account)::text ~ '^[!-~]{3,64}$'::text))),
    CONSTRAINT ck_carrier_api_environment CHECK (((api_environment IS NULL) OR ((api_environment)::text = ANY ((ARRAY['STAGING'::character varying, 'PRODUCTION'::character varying])::text[])))),
    CONSTRAINT ck_carrier_code CHECK (((code)::text ~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'::text)),
    CONSTRAINT ck_carrier_connection_api_booking CHECK ((((connection_type)::text <> 'API_BOOKING'::text) OR ((api_environment IS NOT NULL) AND (api_account IS NOT NULL) AND (api_key_sealed IS NOT NULL) AND (webhook_auth_header IS NOT NULL) AND (webhook_auth_value_sealed IS NOT NULL)))),
    CONSTRAINT ck_carrier_connection_manual CHECK ((((connection_type)::text <> 'MANUAL'::text) OR (NOT webhook_enabled))),
    CONSTRAINT ck_carrier_connection_type CHECK (((connection_type)::text = ANY ((ARRAY['MANUAL'::character varying, 'WEBHOOK_LOAD'::character varying, 'API_BOOKING'::character varying])::text[]))),
    CONSTRAINT ck_carrier_connection_webhook_load CHECK ((((connection_type)::text <> 'WEBHOOK_LOAD'::text) OR (webhook_secret_sealed IS NOT NULL))),
    CONSTRAINT ck_carrier_failure_reason_map CHECK (((jsonb_typeof(failure_reason_map) = 'object'::text) AND (NOT jsonb_path_exists(failure_reason_map, 'strict $.*?(@.type() != "string")'::jsonpath)) AND (NOT jsonb_path_exists(failure_reason_map, '$.*?(((((@ != "CUSTOMER_ABSENT" && @ != "REFUSED") && @ != "WRONG_ADDRESS") && @ != "LOST") && @ != "DAMAGED") && @ != "OTHER")'::jsonpath)) AND (jsonb_array_length(jsonb_path_query_array(failure_reason_map, '$.keyvalue()'::jsonpath)) <= 100))),
    CONSTRAINT ck_carrier_name CHECK ((btrim((name)::text) <> ''::text)),
    CONSTRAINT ck_carrier_secrets_sealed CHECK ((((webhook_secret_sealed IS NULL) OR (webhook_secret_sealed ~ '^v1:[A-Za-z0-9+/]+={0,2}$'::text)) AND ((webhook_auth_value_sealed IS NULL) OR (webhook_auth_value_sealed ~ '^v1:[A-Za-z0-9+/]+={0,2}$'::text)) AND ((api_key_sealed IS NULL) OR (api_key_sealed ~ '^v1:[A-Za-z0-9+/]+={0,2}$'::text)))),
    CONSTRAINT ck_carrier_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INACTIVE'::character varying])::text[]))),
    CONSTRAINT ck_carrier_webhook_auth_header CHECK (((webhook_auth_header IS NULL) OR ((webhook_auth_header)::text ~ '^[A-Za-z0-9-]{1,64}$'::text)))
);

