    duration_ms integer NOT NULL,
    called_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_carrier_api_call_answered CHECK ((((outcome)::text = 'NO_ANSWER'::text) = (http_status IS NULL))),
    CONSTRAINT ck_carrier_api_call_duration CHECK ((duration_ms >= 0)),
    CONSTRAINT ck_carrier_api_call_operation CHECK (((operation)::text = ANY ((ARRAY['TOKEN'::character varying, 'SERVICES'::character varying, 'BOOK'::character varying, 'CANCEL'::character varying, 'STATUS'::character varying])::text[]))),
    CONSTRAINT ck_carrier_api_call_outcome CHECK (((outcome)::text = ANY ((ARRAY['OK'::character varying, 'REFUSED'::character varying, 'NO_ANSWER'::character varying])::text[]))),
    CONSTRAINT ck_carrier_api_call_token_body CHECK ((((operation)::text <> 'TOKEN'::text) OR ((request_body IS NULL) AND (response_body IS NULL))))
);

--
-- Name: carrier_booking; Type: TABLE; Schema: fulfillment; Owner: -
--

CREATE TABLE fulfillment.carrier_booking (
    id uuid NOT NULL,
    load_id uuid NOT NULL,
    carrier_id uuid NOT NULL,
    service_code character varying(64) NOT NULL,
    stops jsonb NOT NULL,
    order_time timestamp with time zone,
    status character varying(16) NOT NULL,
    carrier_order_id character varying(64),
