    booked_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    cancel_reason character varying(500),
    cancel_attempts integer DEFAULT 0 NOT NULL,
    last_error character varying(1000),
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_carrier_booking_attempts CHECK ((cancel_attempts >= 0)),
    CONSTRAINT ck_carrier_booking_booked CHECK ((((status)::text = ANY ((ARRAY['REQUESTED'::character varying, 'FAILED'::character varying, 'UNCONFIRMED'::character varying])::text[])) OR ((carrier_order_id IS NOT NULL) AND (booked_at IS NOT NULL)))),
    CONSTRAINT ck_carrier_booking_cancelled CHECK ((((status)::text = 'CANCELLED'::text) = (cancelled_at IS NOT NULL))),
    CONSTRAINT ck_carrier_booking_failed CHECK ((((status)::text <> ALL ((ARRAY['FAILED'::character varying, 'UNCONFIRMED'::character varying, 'CANCEL_FAILED'::character varying])::text[])) OR (last_error IS NOT NULL))),
    CONSTRAINT ck_carrier_booking_status CHECK (((status)::text = ANY ((ARRAY['REQUESTED'::character varying, 'BOOKED'::character varying, 'FAILED'::character varying, 'UNCONFIRMED'::character varying, 'CANCELLED'::character varying, 'CANCEL_FAILED'::character varying])::text[]))),
    CONSTRAINT ck_carrier_booking_stops CHECK (((jsonb_typeof(stops) = 'array'::text) AND (jsonb_array_length(stops) >= 1)))
);

--
-- Name: carrier_event; Type: TABLE; Schema: fulfillment; Owner: -
--

CREATE TABLE fulfillment.carrier_event (
    id uuid NOT NULL,
    carrier_id uuid,
    carrier_code character varying(64) NOT NULL,
    received_at timestamp with time zone NOT NULL,
    payload text NOT NULL,
    signature_valid boolean NOT NULL,
    event_kind character varying(24),
    carrier_reference character varying(128),
    carrier_reported_at timestamp with time zone,
    dedupe_key character varying(64),
    warehouse_id uuid,
    load_id uuid,
    shipment_id uuid,
    result character varying(20) NOT NULL,
    result_note character varying(1000),
    decided_at timestamp with time zone,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    resolution_note character varying(1000),
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_carrier_event_code CHECK (((carrier_code)::text ~ '^[!-~]{1,64}$'::text)),
    CONSTRAINT ck_carrier_event_decided CHECK ((((result)::text = 'RECEIVED'::text) = (decided_at IS NULL))),
    CONSTRAINT ck_carrier_event_kind CHECK (((event_kind IS NULL) OR ((event_kind)::text = ANY ((ARRAY['WAYBILL'::character varying, 'DRIVER_ASSIGNED'::character varying, 'DRIVER_RELEASED'::character varying, 'PICKED_UP'::character varying, 'IN_TRANSIT'::character varying, 'DELIVERED'::character varying, 'DELIVERY_FAILED'::character varying, 'RETURNING'::character varying, 'RETURNED'::character varying, 'ORDER_CANCELLED'::character varying, 'CANCELLED_ON_REQUEST'::character varying, 'ORDER_COMPLETED'::character varying, 'OTHER'::character varying])::text[])))),
    CONSTRAINT ck_carrier_event_matched CHECK ((((result)::text <> ALL ((ARRAY['APPLIED'::character varying, 'DUPLICATE'::character varying, 'STALE'::character varying])::text[])) OR (load_id IS NOT NULL))),
    CONSTRAINT ck_carrier_event_payload CHECK ((octet_length(payload) <= 65536)),
    CONSTRAINT ck_carrier_event_resolution CHECK ((((resolved_at IS NULL) = (resolved_by IS NULL)) AND ((resolved_at IS NULL) = (resolution_note IS NULL)))),
    CONSTRAINT ck_carrier_event_resolution_note CHECK (((resolution_note IS NULL) OR (btrim((resolution_note)::text) <> ''::text))),
    CONSTRAINT ck_carrier_event_resolvable CHECK (((resolved_at IS NULL) OR ((result)::text = ANY ((ARRAY['RECEIVED'::character varying, 'UNMATCHED'::character varying, 'INVALID_SIGNATURE'::character varying, 'NEEDS_REVIEW'::character varying])::text[])))),
    CONSTRAINT ck_carrier_event_result CHECK (((result)::text = ANY ((ARRAY['RECEIVED'::character varying, 'APPLIED'::character varying, 'DUPLICATE'::character varying, 'STALE'::character varying, 'IGNORED'::character varying, 'UNMATCHED'::character varying, 'INVALID_SIGNATURE'::character varying, 'NEEDS_REVIEW'::character varying])::text[]))),
    CONSTRAINT ck_carrier_event_shipment CHECK (((shipment_id IS NULL) OR (load_id IS NOT NULL))),
    CONSTRAINT ck_carrier_event_signature CHECK ((signature_valid OR (((result)::text = 'INVALID_SIGNATURE'::text) AND (load_id IS NULL)))),
    CONSTRAINT ck_carrier_event_unknown_carrier CHECK (((carrier_id IS NOT NULL) OR ((result)::text = 'INVALID_SIGNATURE'::text))),
