    CONSTRAINT ck_dispatch_load_booked CHECK ((((status)::text <> 'VEHICLE_BOOKED'::text) OR (booked_at IS NOT NULL))),
    CONSTRAINT ck_dispatch_load_booking_cancel CHECK (((booking_cancelled_at IS NULL) = (booking_cancel_reason IS NULL))),
    CONSTRAINT ck_dispatch_load_cancel_reason_code CHECK (((cancel_reason_code IS NULL) OR (((status)::text = 'CANCELLED'::text) AND ((cancel_reason_code)::text = ANY ((ARRAY['XE_HONG'::character varying, 'SAI_XE'::character varying, 'KIEN_KHONG_VUA'::character varying, 'KHAC'::character varying])::text[]))))),
    CONSTRAINT ck_dispatch_load_cancelled CHECK (((((status)::text = 'CANCELLED'::text) = (cancelled_at IS NOT NULL)) AND (((status)::text <> 'CANCELLED'::text) OR (cancel_reason IS NOT NULL)))),
    CONSTRAINT ck_dispatch_load_carrier CHECK ((((status)::text = ANY ((ARRAY['PLANNED'::character varying, 'CANCELLED'::character varying])::text[])) OR (carrier_id IS NOT NULL))),
    CONSTRAINT ck_dispatch_load_dispatched CHECK (((((status)::text = 'DISPATCHED'::text) = (dispatched_at IS NOT NULL)) AND (((status)::text <> 'DISPATCHED'::text) OR ((dispatched_by IS NOT NULL) AND (carrier_representative IS NOT NULL) AND (vehicle_plate IS NOT NULL) AND (shipment_count > 0) AND (package_count > 0))))),
    CONSTRAINT ck_dispatch_load_loading CHECK ((((status)::text <> ALL ((ARRAY['LOADING'::character varying, 'DISPATCHED'::character varying])::text[])) OR (loading_started_at IS NOT NULL))),
    CONSTRAINT ck_dispatch_load_status CHECK (((status)::text = ANY ((ARRAY['PLANNED'::character varying, 'VEHICLE_BOOKED'::character varying, 'LOADING'::character varying, 'DISPATCHED'::character varying, 'CANCELLED'::character varying])::text[]))),
    CONSTRAINT ck_dispatch_load_totals CHECK (((shipment_count >= 0) AND (package_count >= 0))),
    CONSTRAINT ck_dispatch_load_vehicle CHECK (((load_plan_vehicle_id IS NOT NULL) OR ((status)::text = ANY ((ARRAY['DISPATCHED'::character varying, 'CANCELLED'::character varying])::text[])))),
    CONSTRAINT ck_dispatch_load_vehicle_booked CHECK (((load_plan_vehicle_id IS NULL) OR ((status)::text <> ALL ((ARRAY['VEHICLE_BOOKED'::character varying, 'LOADING'::character varying, 'DISPATCHED'::character varying])::text[])) OR (booked_at IS NOT NULL))),
    CONSTRAINT ck_dispatch_load_waybill_carrier CHECK (((waybill_no IS NULL) OR (carrier_id IS NOT NULL))),
    CONSTRAINT ck_dispatch_load_waybill_no CHECK (((waybill_no IS NULL) OR ((waybill_no)::text ~ '^[!-~]{1,64}$'::text)))
);

