    CONSTRAINT ck_package_kind CHECK ((((pick_line_id IS NULL) AND (lpn IS NULL) AND ((status)::text = ANY ((ARRAY['OPEN'::character varying, 'SEALED'::character varying, 'VOIDED'::character varying])::text[])) AND (checked_at IS NULL) AND (labeled_at IS NULL) AND (removed_at IS NULL) AND (label_version = 0)) OR ((pick_line_id IS NOT NULL) AND (lpn IS NOT NULL) AND ((status)::text = ANY ((ARRAY['TO_CHECK'::character varying, 'CHECKED'::character varying, 'LABELED'::character varying, 'REMOVED'::character varying])::text[])) AND (sealed_at IS NULL) AND (voided_at IS NULL)))),
    CONSTRAINT ck_package_labeled CHECK (((label_version >= 0) AND ((labeled_at IS NULL) = (labeled_by IS NULL)) AND ((labeled_at IS NULL) = (label_version = 0)) AND (((status)::text <> 'LABELED'::text) OR ((labeled_at IS NOT NULL) AND (checked_at IS NOT NULL) AND (weight_kg IS NOT NULL) AND (length_cm IS NOT NULL) AND (width_cm IS NOT NULL) AND (height_cm IS NOT NULL) AND (dim_weight_kg IS NOT NULL))))),
    CONSTRAINT ck_package_measures CHECK ((((weight_kg IS NULL) OR (weight_kg > (0)::numeric)) AND ((length_cm IS NULL) OR (length_cm > (0)::numeric)) AND ((width_cm IS NULL) OR (width_cm > (0)::numeric)) AND ((height_cm IS NULL) OR (height_cm > (0)::numeric)) AND ((dim_weight_kg IS NULL) OR (dim_weight_kg > (0)::numeric)))),
    CONSTRAINT ck_package_no CHECK ((package_no > 0)),
    CONSTRAINT ck_package_removed CHECK (((((status)::text = 'REMOVED'::text) = (removed_at IS NOT NULL)) AND ((removed_at IS NULL) = (removal_reason IS NULL)) AND ((removal_reason IS NULL) OR ((removal_reason)::text = ANY ((ARRAY['DAMAGED'::character varying, 'ORDER_CANCELLED'::character varying])::text[]))) AND (((removal_reason)::text IS DISTINCT FROM 'DAMAGED'::text) OR (removed_by IS NOT NULL)) AND ((removal_note IS NULL) OR (btrim((removal_note)::text) <> ''::text)))),
    CONSTRAINT ck_package_sealed CHECK ((((status)::text <> 'SEALED'::text) OR ((sealed_at IS NOT NULL) AND (weight_kg IS NOT NULL) AND (length_cm IS NOT NULL) AND (width_cm IS NOT NULL) AND (height_cm IS NOT NULL)))),
    CONSTRAINT ck_package_shipped CHECK (((shipment_id IS NULL) OR ((status)::text = ANY ((ARRAY['SEALED'::character varying, 'VOIDED'::character varying, 'LABELED'::character varying])::text[])))),
    CONSTRAINT ck_package_status CHECK (((status)::text = ANY ((ARRAY['OPEN'::character varying, 'SEALED'::character varying, 'VOIDED'::character varying, 'TO_CHECK'::character varying, 'CHECKED'::character varying, 'LABELED'::character varying, 'REMOVED'::character varying])::text[]))),
    CONSTRAINT ck_package_voided CHECK ((((status)::text = 'VOIDED'::text) = (voided_at IS NOT NULL)))
);

--
-- Name: COLUMN package.pick_line_id; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.package.pick_line_id IS '4C-6: the pick line that took this shipping carton; null for a parcel of the repack station (removed in 4C-7)';

--
-- Name: COLUMN package.lpn; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.package.lpn IS '4C-6: the LPN of the carton the producer packed - the shipping carton itself (kltn-docs 08 BR-02)';

--
-- Name: COLUMN package.label_version; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.package.label_version IS '4C-6: 0 before the first shipping label, then 1, plus one for every reprint: only the latest is valid (08 BR-08)';

--
-- Name: CONSTRAINT ck_package_kind ON package; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON CONSTRAINT ck_package_kind ON fulfillment.package IS 'A shipping carton of the check station (team plan 4C-6), or a parcel the repack station sealed or voided before 4C-7 removed it (history only: no new one is written).';

--
-- Name: pick; Type: TABLE; Schema: fulfillment; Owner: -
--

CREATE TABLE fulfillment.pick (
    id uuid NOT NULL,
    wave_id uuid,
    order_id uuid NOT NULL,
    status character varying(32) NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    assigned_user_id uuid,
    assigned_at timestamp with time zone,
    started_at timestamp with time zone,
    picked_at timestamp with time zone,
    needs_put_back boolean DEFAULT false NOT NULL,
    order_number character varying(32) NOT NULL,
    warehouse_id uuid NOT NULL,
    destination character varying(16) DEFAULT 'DISPATCH'::character varying NOT NULL,
    staging_location_code character varying(64),
    staged_at timestamp with time zone,
    moved_to_dispatch_at timestamp with time zone,
    moved_to_dispatch_by uuid,
    delivery_batch_id uuid,
    CONSTRAINT ck_pick_destination CHECK (((destination)::text = ANY ((ARRAY['DISPATCH'::character varying, 'STAGING'::character varying])::text[]))),
    CONSTRAINT ck_pick_moved_to_dispatch CHECK ((((moved_to_dispatch_at IS NULL) = (moved_to_dispatch_by IS NULL)) AND ((moved_to_dispatch_at IS NULL) OR (((destination)::text = 'STAGING'::text) AND (staged_at IS NOT NULL))))),
    CONSTRAINT ck_pick_put_back CHECK (((NOT needs_put_back) OR ((status)::text = 'CANCELLED'::text))),
    CONSTRAINT ck_pick_staged CHECK ((((status)::text <> 'STAGED'::text) OR (((destination)::text = 'STAGING'::text) AND (staged_at IS NOT NULL) AND (moved_to_dispatch_at IS NULL)))),
    CONSTRAINT ck_pick_staging_location CHECK ((((destination)::text = 'STAGING'::text) = (staging_location_code IS NOT NULL))),
    CONSTRAINT ck_pick_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'PICKING'::character varying, 'STAGED'::character varying, 'PICKED'::character varying, 'CANCELLED'::character varying])::text[])))
);

--
-- Name: COLUMN pick.order_number; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick.order_number IS 'ordering.customer_order.order_number at the time the task was created; shown on pick lists.';

--
-- Name: COLUMN pick.warehouse_id; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick.warehouse_id IS 'The warehouse the goods are picked from: the order''s warehouse once released, else where its holds sit.';

--
-- Name: COLUMN pick.destination; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick.destination IS 'kltn-docs 07 §1: where picked cartons go - DISPATCH (deducted when scanned) or STAGING (moved, held for the order).';

--
-- Name: COLUMN pick.staging_location_code; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick.staging_location_code IS 'The STAGING area of the task''s warehouse its cartons are moved to; set only for a STAGING task.';

--
-- Name: COLUMN pick.moved_to_dispatch_at; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick.moved_to_dispatch_at IS 'kltn-docs 07 §4.3 step 8: when the warehouse manager moved the staged task to dispatch, deducting its cartons.';

--
-- Name: COLUMN pick.delivery_batch_id; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick.delivery_batch_id IS '4B-8 (07 BR-07): the released delivery batch this task picks; null for an order without a delivery schedule.';

--
-- Name: pick_line; Type: TABLE; Schema: fulfillment; Owner: -
--

CREATE TABLE fulfillment.pick_line (
    id uuid NOT NULL,
    pick_id uuid NOT NULL,
    order_line_id uuid NOT NULL,
    reservation_id uuid,
    sku character varying(64) NOT NULL,
    location_code character varying(64) NOT NULL,
    lot_number character varying(64),
    sequence_no integer DEFAULT 0 NOT NULL,
    allocated_qty integer NOT NULL,
    picked_qty integer DEFAULT 0 NOT NULL,
    short_qty integer DEFAULT 0 NOT NULL,
    status character varying(16) DEFAULT 'OPEN'::character varying NOT NULL,
    picked_by uuid,
    picked_at timestamp with time zone,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    consumed_at timestamp with time zone,
    scanned_location_code character varying(64),
    scanned_code character varying(64),
    put_back_qty integer DEFAULT 0 NOT NULL,
    put_back_location_code character varying(64),
    put_back_by uuid,
    put_back_at timestamp with time zone,
    lpn character varying(30),
    whole_carton boolean DEFAULT false NOT NULL,
    short_reason character varying(16),
    staged_at timestamp with time zone,
    staged_location_code character varying(64),
    CONSTRAINT ck_pick_line_lpn CHECK ((lpn IS NOT NULL)),
    CONSTRAINT ck_pick_line_picked CHECK ((((status)::text <> ALL ((ARRAY['PICKED'::character varying, 'STAGED'::character varying, 'PUT_BACK'::character varying])::text[])) OR ((picked_qty = allocated_qty) AND (picked_by IS NOT NULL) AND (picked_at IS NOT NULL) AND ((reservation_id IS NULL) OR (consumed_at IS NOT NULL) OR (((status)::text <> 'PICKED'::text) AND (staged_at IS NOT NULL)))))),
    CONSTRAINT ck_pick_line_put_back CHECK (((((status)::text = 'PUT_BACK'::text) = (put_back_at IS NOT NULL)) AND (((status)::text <> 'PUT_BACK'::text) OR ((put_back_qty = picked_qty) AND (put_back_qty > 0) AND (put_back_by IS NOT NULL) AND (put_back_location_code IS NOT NULL))))),
    CONSTRAINT ck_pick_line_put_back_qty CHECK (((put_back_qty >= 0) AND (put_back_qty <= picked_qty))),
    CONSTRAINT ck_pick_line_put_back_whole CHECK ((((status)::text <> 'PUT_BACK'::text) OR (put_back_qty = allocated_qty))),
    CONSTRAINT ck_pick_line_qty CHECK (((allocated_qty > 0) AND (picked_qty >= 0) AND (short_qty >= 0))),
    CONSTRAINT ck_pick_line_short CHECK ((((status)::text <> 'SHORT'::text) OR (short_qty > 0))),
    CONSTRAINT ck_pick_line_short_reason CHECK (((short_reason IS NULL) OR (((short_reason)::text = ANY ((ARRAY['NOT_FOUND'::character varying, 'DAMAGED'::character varying])::text[])) AND (short_qty = allocated_qty) AND ((status)::text = ANY ((ARRAY['SHORT'::character varying, 'CANCELLED'::character varying])::text[]))))),
    CONSTRAINT ck_pick_line_short_reported CHECK ((((status)::text <> 'SHORT'::text) OR (short_reason IS NOT NULL))),
    CONSTRAINT ck_pick_line_staged CHECK ((((staged_at IS NULL) = (staged_location_code IS NULL)) AND (((status)::text <> 'STAGED'::text) OR ((staged_at IS NOT NULL) AND (consumed_at IS NULL))))),
    CONSTRAINT ck_pick_line_status CHECK (((status)::text = ANY ((ARRAY['OPEN'::character varying, 'STAGED'::character varying, 'PICKED'::character varying, 'SHORT'::character varying, 'CANCELLED'::character varying, 'PUT_BACK'::character varying])::text[]))),
    CONSTRAINT ck_pick_line_whole_carton CHECK (((NOT whole_carton) OR (lpn IS NOT NULL))),
    CONSTRAINT ck_pick_line_within_allocation CHECK (((picked_qty + short_qty) <= allocated_qty))
);

--
-- Name: COLUMN pick_line.consumed_at; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick_line.consumed_at IS 'When the hold behind the line was deducted (inventory.stock_movement PICK, reference PICK_LINE).';

--
-- Name: COLUMN pick_line.scanned_location_code; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick_line.scanned_location_code IS 'The location code the picker scanned.';

--
-- Name: COLUMN pick_line.scanned_code; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick_line.scanned_code IS 'The SKU or barcode the picker scanned.';

--
-- Name: COLUMN pick_line.put_back_location_code; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick_line.put_back_location_code IS 'The bin the goods of a cancelled order went back onto (docs 07 BR-05).';

--
-- Name: COLUMN pick_line.lpn; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick_line.lpn IS 'The carton the line takes: the LPN of its hold''s stock row (tg_pick_line_carton), scanned to confirm the line and again to put it back. NULL only on loose history (ck_pick_line_lpn).';

--
-- Name: COLUMN pick_line.whole_carton; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick_line.whole_carton IS 'The hold is the carton''s whole sealed content when planned: the picker takes the carton as it stands.';

--
-- Name: COLUMN pick_line.short_reason; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick_line.short_reason IS 'kltn-docs 07 §4.4 step 9: why the picker could not take the line''s carton - NOT_FOUND (not at the bin) or DAMAGED (there, but not fit to ship). Set with the short; kept when the line is reallocated (CANCELLED).';

--
-- Name: COLUMN pick_line.staged_at; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick_line.staged_at IS 'kltn-docs 07 §4.2 step 5: when the carton was moved to the staging area (MOVE, reference PICK_LINE), not deducted.';

--
-- Name: COLUMN pick_line.staged_location_code; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON COLUMN fulfillment.pick_line.staged_location_code IS 'The staging area the carton was moved to; kept after the task moved to dispatch or the carton was put back.';

--
-- Name: CONSTRAINT ck_pick_line_lpn ON pick_line; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON CONSTRAINT ck_pick_line_lpn ON fulfillment.pick_line IS 'kltn-docs 07 BR-04, BR-10: a pick line is one carton, named by its LPN. NOT VALID where loose history exists (lines from before 4C-1, or the carton-less lines V20261114000400 cancelled).';

--
-- Name: CONSTRAINT ck_pick_line_put_back ON pick_line; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON CONSTRAINT ck_pick_line_put_back ON fulfillment.pick_line IS 'kltn-docs 07 BR-05: a put-back returns what the line picked. NOT VALID where partial put-backs of before 4C-4 exist.';

--
-- Name: CONSTRAINT ck_pick_line_put_back_whole ON pick_line; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON CONSTRAINT ck_pick_line_put_back_whole ON fulfillment.pick_line IS 'kltn-docs 07 BR-05, §4.5 step 14: a put-back returns the whole carton. NOT VALID where partial put-backs exist.';

--
-- Name: CONSTRAINT ck_pick_line_short_reported ON pick_line; Type: COMMENT; Schema: fulfillment; Owner: -
--

COMMENT ON CONSTRAINT ck_pick_line_short_reported ON fulfillment.pick_line IS 'kltn-docs 07 §4.4 step 9: a short pick says why. NOT VALID where short lines without a reason exist.';

--
-- Name: shipment; Type: TABLE; Schema: fulfillment; Owner: -
--

CREATE TABLE fulfillment.shipment (
    id uuid NOT NULL,
    pack_id uuid,
    order_id uuid NOT NULL,
    carrier character varying(120),
    tracking_number character varying(128),
    status character varying(32) NOT NULL,
    dispatched_at timestamp with time zone,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    code character varying(48) NOT NULL,
    request_id uuid,
    warehouse_id uuid NOT NULL,
    package_count integer DEFAULT 1 NOT NULL,
    partial boolean DEFAULT false NOT NULL,
    partial_note character varying(500),
    ready_at timestamp with time zone NOT NULL,
    ready_by uuid,
    handed_over_at timestamp with time zone,
    handed_over_by uuid,
    outcome_at timestamp with time zone,
    outcome_by uuid,
    failure_reason character varying(24),
    failure_note character varying(500),
    cancelled_at timestamp with time zone,
    cancel_reason character varying(500),
    carrier_id uuid,
    load_id uuid,
    whole_order_handover boolean DEFAULT false NOT NULL,
    CONSTRAINT ck_shipment_cancelled CHECK ((((status)::text = 'CANCELLED'::text) = (cancelled_at IS NOT NULL))),
    CONSTRAINT ck_shipment_failure CHECK (((((status)::text <> 'DELIVERY_FAILED'::text) OR (failure_reason IS NOT NULL)) AND ((failure_reason IS NULL) OR ((failure_reason)::text = ANY ((ARRAY['CUSTOMER_ABSENT'::character varying, 'REFUSED'::character varying, 'WRONG_ADDRESS'::character varying, 'LOST'::character varying, 'DAMAGED'::character varying, 'OTHER'::character varying])::text[]))))),
    CONSTRAINT ck_shipment_handed_over CHECK ((((status)::text <> ALL ((ARRAY['HANDED_OVER'::character varying, 'DELIVERED'::character varying, 'DELIVERY_FAILED'::character varying, 'RETURNED'::character varying])::text[])) OR (handed_over_at IS NOT NULL))),
    CONSTRAINT ck_shipment_handed_over_load CHECK ((((status)::text <> ALL ((ARRAY['HANDED_OVER'::character varying, 'DELIVERED'::character varying, 'DELIVERY_FAILED'::character varying, 'RETURNED'::character varying])::text[])) OR whole_order_handover OR ((load_id IS NOT NULL) AND (carrier_id IS NOT NULL) AND (handed_over_by IS NOT NULL)))),
    CONSTRAINT ck_shipment_load_handed_over CHECK (((load_id IS NULL) OR (handed_over_at IS NOT NULL))),
    CONSTRAINT ck_shipment_outcome CHECK ((((status)::text <> ALL ((ARRAY['DELIVERED'::character varying, 'DELIVERY_FAILED'::character varying, 'RETURNED'::character varying])::text[])) OR (outcome_at IS NOT NULL))),
    CONSTRAINT ck_shipment_package_count CHECK ((package_count > 0)),
    CONSTRAINT ck_shipment_partial CHECK (((NOT partial) OR (partial_note IS NOT NULL))),
    CONSTRAINT ck_shipment_status CHECK (((status)::text = ANY ((ARRAY['READY_TO_DISPATCH'::character varying, 'HANDED_OVER'::character varying, 'DELIVERED'::character varying, 'DELIVERY_FAILED'::character varying, 'RETURNED'::character varying, 'CANCELLED'::character varying])::text[])))
);

--
-- Name: shipment_event; Type: TABLE; Schema: fulfillment; Owner: -
--

CREATE TABLE fulfillment.shipment_event (
    id uuid NOT NULL,
    shipment_id uuid NOT NULL,
    status character varying(24) NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    source character varying(16) NOT NULL,
    carrier_event_id character varying(128),
    location_text character varying(255),
    note character varying(1000),
    raw_payload jsonb,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    recorded_by uuid,
    CONSTRAINT ck_shipment_event_payload CHECK (((raw_payload IS NULL) OR (jsonb_typeof(raw_payload) = 'object'::text))),
    CONSTRAINT ck_shipment_event_source CHECK (((source)::text = ANY ((ARRAY['CARRIER_WEBHOOK'::character varying, 'CARRIER_POLL'::character varying, 'MANUAL'::character varying])::text[]))),
    CONSTRAINT ck_shipment_event_status CHECK (((status)::text = ANY ((ARRAY['LABEL_CREATED'::character varying, 'READY_TO_DISPATCH'::character varying, 'HANDED_OVER'::character varying, 'IN_TRANSIT'::character varying, 'OUT_FOR_DELIVERY'::character varying, 'DELIVERY_FAILED'::character varying, 'RETURNING'::character varying, 'DELIVERED'::character varying, 'RETURNED'::character varying, 'EXCEPTION'::character varying, 'CANCELLED'::character varying])::text[])))
);

--
-- Name: shipment_pod_file; Type: TABLE; Schema: fulfillment; Owner: -
--

CREATE TABLE fulfillment.shipment_pod_file (
    id uuid NOT NULL,
    shipment_id uuid NOT NULL,
    storage_key character varying(512) NOT NULL,
    file_name character varying(255) NOT NULL,
    content_type character varying(100) NOT NULL,
    size_bytes bigint NOT NULL,
    uploaded_by uuid NOT NULL,
    uploaded_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_shipment_pod_file_key CHECK (((storage_key)::text ~~ 'documents/%'::text)),
    CONSTRAINT ck_shipment_pod_file_name CHECK ((btrim((file_name)::text) <> ''::text)),
    CONSTRAINT ck_shipment_pod_file_size CHECK ((size_bytes > 0))
);

--
-- Name: tracking_milestone; Type: TABLE; Schema: fulfillment; Owner: -
--

CREATE TABLE fulfillment.tracking_milestone (
    id uuid NOT NULL,
    load_id uuid NOT NULL,
    milestone character varying(16) NOT NULL,
    carrier_reported_at timestamp with time zone NOT NULL,
    source character varying(16) NOT NULL,
    carrier_event_id uuid,
    recorded_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_tracking_milestone_event CHECK ((((source)::text = 'CARRIER_WEBHOOK'::text) = (carrier_event_id IS NOT NULL))),
    CONSTRAINT ck_tracking_milestone_kind CHECK (((milestone)::text = ANY ((ARRAY['PICKED_UP'::character varying, 'IN_TRANSIT'::character varying, 'RETURNING'::character varying, 'RETURNED'::character varying])::text[]))),
    CONSTRAINT ck_tracking_milestone_source CHECK (((source)::text = ANY ((ARRAY['CARRIER_WEBHOOK'::character varying, 'MANUAL'::character varying])::text[])))
);

--
-- Name: vehicle_type; Type: TABLE; Schema: fulfillment; Owner: -
--

CREATE TABLE fulfillment.vehicle_type (
    id uuid NOT NULL,
    code character varying(32) NOT NULL,
    name character varying(120) NOT NULL,
    kind character varying(16) NOT NULL,
    inner_length_mm integer NOT NULL,
    inner_width_mm integer NOT NULL,
    inner_height_mm integer NOT NULL,
    gusset_mm integer DEFAULT 0 NOT NULL,
    max_payload_kg numeric(10,3) NOT NULL,
    available_count integer DEFAULT 0 NOT NULL,
    rental_price numeric(19,4),
    is_preset boolean DEFAULT false NOT NULL,
    status character varying(16) DEFAULT 'ACTIVE'::character varying NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    door_width_mm integer,
    door_height_mm integer,
    CONSTRAINT ck_vehicle_type_available CHECK ((available_count >= 0)),
    CONSTRAINT ck_vehicle_type_code CHECK (((code)::text ~ '^[A-Z0-9][A-Z0-9_-]{1,31}$'::text)),
    CONSTRAINT ck_vehicle_type_door_height CHECK (((door_height_mm IS NULL) OR (door_height_mm > 0))),
    CONSTRAINT ck_vehicle_type_door_height_fits CHECK (((door_height_mm IS NULL) OR (door_height_mm <= inner_height_mm))),
    CONSTRAINT ck_vehicle_type_door_width CHECK (((door_width_mm IS NULL) OR (door_width_mm > 0))),
    CONSTRAINT ck_vehicle_type_door_width_fits CHECK (((door_width_mm IS NULL) OR (door_width_mm <= inner_width_mm))),
    CONSTRAINT ck_vehicle_type_gusset CHECK ((gusset_mm >= 0)),
    CONSTRAINT ck_vehicle_type_gusset_fits CHECK ((((2 * gusset_mm) < inner_width_mm) AND (gusset_mm < inner_height_mm))),
    CONSTRAINT ck_vehicle_type_height CHECK ((inner_height_mm > 0)),
    CONSTRAINT ck_vehicle_type_kind CHECK (((kind)::text = ANY ((ARRAY['CONTAINER'::character varying, 'TRUCK'::character varying, 'PICKUP'::character varying])::text[]))),
    CONSTRAINT ck_vehicle_type_length CHECK ((inner_length_mm > 0)),
    CONSTRAINT ck_vehicle_type_name CHECK ((btrim((name)::text) <> ''::text)),
    CONSTRAINT ck_vehicle_type_payload CHECK ((max_payload_kg > (0)::numeric)),
    CONSTRAINT ck_vehicle_type_rental_price CHECK (((rental_price IS NULL) OR (rental_price >= (0)::numeric))),
    CONSTRAINT ck_vehicle_type_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INACTIVE'::character varying])::text[]))),
    CONSTRAINT ck_vehicle_type_width CHECK ((inner_width_mm > 0))
);

--
-- Name: wave; Type: TABLE; Schema: fulfillment; Owner: -
--

CREATE TABLE fulfillment.wave (
    id uuid NOT NULL,
    code character varying(64) NOT NULL,
    status character varying(32) NOT NULL,
    released_at timestamp with time zone,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_wave_status CHECK (((status)::text = ANY ((ARRAY['PLANNED'::character varying, 'RELEASED'::character varying, 'COMPLETED'::character varying])::text[])))
);

--
-- Name: waybill_change; Type: TABLE; Schema: fulfillment; Owner: -
--

CREATE TABLE fulfillment.waybill_change (
    id uuid NOT NULL,
    load_id uuid NOT NULL,
    old_waybill_no character varying(64),
    new_waybill_no character varying(64),
    source character varying(16) NOT NULL,
    changed_by uuid,
    changed_at timestamp with time zone NOT NULL,
    reason character varying(500),
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_waybill_change_changes CHECK (((old_waybill_no)::text IS DISTINCT FROM (new_waybill_no)::text)),
    CONSTRAINT ck_waybill_change_reason CHECK (((reason IS NULL) OR (btrim((reason)::text) <> ''::text))),
    CONSTRAINT ck_waybill_change_source CHECK (((source)::text = ANY ((ARRAY['MANUAL'::character varying, 'FILE'::character varying, 'WEBHOOK'::character varying, 'API'::character varying])::text[]))),
    CONSTRAINT ck_waybill_change_who CHECK (((((source)::text = 'WEBHOOK'::text) AND (changed_by IS NULL)) OR (((source)::text = ANY ((ARRAY['MANUAL'::character varying, 'FILE'::character varying])::text[])) AND (changed_by IS NOT NULL)) OR ((source)::text = 'API'::text)))
);

