    CONSTRAINT ck_waybill_import_rows CHECK ((((rows_total >= 1) AND (rows_total <= 1000)) AND (rows_applied >= 0) AND (rows_rejected >= 0) AND ((rows_applied + rows_rejected) = rows_total)))
);

--
