    CONSTRAINT ck_waybill_import_row_outcome CHECK (((outcome)::text = ANY ((ARRAY['NEW'::character varying, 'OVERWRITE'::character varying, 'SAME'::character varying, 'ERROR'::character varying])::text[]))),
    CONSTRAINT ck_waybill_import_row_problem CHECK (((((outcome)::text = 'ERROR'::text) = (problem IS NOT NULL)) AND ((problem IS NULL) OR ((problem)::text = ANY ((ARRAY['MISSING_FIELDS'::character varying, 'INVALID_WAYBILL'::character varying, 'INVALID_VEHICLE_DETAILS'::character varying, 'LOAD_NOT_FOUND'::character varying, 'LOAD_OUT_OF_SCOPE'::character varying, 'LOAD_REPEATED'::character varying, 'LOAD_NOT_BOOKED'::character varying, 'LOAD_CANCELLED'::character varying, 'LOAD_LEFT'::character varying, 'WAYBILL_FROM_CARRIER_API'::character varying, 'DUPLICATE_IN_FILE'::character varying, 'DUPLICATE_IN_CARRIER'::character varying, 'OVERWRITE_NOT_CONFIRMED'::character varying])::text[])))))
);

