    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_portal_invitation_consumed CHECK (((consumed_at IS NULL) OR ((consumed_at >= issued_at) AND (consumed_at < expires_at)))),
    CONSTRAINT ck_portal_invitation_delivery CHECK ((((delivery_status IS NULL) AND (delivery_attempted_at IS NULL)) OR (((delivery_status)::text = ANY ((ARRAY['SENT'::character varying, 'FAILED'::character varying])::text[])) AND (delivery_attempted_at IS NOT NULL)))),
    CONSTRAINT ck_portal_invitation_digest CHECK ((token_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ck_portal_invitation_lifetime CHECK ((expires_at > issued_at)),
    CONSTRAINT ck_portal_invitation_one_end CHECK (((consumed_at IS NULL) OR (revoked_at IS NULL))),
    CONSTRAINT ck_portal_invitation_revoked CHECK (((revoked_at IS NULL) OR (revoked_at >= issued_at)))
);

