    CONSTRAINT ck_cycle_count_status CHECK (((status)::text = ANY ((ARRAY['PLANNED'::character varying, 'IN_PROGRESS'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying])::text[]))),
    CONSTRAINT ck_cycle_count_trigger CHECK (((trigger_type)::text = ANY ((ARRAY['SCHEDULED'::character varying, 'SHORT_PICK'::character varying, 'MOVE_DISCREPANCY'::character varying, 'MANUAL'::character varying])::text[])))
);

