    CONSTRAINT ck_cycle_count_line_qty CHECK (((expected_qty >= 0) AND ((counted_qty IS NULL) OR (counted_qty >= 0))))
);

--
-- Name: COLUMN cycle_count_line.stock_package_id; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.cycle_count_line.stock_package_id IS 'The carton this line counts; NULL for a loose layer.';

--
-- Name: inventory_items; Type: TABLE; Schema: inventory; Owner: -
--

