    last_modified_by character varying(100),
    rotatable boolean DEFAULT true NOT NULL,
    CONSTRAINT ck_inventory_items_pack_size CHECK ((pack_size >= 1)),
    CONSTRAINT ck_inventory_items_package_count CHECK ((package_count >= 1)),
    CONSTRAINT ck_inventory_items_package_size CHECK ((((package_length_cm IS NULL) OR (package_length_cm > (0)::numeric)) AND ((package_width_cm IS NULL) OR (package_width_cm > (0)::numeric)) AND ((package_height_cm IS NULL) OR (package_height_cm > (0)::numeric)))),
    CONSTRAINT ck_inventory_items_package_weight CHECK (((package_weight_kg IS NULL) OR (package_weight_kg > (0)::numeric))),
    CONSTRAINT ck_inventory_items_size CHECK ((((length_cm IS NULL) OR (length_cm > (0)::numeric)) AND ((width_cm IS NULL) OR (width_cm > (0)::numeric)) AND ((height_cm IS NULL) OR (height_cm > (0)::numeric)))),
    CONSTRAINT ck_inventory_items_uom CHECK (((unit_of_measure)::text ~ '^[A-Z0-9_]{1,16}$'::text)),
    CONSTRAINT ck_inventory_items_weight CHECK (((weight_kg IS NULL) OR (weight_kg > (0)::numeric)))
);

--
-- Name: stock_adjustment; Type: TABLE; Schema: inventory; Owner: -
--

CREATE TABLE inventory.stock_adjustment (
    id uuid NOT NULL,
    adjustment_number character varying(30) NOT NULL,
    location_code character varying(64) NOT NULL,
    sku character varying(64) NOT NULL,
    lot_number character varying(64),
    quantity_delta integer NOT NULL,
    reason_code character varying(24) NOT NULL,
    note character varying(1000),
    status character varying(20) DEFAULT 'PENDING_APPROVAL'::character varying NOT NULL,
    cycle_count_line_id uuid,
    requested_by uuid NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    rejection_reason character varying(500),
    posted_at timestamp with time zone,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    withdrawn_at timestamp with time zone,
    received_at timestamp with time zone,
    reservation_id uuid,
    stock_package_id uuid,
    CONSTRAINT ck_stock_adjustment_count_variance CHECK ((((reason_code)::text <> 'COUNT_VARIANCE'::text) OR (cycle_count_line_id IS NOT NULL))),
    CONSTRAINT ck_stock_adjustment_decided CHECK ((((status)::text = ANY ((ARRAY['PENDING_APPROVAL'::character varying, 'WITHDRAWN'::character varying])::text[])) = ((decided_by IS NULL) AND (decided_at IS NULL)))),
    CONSTRAINT ck_stock_adjustment_delta CHECK ((quantity_delta <> 0)),
    CONSTRAINT ck_stock_adjustment_four_eyes CHECK (((decided_by IS NULL) OR (decided_by <> requested_by))),
    CONSTRAINT ck_stock_adjustment_other_note CHECK ((((reason_code)::text <> 'OTHER'::text) OR (NULLIF(btrim((note)::text), ''::text) IS NOT NULL))),
    CONSTRAINT ck_stock_adjustment_posted CHECK ((((status)::text = 'POSTED'::text) = (posted_at IS NOT NULL))),
    CONSTRAINT ck_stock_adjustment_reason CHECK (((reason_code)::text = ANY ((ARRAY['DAMAGED'::character varying, 'LOST'::character varying, 'FOUND'::character varying, 'COUNT_VARIANCE'::character varying, 'EXPIRED'::character varying, 'DATA_CORRECTION'::character varying, 'SCRAP'::character varying, 'SAMPLE'::character varying, 'OTHER'::character varying, 'SUBCONTRACT_LOSS'::character varying])::text[]))),
    CONSTRAINT ck_stock_adjustment_rejected CHECK ((((status)::text = 'REJECTED'::text) = (rejection_reason IS NOT NULL))),
    CONSTRAINT ck_stock_adjustment_reservation_scrap CHECK (((reservation_id IS NULL) OR ((quantity_delta < 0) AND ((reason_code)::text = 'SCRAP'::text)))),
    CONSTRAINT ck_stock_adjustment_status CHECK (((status)::text = ANY ((ARRAY['PENDING_APPROVAL'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying, 'POSTED'::character varying, 'WITHDRAWN'::character varying])::text[]))),
    CONSTRAINT ck_stock_adjustment_withdrawn CHECK ((((status)::text = 'WITHDRAWN'::text) = (withdrawn_at IS NOT NULL))),
    CONSTRAINT ck_stock_adjustment_writes_down CHECK ((((reason_code)::text <> ALL ((ARRAY['SCRAP'::character varying, 'SAMPLE'::character varying])::text[])) OR (quantity_delta < 0)))
);

--
-- Name: COLUMN stock_adjustment.reservation_id; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_adjustment.reservation_id IS 'The hold whose units this SCRAP write-off takes: printed goods of a cancelled order (BR-PRD-10). Approval closes the hold.';

--
-- Name: COLUMN stock_adjustment.stock_package_id; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_adjustment.stock_package_id IS 'The carton whose contents are adjusted; NULL for loose stock.';

--
-- Name: CONSTRAINT ck_stock_adjustment_other_note ON stock_adjustment; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON CONSTRAINT ck_stock_adjustment_other_note ON inventory.stock_adjustment IS 'kltn-docs 20 BR-04: an adjustment with reason OTHER carries a note.';

--
-- Name: stock_item; Type: TABLE; Schema: inventory; Owner: -
--

CREATE TABLE inventory.stock_item (
    id uuid NOT NULL,
    sku character varying(64) NOT NULL,
    location_code character varying(64) NOT NULL,
    lot_number character varying(64) NOT NULL,
    on_hand integer DEFAULT 0 NOT NULL,
    reserved integer DEFAULT 0 NOT NULL,
    status character varying(32) NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    received_at timestamp with time zone,
    stock_package_id uuid,
    lot_id uuid NOT NULL,
    CONSTRAINT ck_stock_item_lot CHECK ((btrim((lot_number)::text) <> ''::text)),
    CONSTRAINT ck_stock_item_on_hand_non_negative CHECK ((on_hand >= 0)),
    CONSTRAINT ck_stock_item_quarantine_unheld CHECK ((((status)::text <> 'QUARANTINE'::text) OR (reserved = 0))),
    CONSTRAINT ck_stock_item_reserved_non_negative CHECK ((reserved >= 0)),
    CONSTRAINT ck_stock_item_reserved_within_on_hand CHECK ((reserved <= on_hand)),
    CONSTRAINT ck_stock_item_status CHECK (((status)::text = ANY ((ARRAY['INBOUND'::character varying, 'AVAILABLE'::character varying, 'QUARANTINE'::character varying, 'BLOCKED'::character varying, 'DAMAGED'::character varying, 'EXPIRED'::character varying, 'IN_PRODUCTION'::character varying])::text[]))),
    CONSTRAINT ck_stock_item_whole_cartons CHECK (((stock_package_id IS NOT NULL) OR ((on_hand = 0) AND (reserved = 0))))
);

--
-- Name: TABLE stock_item; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON TABLE inventory.stock_item IS 'Stock row: one quantity of a SKU at one location, of one lot and receipt time, in one status - loose (stock_package_id NULL) or the contents of one carton. on_hand and reserved are counted in the base unit.';

--
-- Name: COLUMN stock_item.reserved; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_item.reserved IS 'Units of this row held by HELD reservations: allocations and older checkout holds (SKU reservations sit on no row).';

--
-- Name: COLUMN stock_item.stock_package_id; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_item.stock_package_id IS 'The carton this row is the contents of (one row per carton). NULL only for loose rows still written by a put-back, a customer return or a damage report, and for emptied rows of the history.';

--
-- Name: CONSTRAINT ck_stock_item_lot ON stock_item; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON CONSTRAINT ck_stock_item_lot ON inventory.stock_item IS 'kltn-docs 20 BR-22: every unit carries a lot; a unit with no known lot is of lot UNTRACED (C45).';

--
-- Name: CONSTRAINT ck_stock_item_quarantine_unheld ON stock_item; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON CONSTRAINT ck_stock_item_quarantine_unheld ON inventory.stock_item IS 'Kltn-docs 20 BR-01, BR-21: only a free carton is quarantined, and quarantined stock is never allocated.';

--
-- Name: CONSTRAINT ck_stock_item_whole_cartons ON stock_item; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON CONSTRAINT ck_stock_item_whole_cartons ON inventory.stock_item IS 'Stock is kept in whole LPN cartons (kltn-docs 20 BR-14): a row in no carton holds nothing and nobody''s hold.';

--
-- Name: stock_lot; Type: TABLE; Schema: inventory; Owner: -
--

CREATE TABLE inventory.stock_lot (
    id uuid NOT NULL,
    sku character varying(64) NOT NULL,
    lot_number character varying(64),
    received_at timestamp with time zone,
    origin_type character varying(16) NOT NULL,
    goods_receipt_id uuid,
    goods_receipt_number character varying(30),
    warehouse_id uuid,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    production_order_id uuid,
    production_order_code character varying(32),
    CONSTRAINT ck_stock_lot_origin CHECK (((origin_type)::text = ANY ((ARRAY['GOODS_RECEIPT'::character varying, 'PRODUCTION_ORDER'::character varying, 'UNTRACED'::character varying])::text[]))),
    CONSTRAINT ck_stock_lot_production_order CHECK (((((origin_type)::text = 'PRODUCTION_ORDER'::text) = (production_order_id IS NOT NULL)) AND ((production_order_id IS NULL) = (production_order_code IS NULL)) AND (((origin_type)::text <> 'PRODUCTION_ORDER'::text) OR (((lot_number)::text = (production_order_code)::text) AND (received_at IS NOT NULL) AND (goods_receipt_id IS NULL) AND (goods_receipt_number IS NULL))))),
    CONSTRAINT ck_stock_lot_receipt CHECK ((((origin_type)::text <> 'GOODS_RECEIPT'::text) OR ((goods_receipt_id IS NOT NULL) AND (received_at IS NOT NULL)))),
    CONSTRAINT ck_stock_lot_untraced CHECK ((((origin_type)::text <> 'UNTRACED'::text) OR (goods_receipt_id IS NULL)))
);

--
-- Name: TABLE stock_lot; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON TABLE inventory.stock_lot IS 'A lot as received: one per goods receipt and (SKU, lot number, expiry), so a reused lot number is a new lot (SCRUM-142).';

--
-- Name: COLUMN stock_lot.production_order_code; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_lot.production_order_code IS 'The production order as it read when its first goods were received: also the lot number (kltn-docs 03 BR-03).';

--
-- Name: stock_movement; Type: TABLE; Schema: inventory; Owner: -
--

CREATE TABLE inventory.stock_movement (
    id uuid NOT NULL,
    movement_type character varying(24) NOT NULL,
    sku character varying(64) NOT NULL,
    lot_number character varying(64),
    from_location_code character varying(64),
    to_location_code character varying(64),
    quantity integer NOT NULL,
    from_status character varying(32),
    to_status character varying(32),
    reference_type character varying(32) NOT NULL,
    reference_id uuid NOT NULL,
    reason character varying(500),
    actor_id uuid,
    occurred_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    from_stock_package_id uuid,
    to_stock_package_id uuid,
    lot_id uuid,
    order_id uuid,
    order_number character varying(32),
    CONSTRAINT ck_stock_movement_package_side CHECK ((((from_stock_package_id IS NULL) OR (from_location_code IS NOT NULL)) AND ((to_stock_package_id IS NULL) OR (to_location_code IS NOT NULL)))),
    CONSTRAINT ck_stock_movement_put_back_carton CHECK ((((movement_type)::text <> 'PUT_BACK'::text) OR ((reference_type)::text <> 'PICK_LINE'::text) OR (to_stock_package_id IS NOT NULL))),
    CONSTRAINT ck_stock_movement_qty CHECK ((quantity > 0)),
    CONSTRAINT ck_stock_movement_quarantine_exit CHECK ((((from_status)::text IS DISTINCT FROM 'QUARANTINE'::text) OR ((to_location_code IS NOT NULL) AND ((to_status)::text = 'QUARANTINE'::text)) OR ((reference_type)::text = 'STOCK_ADJUSTMENT'::text) OR (((reference_type)::text = 'PUTAWAY_TASK'::text) AND ((to_status)::text = 'AVAILABLE'::text)) OR ((reference_type)::text = ANY ((ARRAY['QC_INSPECTION'::character varying, 'RETURN_REQUEST_LINE'::character varying])::text[])))),
    CONSTRAINT ck_stock_movement_reference CHECK (((reference_type)::text = ANY ((ARRAY['GOODS_RECEIPT_LINE'::character varying, 'QC_INSPECTION'::character varying, 'PUTAWAY_TASK'::character varying, 'PICK_LINE'::character varying, 'PACKAGE'::character varying, 'MOVE_TASK'::character varying, 'TRANSFER_ORDER_LINE'::character varying, 'STOCK_ADJUSTMENT'::character varying, 'CYCLE_COUNT_LINE'::character varying, 'RETURN_REQUEST_LINE'::character varying, 'ORDER'::character varying, 'PRODUCTION_ORDER'::character varying, 'EXPIRY_SWEEP'::character varying, 'DAMAGE_REPORT'::character varying, 'STOCK_PACKAGE'::character varying, 'GOODS_RECEIPT'::character varying])::text[]))),
    CONSTRAINT ck_stock_movement_return_receipt CHECK ((((reference_type)::text <> 'GOODS_RECEIPT'::text) OR (((movement_type)::text = 'RECEIPT'::text) AND (to_stock_package_id IS NOT NULL) AND ((to_status)::text = 'QUARANTINE'::text)))),
    CONSTRAINT ck_stock_movement_shape CHECK (
CASE
    WHEN ((movement_type)::text = ANY ((ARRAY['RECEIPT'::character varying, 'TRANSFER_IN'::character varying, 'RETURN_IN'::character varying])::text[])) THEN ((from_location_code IS NULL) AND (to_location_code IS NOT NULL))
    WHEN ((movement_type)::text = ANY ((ARRAY['PICK'::character varying, 'TRANSFER_OUT'::character varying, 'SCRAP'::character varying, 'CONSUMPTION'::character varying, 'SUPPLIER_RETURN'::character varying])::text[])) THEN ((from_location_code IS NOT NULL) AND (to_location_code IS NULL))
    WHEN ((movement_type)::text = 'PUTAWAY'::text) THEN ((from_location_code IS NOT NULL) AND (to_location_code IS NOT NULL) AND ((from_location_code)::text <> (to_location_code)::text))
    WHEN ((movement_type)::text = 'MOVE'::text) THEN ((from_location_code IS NOT NULL) AND (to_location_code IS NOT NULL) AND (((from_location_code)::text <> (to_location_code)::text) OR (((reference_type)::text = 'STOCK_PACKAGE'::text) AND (NOT (to_stock_package_id IS DISTINCT FROM reference_id)))))
    WHEN ((movement_type)::text = 'PUT_BACK'::text) THEN ((to_location_code IS NOT NULL) AND ((((reference_type)::text = ANY ((ARRAY['PICK_LINE'::character varying, 'ORDER'::character varying, 'DAMAGE_REPORT'::character varying])::text[])) AND (from_location_code IS NULL)) OR ((from_location_code IS NOT NULL) AND ((from_location_code)::text <> (to_location_code)::text))))
    WHEN ((movement_type)::text = ANY ((ARRAY['ADJUSTMENT'::character varying, 'COUNT_CORRECTION'::character varying])::text[])) THEN (num_nonnulls(from_location_code, to_location_code) = 1)
    WHEN ((movement_type)::text = 'STATUS_CHANGE'::text) THEN ((from_location_code IS NOT NULL) AND (to_location_code IS NOT NULL) AND (from_status IS NOT NULL) AND (to_status IS NOT NULL) AND ((from_status)::text <> (to_status)::text) AND (((from_location_code)::text = (to_location_code)::text) OR (((reference_type)::text = 'STOCK_PACKAGE'::text) AND ((to_status)::text = 'QUARANTINE'::text))))
    ELSE NULL::boolean
END),
    CONSTRAINT ck_stock_movement_status CHECK ((((from_status IS NULL) OR ((from_status)::text = ANY ((ARRAY['INBOUND'::character varying, 'AVAILABLE'::character varying, 'QUARANTINE'::character varying, 'BLOCKED'::character varying, 'DAMAGED'::character varying, 'EXPIRED'::character varying, 'IN_PRODUCTION'::character varying])::text[]))) AND ((to_status IS NULL) OR ((to_status)::text = ANY ((ARRAY['INBOUND'::character varying, 'AVAILABLE'::character varying, 'QUARANTINE'::character varying, 'BLOCKED'::character varying, 'DAMAGED'::character varying, 'EXPIRED'::character varying, 'IN_PRODUCTION'::character varying])::text[]))))),
    CONSTRAINT ck_stock_movement_type CHECK (((movement_type)::text = ANY ((ARRAY['RECEIPT'::character varying, 'PUTAWAY'::character varying, 'PICK'::character varying, 'PUT_BACK'::character varying, 'MOVE'::character varying, 'TRANSFER_OUT'::character varying, 'TRANSFER_IN'::character varying, 'ADJUSTMENT'::character varying, 'COUNT_CORRECTION'::character varying, 'RETURN_IN'::character varying, 'STATUS_CHANGE'::character varying, 'SCRAP'::character varying, 'CONSUMPTION'::character varying, 'SUPPLIER_RETURN'::character varying])::text[])))
);

--
-- Name: COLUMN stock_movement.from_stock_package_id; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_movement.from_stock_package_id IS 'The stock package the stock left, if any.';

--
-- Name: COLUMN stock_movement.to_stock_package_id; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_movement.to_stock_package_id IS 'The stock package the stock went into, if any.';

--
-- Name: COLUMN stock_movement.order_number; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_movement.order_number IS 'Snapshot of ordering.customer_order.order_number when order_id is set (SCRUM-153).';

--
-- Name: CONSTRAINT ck_stock_movement_put_back_carton ON stock_movement; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON CONSTRAINT ck_stock_movement_put_back_carton ON inventory.stock_movement IS 'kltn-docs 07 §4.5 step 14: a pick line''s put-back goes back into its carton. NOT VALID where loose put-backs exist.';

--
-- Name: CONSTRAINT ck_stock_movement_quarantine_exit ON stock_movement; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON CONSTRAINT ck_stock_movement_quarantine_exit ON inventory.stock_movement IS 'Kltn-docs 20 BR-21, 05 BR-14: QUARANTINE stock leaves quarantine by an approved adjustment or by the putaway of its release; QC_INSPECTION and RETURN_REQUEST_LINE are the old flows (team plan 4D-3/4D-4).';

--
-- Name: CONSTRAINT ck_stock_movement_return_receipt ON stock_movement; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON CONSTRAINT ck_stock_movement_return_receipt ON inventory.stock_movement IS 'Kltn-docs 03 BR-14: a return receipt brings each carton back whole into QUARANTINE, one RECEIPT line per carton.';

--
-- Name: stock_package; Type: TABLE; Schema: inventory; Owner: -
--

CREATE TABLE inventory.stock_package (
    id uuid NOT NULL,
    lpn character varying(30) NOT NULL,
    inventory_item_id uuid NOT NULL,
    uom_conversion_id uuid NOT NULL,
    nominal_qty integer NOT NULL,
    received_qty integer,
    location_code character varying(64) NOT NULL,
    status character varying(16) DEFAULT 'RECEIVING'::character varying NOT NULL,
    goods_receipt_line_id uuid,
    closed_at timestamp with time zone,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_stock_package_closed CHECK ((((status)::text = ANY ((ARRAY['CONSUMED'::character varying, 'LOST'::character varying, 'VOID'::character varying])::text[])) = (closed_at IS NOT NULL))),
    CONSTRAINT ck_stock_package_counted CHECK ((((status)::text = ANY ((ARRAY['RECEIVING'::character varying, 'VOID'::character varying])::text[])) OR (received_qty IS NOT NULL))),
    CONSTRAINT ck_stock_package_lpn CHECK (((lpn)::text ~ '^[A-Z0-9][A-Z0-9-]{3,29}$'::text)),
    CONSTRAINT ck_stock_package_nominal CHECK ((nominal_qty > 0)),
    CONSTRAINT ck_stock_package_received CHECK (((received_qty IS NULL) OR (received_qty >= 0))),
    CONSTRAINT ck_stock_package_standard_count CHECK ((((status)::text <> ALL ((ARRAY['RECEIVING'::character varying, 'IN_STOCK'::character varying])::text[])) OR (received_qty IS NULL) OR (received_qty = nominal_qty))),
    CONSTRAINT ck_stock_package_status CHECK (((status)::text = ANY ((ARRAY['RECEIVING'::character varying, 'IN_STOCK'::character varying, 'CONSUMED'::character varying, 'LOST'::character varying, 'VOID'::character varying])::text[])))
);

--
-- Name: TABLE stock_package; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON TABLE inventory.stock_package IS 'One physical carton with its own LPN. Its contents are the stock_item rows that point at it.';

--
-- Name: COLUMN stock_package.lpn; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_package.lpn IS 'License plate number printed on the label; unique everywhere.';

--
-- Name: COLUMN stock_package.nominal_qty; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_package.nominal_qty IS 'The packing unit''s factor when it was made.';

--
-- Name: COLUMN stock_package.received_qty; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_package.received_qty IS 'Counted into it at receipt; fixed once in stock.';

--
-- Name: COLUMN stock_package.location_code; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_package.location_code IS 'Where it is; always where its stock rows are.';

--
-- Name: CONSTRAINT ck_stock_package_standard_count ON stock_package; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON CONSTRAINT ck_stock_package_standard_count ON inventory.stock_package IS 'kltn-docs 03 BR-13, 20 BR-18: a carton is counted, and is in stock, only at its standard count.';

--
-- Name: uom_conversions; Type: TABLE; Schema: inventory; Owner: -
--

CREATE TABLE inventory.uom_conversions (
    id uuid NOT NULL,
    inventory_item_id uuid NOT NULL,
    unit_of_measure character varying(16) NOT NULL,
    factor integer NOT NULL,
    is_base boolean DEFAULT false NOT NULL,
    weight_kg numeric(10,3),
    length_cm numeric(10,2),
    width_cm numeric(10,2),
    height_cm numeric(10,2),
    default_purchase boolean DEFAULT false NOT NULL,
    active boolean DEFAULT true NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    default_shipping boolean DEFAULT false NOT NULL,
    CONSTRAINT ck_uom_conversions_base CHECK (((NOT is_base) OR ((factor = 1) AND active AND (weight_kg IS NULL) AND (length_cm IS NULL) AND (width_cm IS NULL) AND (height_cm IS NULL)))),
    CONSTRAINT ck_uom_conversions_default_purchase CHECK (((NOT default_purchase) OR active)),
    CONSTRAINT ck_uom_conversions_default_shipping CHECK (((NOT default_shipping) OR active)),
    CONSTRAINT ck_uom_conversions_factor CHECK ((factor >= 1)),
    CONSTRAINT ck_uom_conversions_size CHECK ((((length_cm IS NULL) OR (length_cm > (0)::numeric)) AND ((width_cm IS NULL) OR (width_cm > (0)::numeric)) AND ((height_cm IS NULL) OR (height_cm > (0)::numeric)))),
    CONSTRAINT ck_uom_conversions_unit CHECK (((unit_of_measure)::text ~ '^[A-Z0-9_]{1,16}$'::text)),
    CONSTRAINT ck_uom_conversions_weight CHECK (((weight_kg IS NULL) OR (weight_kg > (0)::numeric)))
);

--
-- Name: stock_package_balance; Type: VIEW; Schema: inventory; Owner: -
--

CREATE VIEW inventory.stock_package_balance AS
 SELECT p.id AS stock_package_id,
    p.lpn,
    i.sku,
    p.inventory_item_id,
    p.uom_conversion_id,
    u.unit_of_measure,
    p.nominal_qty,
    p.received_qty,
    p.location_code,
    p.status,
    s.id AS stock_item_id,
    s.status AS stock_status,
    s.lot_number,
    COALESCE(s.on_hand, 0) AS on_hand,
    COALESCE(s.reserved, 0) AS reserved,
        CASE
            WHEN ((s.status)::text = 'AVAILABLE'::text) THEN (s.on_hand - s.reserved)
            ELSE 0
        END AS available,
    p.goods_receipt_line_id,
    p.closed_at
   FROM (((inventory.stock_package p
     JOIN inventory.inventory_items i ON ((i.id = p.inventory_item_id)))
     JOIN inventory.uom_conversions u ON ((u.id = p.uom_conversion_id)))
     LEFT JOIN inventory.stock_item s ON ((s.stock_package_id = p.id)));

--
-- Name: VIEW stock_package_balance; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON VIEW inventory.stock_package_balance IS 'One row per LPN carton with its stock row: lot, stock status, on hand, reserved, available (team plan 4C-3).';

--
-- Name: stock_reservation; Type: TABLE; Schema: inventory; Owner: -
--

CREATE TABLE inventory.stock_reservation (
    id uuid NOT NULL,
    stock_item_id uuid,
    order_id uuid NOT NULL,
    root_request_id uuid NOT NULL,
    request_id uuid NOT NULL,
    quantity integer NOT NULL,
    reserved_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone,
    status character varying(32) NOT NULL,
    release_reason character varying(32),
    closed_at timestamp with time zone,
    sku character varying(64) NOT NULL,
    allocated_from_id uuid,
    order_number character varying(32),
    warehouse_code character varying(64),
    CONSTRAINT ck_stock_reservation_allocation CHECK (((allocated_from_id IS NULL) OR ((order_id IS NOT NULL) AND (expires_at IS NULL)))),
    CONSTRAINT ck_stock_reservation_closed_at CHECK (((((status)::text = 'HELD'::text) AND (closed_at IS NULL)) OR (((status)::text <> 'HELD'::text) AND (closed_at IS NOT NULL)))),
    CONSTRAINT ck_stock_reservation_expired_had_deadline CHECK ((((status)::text <> 'EXPIRED'::text) OR (expires_at IS NOT NULL))),
    CONSTRAINT ck_stock_reservation_kind CHECK ((((stock_item_id IS NOT NULL) AND ((status)::text <> 'ALLOCATED'::text)) OR ((stock_item_id IS NULL) AND (allocated_from_id IS NULL) AND ((status)::text <> 'CONSUMED'::text)))),
    CONSTRAINT ck_stock_reservation_quantity CHECK ((quantity > 0)),
    CONSTRAINT ck_stock_reservation_status CHECK (((status)::text = ANY ((ARRAY['HELD'::character varying, 'ALLOCATED'::character varying, 'CONSUMED'::character varying, 'RELEASED'::character varying, 'EXPIRED'::character varying])::text[]))),
    CONSTRAINT ck_stock_reservation_warehouse CHECK (((warehouse_code IS NULL) OR (stock_item_id IS NULL)))
);

--
-- Name: TABLE stock_reservation; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON TABLE inventory.stock_reservation IS 'Holds on stock. stock_item_id NULL: a SKU reservation (soft, expires). Otherwise a hold on one stock row: an allocation, a production hold, or a checkout hold made before SCRUM-152.';

--
-- Name: COLUMN stock_reservation.stock_item_id; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_reservation.stock_item_id IS 'The stock row held; NULL for a SKU reservation (checkout hold on a SKU, no location, SCRUM-152).';

--
-- Name: COLUMN stock_reservation.sku; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_reservation.sku IS 'The SKU held. For a row on a stock item it is that item''s SKU (tg_stock_reservation_sku).';

--
-- Name: COLUMN stock_reservation.allocated_from_id; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_reservation.allocated_from_id IS 'The SKU reservation this allocation was made from at release (F-FUL step 02), kept through a reallocation after a short pick.';

--
-- Name: COLUMN stock_reservation.order_number; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_reservation.order_number IS 'Snapshot of ordering.customer_order.order_number for the lot trace (SCRUM-153); NULL until the order row exists.';

--
-- Name: COLUMN stock_reservation.warehouse_code; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON COLUMN inventory.stock_reservation.warehouse_code IS 'The warehouse a SKU reservation is held at (20 §5.6, BR-17): an order of a contract holds its stock at its shipping warehouse only. Null for a checkout hold, promised against the whole system.';

--
-- Name: delivery_log; Type: TABLE; Schema: notification; Owner: -
--

CREATE TABLE notification.delivery_log (
    id uuid NOT NULL,
    template_code character varying(64),
    channel character varying(16) NOT NULL,
    recipient character varying(500) NOT NULL,
    status character varying(16) NOT NULL,
    error character varying(1000),
    sent_at timestamp with time zone,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    external_reference character varying(100),
    operation_reference character varying(100),
    terminal boolean DEFAULT false NOT NULL,
    delivery_generation integer DEFAULT 0 NOT NULL,
    attempt_number integer DEFAULT 1 NOT NULL,
    provider character varying(16),
    provider_message_id character varying(100),
    next_attempt_at timestamp with time zone,
    provider_status character varying(24),
    provider_status_at timestamp with time zone,
    CONSTRAINT ck_delivery_attempt_number CHECK ((attempt_number > 0)),
    CONSTRAINT ck_delivery_log_channel CHECK (((channel)::text = ANY ((ARRAY['EMAIL'::character varying, 'SMS'::character varying, 'PUSH'::character varying, 'API'::character varying])::text[]))),
    CONSTRAINT ck_delivery_log_next_attempt CHECK (((next_attempt_at IS NULL) OR (((status)::text = 'FAILED'::text) AND (NOT terminal)))),
    CONSTRAINT ck_delivery_log_provider CHECK (((provider IS NULL) OR ((provider)::text = ANY ((ARRAY['RESEND'::character varying, 'SMTP'::character varying, 'RECORDING'::character varying])::text[])))),
    CONSTRAINT ck_delivery_log_provider_message CHECK (((provider_message_id IS NULL) OR (((status)::text = 'SENT'::text) AND (provider IS NOT NULL)))),
    CONSTRAINT ck_delivery_log_provider_report CHECK ((((provider_status IS NULL) = (provider_status_at IS NULL)) AND ((provider_status IS NULL) OR (provider_message_id IS NOT NULL)))),
    CONSTRAINT ck_delivery_log_provider_status CHECK (((provider_status IS NULL) OR ((provider_status)::text = ANY ((ARRAY['DELIVERY_DELAYED'::character varying, 'DELIVERED'::character varying, 'BOUNCED'::character varying, 'COMPLAINED'::character varying, 'FAILED'::character varying])::text[])))),
    CONSTRAINT ck_delivery_log_skipped_terminal CHECK ((((status)::text <> 'SKIPPED'::text) OR terminal)),
    CONSTRAINT ck_delivery_log_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'SENT'::character varying, 'FAILED'::character varying, 'SKIPPED'::character varying])::text[]))),
    CONSTRAINT delivery_log_delivery_generation_check CHECK ((delivery_generation >= 0))
);

--
-- Name: COLUMN delivery_log.provider_message_id; Type: COMMENT; Schema: notification; Owner: -
--

COMMENT ON COLUMN notification.delivery_log.provider_message_id IS 'The provider''s id of a sent message (Resend email id); delivery webhooks are matched on it.';

--
-- Name: COLUMN delivery_log.next_attempt_at; Type: COMMENT; Schema: notification; Owner: -
--

COMMENT ON COLUMN notification.delivery_log.next_attempt_at IS 'A failed attempt that will be retried: not before this time (Retry-After or back-off).';

--
-- Name: COLUMN delivery_log.provider_status; Type: COMMENT; Schema: notification; Owner: -
--

COMMENT ON COLUMN notification.delivery_log.provider_status IS 'Last outcome the provider reported after accepting the message (webhook): DELIVERED, BOUNCED, COMPLAINED, DELIVERY_DELAYED, FAILED.';

--
-- Name: preference; Type: TABLE; Schema: notification; Owner: -
--

CREATE TABLE notification.preference (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    channel character varying(16) NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_preference_channel CHECK (((channel)::text = ANY ((ARRAY['EMAIL'::character varying, 'SMS'::character varying, 'PUSH'::character varying])::text[])))
);

--
-- Name: template; Type: TABLE; Schema: notification; Owner: -
--

CREATE TABLE notification.template (
    id uuid NOT NULL,
    code character varying(64) NOT NULL,
    channel character varying(16) NOT NULL,
    subject character varying(300),
    body character varying(4000) NOT NULL,
    locale character varying(10) DEFAULT 'vi'::character varying NOT NULL,
    active boolean DEFAULT true NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_template_channel CHECK (((channel)::text = ANY ((ARRAY['EMAIL'::character varying, 'SMS'::character varying, 'PUSH'::character varying])::text[])))
);

--
-- Name: user_notification; Type: TABLE; Schema: notification; Owner: -
--

CREATE TABLE notification.user_notification (
    id uuid NOT NULL,
    recipient_id uuid NOT NULL,
    category character varying(40) NOT NULL,
    severity character varying(8) NOT NULL,
    title character varying(200) NOT NULL,
    body character varying(1000),
    link character varying(300),
    source_type character varying(40),
    source_id character varying(100),
    dedupe_key character varying(200) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    read_at timestamp with time zone,
    CONSTRAINT ck_user_notification_link CHECK (((link IS NULL) OR (((link)::text ~~ '/%'::text) AND ((link)::text !~~ '//%'::text)))),
    CONSTRAINT ck_user_notification_read CHECK (((read_at IS NULL) OR (read_at >= created_at))),
    CONSTRAINT ck_user_notification_severity CHECK (((severity)::text = ANY ((ARRAY['INFO'::character varying, 'WARN'::character varying, 'CRITICAL'::character varying])::text[]))),
    CONSTRAINT ck_user_notification_text CHECK (((btrim((category)::text) <> ''::text) AND (btrim((title)::text) <> ''::text) AND (btrim((dedupe_key)::text) <> ''::text)))
);

--
-- Name: TABLE user_notification; Type: COMMENT; Schema: notification; Owner: -
--

COMMENT ON TABLE notification.user_notification IS 'In-app inbox, one row per recipient. Posted through notification.api.Inbox; read only by its recipient.';

--
-- Name: COLUMN user_notification.dedupe_key; Type: COMMENT; Schema: notification; Owner: -
--

COMMENT ON COLUMN notification.user_notification.dedupe_key IS 'Chosen by the poster; the same key for the same recipient is posted once.';

--
-- Name: contract_payment_installment; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.contract_payment_installment (
    id uuid NOT NULL,
    contract_id uuid NOT NULL,
    seq smallint NOT NULL,
    name character varying(100) NOT NULL,
    milestone character varying(16) NOT NULL,
    percent numeric(5,2),
    amount numeric(19,4) NOT NULL,
    due_days integer,
    delivery_batch_id uuid,
    CONSTRAINT ck_contract_payment_installment_amount CHECK (((amount > (0)::numeric) AND (amount = trunc(amount)))),
    CONSTRAINT ck_contract_payment_installment_batch CHECK ((((milestone)::text <> 'ON_SIGNING'::text) OR (delivery_batch_id IS NULL))),
    CONSTRAINT ck_contract_payment_installment_due CHECK (((((milestone)::text = 'BEFORE_DELIVERY'::text) = (due_days IS NULL)) AND ((due_days IS NULL) OR ((due_days >= 0) AND (due_days <= 365))))),
    CONSTRAINT ck_contract_payment_installment_milestone CHECK (((milestone)::text = ANY ((ARRAY['ON_SIGNING'::character varying, 'BEFORE_DELIVERY'::character varying, 'AFTER_DELIVERY'::character varying])::text[]))),
    CONSTRAINT ck_contract_payment_installment_name CHECK ((btrim((name)::text) <> ''::text)),
    CONSTRAINT ck_contract_payment_installment_percent CHECK (((percent IS NULL) OR ((percent > (0)::numeric) AND (percent <= (100)::numeric)))),
    CONSTRAINT ck_contract_payment_installment_seq CHECK (((seq >= 1) AND (seq <= 20)))
);

--
-- Name: TABLE contract_payment_installment; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON TABLE ordering.contract_payment_installment IS '4B-4 (14 BR-13, 15 BR-18): the payment plan of a contract, adding up to the order''s total with tax.';

--
-- Name: customer_order; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.customer_order (
    id uuid NOT NULL,
    order_number character varying(32) NOT NULL,
    customer_id uuid,
    request_id uuid NOT NULL,
    status character varying(32) NOT NULL,
    total_amount numeric(19,4) NOT NULL,
    currency character varying(3) NOT NULL,
    placed_at timestamp with time zone NOT NULL,
    cancellation_reason character varying(500),
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    contact_name character varying(200),
    contact_email character varying(320),
    contact_phone character varying(32),
    shipping_recipient_name character varying(200),
    shipping_phone character varying(32),
    shipping_line1 character varying(255),
    shipping_line2 character varying(255),
    shipping_ward_code character varying(20),
    shipping_ward_name character varying(120),
    shipping_province_code character varying(20),
    shipping_province_name character varying(120),
    shipping_country_code character varying(2),
    shipping_postal_code character varying(20),
    billing_recipient_name character varying(200),
    billing_phone character varying(32),
    billing_line1 character varying(255),
    billing_line2 character varying(255),
    billing_ward_code character varying(20),
    billing_ward_name character varying(120),
    billing_province_code character varying(20),
    billing_province_name character varying(120),
    billing_country_code character varying(2),
    billing_postal_code character varying(20),
    warehouse_id uuid,
    released_at timestamp with time zone,
    released_by uuid,
    cancellation_reason_code character varying(32),
    cancellation_retained_amount numeric(19,4),
    cancellation_fee_reason character varying(500),
    cancellation_fee_detail character varying(2000),
    cancellation_fee_amount numeric(19,4),
    printing_started_at timestamp with time zone,
    packed_at timestamp with time zone,
    hold_reason character varying(24),
    status_before_hold character varying(32),
    hold_note character varying(1000),
    shipped_at timestamp with time zone,
    delivered_at timestamp with time zone,
    delivery_failure_reason character varying(24),
    completed_at timestamp with time zone,
    refunded_at timestamp with time zone,
    closed_at timestamp with time zone,
    allow_partial_shipment boolean DEFAULT false NOT NULL,
    fulfilment_started_at timestamp with time zone,
    goods_left_at timestamp with time zone,
    closed_amount numeric(19,4) DEFAULT 0 NOT NULL,
    tax_amount numeric(19,4) DEFAULT 0 NOT NULL,
    net_amount numeric(19,4) GENERATED ALWAYS AS ((total_amount - tax_amount)) STORED,
    contract_signed_at timestamp with time zone,
    shipping_warehouse_id uuid,
    shipping_warehouse_chosen_at timestamp with time zone,
    shipping_warehouse_chosen_by uuid,
    first_labeled_at timestamp with time zone,
    CONSTRAINT ck_order_awaiting_stock CHECK ((((status)::text <> 'AWAITING_STOCK'::text) OR ((contract_signed_at IS NOT NULL) AND (shipping_warehouse_id IS NOT NULL)))),
    CONSTRAINT ck_order_cancellation_code CHECK ((((status)::text = 'CANCELLED'::text) = (cancellation_reason_code IS NOT NULL))),
    CONSTRAINT ck_order_cancellation_code_values CHECK (((cancellation_reason_code)::text = ANY ((ARRAY['CUSTOMER_REQUEST'::character varying, 'PAYMENT_NOT_RECEIVED'::character varying, 'PAYMENT_FAILED'::character varying, 'OUT_OF_STOCK'::character varying, 'SUSPECTED_FRAUD'::character varying, 'CREDIT_REJECTED'::character varying, 'DUPLICATE_ORDER'::character varying, 'PRODUCTION_ISSUE'::character varying, 'REPLACEMENT_WITHDRAWN'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT ck_order_cancellation_fee CHECK ((((cancellation_fee_reason IS NULL) = (cancellation_fee_detail IS NULL)) AND ((cancellation_fee_reason IS NULL) = (cancellation_fee_amount IS NULL)) AND ((cancellation_fee_amount IS NULL) OR (((status)::text = 'CANCELLED'::text) AND (cancellation_fee_amount > (0)::numeric))))),
    CONSTRAINT ck_order_cancellation_reason CHECK ((((status)::text <> 'CANCELLED'::text) OR (cancellation_reason IS NOT NULL))),
    CONSTRAINT ck_order_cancellation_retained CHECK (((cancellation_retained_amount IS NULL) OR (((status)::text = 'CANCELLED'::text) AND (cancellation_retained_amount >= (0)::numeric)))),
    CONSTRAINT ck_order_closed_amount CHECK (((closed_amount >= (0)::numeric) AND (closed_amount <= total_amount))),
    CONSTRAINT ck_order_closed_at CHECK ((((status)::text = 'CLOSED'::text) = (closed_at IS NOT NULL))),
    CONSTRAINT ck_order_completed_at CHECK ((((status)::text <> 'COMPLETED'::text) OR (completed_at IS NOT NULL))),
    CONSTRAINT ck_order_contract_signed CHECK (((contract_signed_at IS NULL) OR ((status)::text <> ALL ((ARRAY['DRAFT'::character varying, 'PENDING_CONTRACT'::character varying])::text[])))),
    CONSTRAINT ck_order_customer_or_guest CHECK (((customer_id IS NOT NULL) OR ((contact_name IS NOT NULL) AND (contact_email IS NOT NULL) AND (contact_phone IS NOT NULL) AND (shipping_recipient_name IS NOT NULL) AND (shipping_line1 IS NOT NULL) AND (shipping_ward_code IS NOT NULL) AND (shipping_province_code IS NOT NULL) AND ((shipping_country_code)::text = 'VN'::text) AND (billing_recipient_name IS NOT NULL) AND (billing_line1 IS NOT NULL) AND (billing_ward_code IS NOT NULL) AND (billing_province_code IS NOT NULL) AND ((billing_country_code)::text = 'VN'::text)))),
    CONSTRAINT ck_order_delivered_at CHECK ((((status)::text <> ALL ((ARRAY['DELIVERED'::character varying, 'RETURN_REQUESTED'::character varying, 'COMPLETED'::character varying])::text[])) OR (delivered_at IS NOT NULL))),
    CONSTRAINT ck_order_delivery_failure CHECK (((((status)::text = 'DELIVERY_FAILED'::text) = (delivery_failure_reason IS NOT NULL)) AND ((delivery_failure_reason IS NULL) OR ((delivery_failure_reason)::text = ANY ((ARRAY['CUSTOMER_ABSENT'::character varying, 'REFUSED'::character varying, 'WRONG_ADDRESS'::character varying, 'LOST'::character varying, 'DAMAGED'::character varying, 'OTHER'::character varying])::text[]))))),
    CONSTRAINT ck_order_fee_after_printing CHECK (((cancellation_fee_amount IS NULL) OR (printing_started_at IS NOT NULL))),
    CONSTRAINT ck_order_fee_within_total CHECK (((cancellation_fee_amount IS NULL) OR (cancellation_fee_amount <= total_amount))),
    CONSTRAINT ck_order_hold_note CHECK (((hold_note IS NULL) OR ((status)::text = 'ON_HOLD'::text))),
    CONSTRAINT ck_order_hold_reason CHECK (((((status)::text = 'ON_HOLD'::text) = (hold_reason IS NOT NULL)) AND ((hold_reason IS NULL) OR ((hold_reason)::text = ANY ((ARRAY['CREDIT'::character varying, 'PAYMENT'::character varying, 'ADDRESS'::character varying, 'INVENTORY'::character varying, 'CUSTOMER'::character varying, 'FRAUD'::character varying, 'OTHER'::character varying])::text[]))))),
    CONSTRAINT ck_order_hold_return CHECK ((((status_before_hold IS NULL) OR ((status)::text = 'ON_HOLD'::text)) AND (((status)::text <> 'ON_HOLD'::text) OR ((hold_reason)::text = 'CREDIT'::text) OR (status_before_hold IS NOT NULL)) AND ((status_before_hold IS NULL) OR ((status_before_hold)::text = ANY ((ARRAY['CONFIRMED'::character varying, 'AWAITING_STOCK'::character varying, 'IN_PRODUCTION'::character varying, 'READY_TO_FULFILL'::character varying, 'PICKING'::character varying, 'PARTIALLY_FULFILLED'::character varying, 'PACKED'::character varying])::text[]))))),
    CONSTRAINT ck_order_labeled_not_cancelled CHECK (((first_labeled_at IS NULL) OR ((status)::text <> 'CANCELLED'::text))),
    CONSTRAINT ck_order_refunded_at CHECK ((((status)::text <> ALL ((ARRAY['REFUNDED'::character varying, 'PARTIALLY_REFUNDED'::character varying])::text[])) OR (refunded_at IS NOT NULL))),
    CONSTRAINT ck_order_release_status CHECK ((((status)::text <> ALL ((ARRAY['IN_PRODUCTION'::character varying, 'READY_TO_FULFILL'::character varying])::text[])) OR (released_at IS NOT NULL))),
    CONSTRAINT ck_order_released CHECK (((released_at IS NULL) = (released_by IS NULL))),
    CONSTRAINT ck_order_released_from_shipping_warehouse CHECK ((((shipping_warehouse_id IS NULL) OR (warehouse_id IS NULL) OR (warehouse_id = shipping_warehouse_id)) AND ((contract_signed_at IS NULL) OR (released_at IS NULL) OR (shipping_warehouse_id IS NOT NULL)))),
    CONSTRAINT ck_order_released_warehouse CHECK (((released_at IS NULL) OR (warehouse_id IS NOT NULL))),
    CONSTRAINT ck_order_shipped_at CHECK ((((status)::text <> ALL ((ARRAY['SHIPPED'::character varying, 'DELIVERY_FAILED'::character varying, 'DELIVERED'::character varying, 'RETURN_REQUESTED'::character varying, 'COMPLETED'::character varying])::text[])) OR (shipped_at IS NOT NULL))),
    CONSTRAINT ck_order_shipping_warehouse CHECK ((((shipping_warehouse_id IS NULL) = (shipping_warehouse_chosen_at IS NULL)) AND ((shipping_warehouse_id IS NULL) = (shipping_warehouse_chosen_by IS NULL)) AND ((shipping_warehouse_id IS NULL) OR (contract_signed_at IS NOT NULL)))),
    CONSTRAINT ck_order_status CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'PENDING_CONTRACT'::character varying, 'PENDING_PAYMENT'::character varying, 'CONFIRMED'::character varying, 'AWAITING_STOCK'::character varying, 'IN_PRODUCTION'::character varying, 'READY_TO_FULFILL'::character varying, 'PICKING'::character varying, 'PARTIALLY_FULFILLED'::character varying, 'PACKED'::character varying, 'ON_HOLD'::character varying, 'SHIPPED'::character varying, 'DELIVERY_FAILED'::character varying, 'DELIVERED'::character varying, 'RETURN_REQUESTED'::character varying, 'RETURNED'::character varying, 'REFUNDED'::character varying, 'PARTIALLY_REFUNDED'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'CLOSED'::character varying])::text[]))),
    CONSTRAINT ck_order_total_non_negative CHECK ((total_amount >= (0)::numeric)),
    CONSTRAINT ck_order_totals CHECK (((tax_amount >= (0)::numeric) AND (tax_amount = trunc(tax_amount)) AND (total_amount >= tax_amount)))
);

--
-- Name: COLUMN customer_order.request_id; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.customer_order.request_id IS 'Idempotency key from the client; a resubmitted checkout returns the original order.';

--
-- Name: COLUMN customer_order.contact_email; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.customer_order.contact_email IS 'Checkout snapshot. Required for guest orders; never updated from a later customer profile edit.';

--
-- Name: COLUMN customer_order.printing_started_at; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.customer_order.printing_started_at IS 'When the first production order of the order entered In Production (17 BR-11): from here a cancellation is staff''s and may keep an agreed fee. Written once (tg_order_printing_started).';

--
-- Name: COLUMN customer_order.packed_at; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.customer_order.packed_at IS 'A package of the order was completed: from here the order is returned, not cancelled.';

--
-- Name: COLUMN customer_order.allow_partial_shipment; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.customer_order.allow_partial_shipment IS 'Sales allowed the order to ship in parts (PACK-PARTIAL); the warehouse ships it whole otherwise.';

--
-- Name: COLUMN customer_order.closed_amount; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.customer_order.closed_amount IS 'Value of the units closed out of the order (a closed remainder, a production shortfall), with their VAT: total_amount less what the order is worth now. "Paid in full" compares the money with total_amount - closed_amount.';

--
-- Name: COLUMN customer_order.tax_amount; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.customer_order.tax_amount IS '4B-3: the VAT of every line and fee line, each rounded to the dong (14 BR-21). 0 on orders placed before.';

--
-- Name: COLUMN customer_order.net_amount; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.customer_order.net_amount IS '4B-3: the total before tax - goods and fee lines (14 BR-09); generated as total_amount - tax_amount.';

--
-- Name: COLUMN customer_order.contract_signed_at; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.customer_order.contract_signed_at IS '4B-5 (14 §4.3 step 15, BR-15): when the order''s sales contract was signed; null for an order placed at checkout.';

--
-- Name: COLUMN customer_order.shipping_warehouse_id; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.customer_order.shipping_warehouse_id IS 'The one warehouse an order of a contract ships from (17 BR-22): Sales chooses it once the order is CONFIRMED; it holds its stock there only, and changes only while nothing is held.';

--
-- Name: COLUMN customer_order.first_labeled_at; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.customer_order.first_labeled_at IS '4C-6: when the first shipping label of the order was printed; from then it is not cancelled and its delivery address does not change (kltn-docs 08 BR-04, 17 BR-12, BR-16)';

--
-- Name: delay_alert; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.delay_alert (
    id uuid NOT NULL,
    type character varying(24) NOT NULL,
    production_order_id uuid,
    delivery_batch_id uuid,
    subject_id uuid GENERATED ALWAYS AS (COALESCE(production_order_id, delivery_batch_id)) STORED,
    sales_order_id uuid NOT NULL,
    opened_at timestamp with time zone NOT NULL,
    closed_at timestamp with time zone,
    CONSTRAINT ck_delay_alert_closed CHECK (((closed_at IS NULL) OR (closed_at >= opened_at))),
    CONSTRAINT ck_delay_alert_subject CHECK (((((type)::text = ANY ((ARRAY['AT_RISK'::character varying, 'PRODUCTION_LATE'::character varying])::text[])) = (production_order_id IS NOT NULL)) AND (((type)::text = ANY ((ARRAY['PO_NEEDED'::character varying, 'DELIVERY_LATE'::character varying])::text[])) = (delivery_batch_id IS NOT NULL)))),
    CONSTRAINT ck_delay_alert_type CHECK (((type)::text = ANY ((ARRAY['AT_RISK'::character varying, 'PRODUCTION_LATE'::character varying, 'PO_NEEDED'::character varying, 'DELIVERY_LATE'::character varying])::text[])))
);

--
-- Name: TABLE delay_alert; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON TABLE ordering.delay_alert IS 'Delay alerts of the production schedule (kltn-docs 17 §4.12, BR-30): AT_RISK, PRODUCTION_LATE on a production order; PO_NEEDED, DELIVERY_LATE on a delivery batch. Opened and closed by the system; they never block anything.';

--
-- Name: delivery_batch; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.delivery_batch (
    id uuid NOT NULL,
    contract_id uuid NOT NULL,
    seq smallint NOT NULL,
    window_start date,
    window_end date,
    CONSTRAINT ck_delivery_batch_seq CHECK (((seq >= 1) AND (seq <= 20))),
    CONSTRAINT ck_delivery_batch_window CHECK ((((window_start IS NULL) = (window_end IS NULL)) AND ((window_start IS NULL) OR (window_start <= window_end))))
);

--
-- Name: TABLE delivery_batch; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON TABLE ordering.delivery_batch IS '4B-4 (14 BR-23): a delivery batch of a contract''s schedule - its window and, in delivery_batch_line, its cartons.';

--
-- Name: delivery_batch_hold; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.delivery_batch_hold (
    reservation_id uuid NOT NULL,
    delivery_batch_id uuid NOT NULL,
    order_id uuid NOT NULL,
    order_line_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: TABLE delivery_batch_hold; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON TABLE ordering.delivery_batch_hold IS '4B-8 (17 §4.2 step 3, BR-29): the delivery batch a hold of the order (a SKU reservation, or an allocation after release) stands for. A batch of the order''s own contract, a line it carries.';

--
-- Name: delivery_batch_line; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.delivery_batch_line (
    id uuid NOT NULL,
    delivery_batch_id uuid NOT NULL,
    order_line_id uuid NOT NULL,
    cartons integer NOT NULL,
    CONSTRAINT ck_delivery_batch_line_cartons CHECK (((cartons >= 1) AND (cartons <= 10000000)))
);

--
-- Name: delivery_batch_release; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.delivery_batch_release (
    delivery_batch_id uuid NOT NULL,
    order_id uuid NOT NULL,
    seq smallint NOT NULL,
    warehouse_id uuid NOT NULL,
    released_at timestamp with time zone NOT NULL,
    released_by uuid NOT NULL,
    CONSTRAINT ck_delivery_batch_release_seq CHECK (((seq >= 1) AND (seq <= 20)))
);

--
-- Name: TABLE delivery_batch_release; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON TABLE ordering.delivery_batch_release IS '4B-8 (17 BR-03, BR-29): a delivery batch released to the shipping warehouse - in schedule order, the batch before it already handed over, from the order''s shipping warehouse. Written once.';

--
-- Name: delivery_batch_window_change; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.delivery_batch_window_change (
    id uuid NOT NULL,
    delivery_batch_id uuid NOT NULL,
    order_id uuid NOT NULL,
    old_window_start date NOT NULL,
    old_window_end date NOT NULL,
    new_window_start date NOT NULL,
    new_window_end date NOT NULL,
    reason_code character varying(24) NOT NULL,
    note character varying(1000) NOT NULL,
    evidence_file_key character varying(512),
    evidence_file_name character varying(255),
    evidence_message_id uuid,
    changed_by uuid NOT NULL,
    changed_at timestamp with time zone NOT NULL,
    CONSTRAINT ck_delivery_batch_window_change_evidence CHECK ((((evidence_file_key IS NULL) = (evidence_file_name IS NULL)) AND (num_nonnulls(evidence_file_key, evidence_message_id) = 1))),
    CONSTRAINT ck_delivery_batch_window_change_not_past CHECK ((new_window_start >= ((changed_at AT TIME ZONE 'Asia/Ho_Chi_Minh'::text))::date)),
    CONSTRAINT ck_delivery_batch_window_change_note CHECK ((btrim((note)::text) <> ''::text)),
    CONSTRAINT ck_delivery_batch_window_change_reason CHECK (((reason_code)::text = ANY ((ARRAY['CUSTOMER_REQUEST'::character varying, 'SELLER_DELAY'::character varying])::text[]))),
    CONSTRAINT ck_delivery_batch_window_change_window CHECK (((new_window_start <= new_window_end) AND (old_window_start <= old_window_end) AND ((new_window_start IS DISTINCT FROM old_window_start) OR (new_window_end IS DISTINCT FROM old_window_end))))
);

--
-- Name: TABLE delivery_batch_window_change; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON TABLE ordering.delivery_batch_window_change IS '4B-8 (17 BR-28): a delivery window moved by Sales with the customer''s consent. The latest row of a batch is its window in force; the signed contract keeps the window it was signed with. Append-only.';

--
-- Name: order_cancellation_request; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.order_cancellation_request (
    id uuid NOT NULL,
    order_id uuid NOT NULL,
    requested_by uuid,
    reason_code character varying(32) NOT NULL,
    note character varying(1000),
    requested_at timestamp with time zone NOT NULL,
    status character varying(16) DEFAULT 'PENDING'::character varying NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_note character varying(1000),
    retained_percent numeric(5,2),
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_order_cancellation_request_decided CHECK ((((status)::text = 'PENDING'::text) = ((decided_by IS NULL) AND (decided_at IS NULL)))),
    CONSTRAINT ck_order_cancellation_request_other CHECK ((((reason_code)::text <> 'OTHER'::text) OR (note IS NOT NULL))),
    CONSTRAINT ck_order_cancellation_request_reason CHECK (((reason_code)::text = ANY ((ARRAY['CUSTOMER_REQUEST'::character varying, 'PAYMENT_NOT_RECEIVED'::character varying, 'PAYMENT_FAILED'::character varying, 'OUT_OF_STOCK'::character varying, 'SUSPECTED_FRAUD'::character varying, 'CREDIT_REJECTED'::character varying, 'DUPLICATE_ORDER'::character varying, 'PRODUCTION_ISSUE'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT ck_order_cancellation_request_rejected CHECK ((((status)::text <> 'REJECTED'::text) OR (decision_note IS NOT NULL))),
    CONSTRAINT ck_order_cancellation_request_retained CHECK (((retained_percent IS NULL) OR (((status)::text = 'APPROVED'::text) AND (retained_percent >= (0)::numeric) AND (retained_percent <= (100)::numeric)))),
    CONSTRAINT ck_order_cancellation_request_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying, 'EXPIRED'::character varying])::text[])))
);

--
-- Name: COLUMN order_cancellation_request.status; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.order_cancellation_request.status IS 'PENDING until Sales decides (APPROVED / REJECTED), or EXPIRED: closed by the system because the order was packed, shipped, delivered or cancelled meanwhile (decided_by NULL, decision_note says why).';

--
-- Name: order_credit_check; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.order_credit_check (
    id uuid NOT NULL,
    order_id uuid NOT NULL,
    checked_at timestamp with time zone NOT NULL,
    credit_limit numeric(19,4) NOT NULL,
    exposure numeric(19,4) NOT NULL,
    order_amount numeric(19,4) NOT NULL,
    outcome character varying(16) NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    note character varying(1000),
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_order_credit_check_amounts CHECK (((credit_limit >= (0)::numeric) AND (exposure >= (0)::numeric) AND (order_amount > (0)::numeric))),
    CONSTRAINT ck_order_credit_check_decided CHECK (((((outcome)::text = ANY ((ARRAY['APPROVED'::character varying, 'REJECTED'::character varying])::text[])) AND (decided_by IS NOT NULL) AND (decided_at IS NOT NULL) AND (note IS NOT NULL)) OR (((outcome)::text = ANY ((ARRAY['WITHIN_LIMIT'::character varying, 'OVER_LIMIT'::character varying, 'OVERDUE'::character varying])::text[])) AND (decided_by IS NULL) AND (decided_at IS NULL)))),
    CONSTRAINT ck_order_credit_check_outcome CHECK (((outcome)::text = ANY ((ARRAY['WITHIN_LIMIT'::character varying, 'OVER_LIMIT'::character varying, 'OVERDUE'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying])::text[]))),
    CONSTRAINT ck_order_credit_check_within CHECK ((((outcome)::text <> 'WITHIN_LIMIT'::text) OR ((exposure + order_amount) <= credit_limit)))
);

--
