    CONSTRAINT ck_order_line_tax CHECK ((((tax_rate IS NULL) = (tax_amount IS NULL)) AND ((tax_rate IS NULL) OR ((tax_rate >= (0)::numeric) AND (tax_rate < (100)::numeric) AND (tax_amount = round(((round(((quantity)::numeric * unit_price), 0) * tax_rate) / (100)::numeric), 0)))))),
    CONSTRAINT ck_order_line_unit_price CHECK ((unit_price >= (0)::numeric))
);

