--
-- Name: production_order; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.production_order (
    id uuid NOT NULL,
    code character varying(32) NOT NULL,
    sales_order_id uuid NOT NULL,
    delivery_batch_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    producer_id uuid NOT NULL,
    receiving_warehouse_id uuid NOT NULL,
    need_by_date date NOT NULL,
    status character varying(24) NOT NULL,
    sample_approval_required boolean NOT NULL,
    sample_required_by_default boolean NOT NULL,
    sample_waiver_reason character varying(500),
    unit_price numeric(19,4),
    currency character varying(3) DEFAULT 'VND'::character varying NOT NULL,
    note character varying(500),
    drawn_up_by uuid NOT NULL,
    submitted_at timestamp with time zone,
    approved_by uuid,
    approved_at timestamp with time zone,
    returned_reason character varying(500),
    sent_at timestamp with time zone,
    production_started_at timestamp with time zone,
    cancelled_by uuid,
    cancelled_at timestamp with time zone,
    cancellation_reason character varying(500),
    closed_by uuid,
    closed_at timestamp with time zone,
    closing_reason character varying(500),
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    expected_completion_date date,
    CONSTRAINT ck_production_order_accepted CHECK ((((status)::text <> ALL ((ARRAY['ACCEPTED'::character varying, 'SAMPLE_PENDING'::character varying])::text[])) OR (expected_completion_date IS NOT NULL))),
    CONSTRAINT ck_production_order_approval CHECK ((((approved_by IS NULL) = (approved_at IS NULL)) AND ((approved_by IS NULL) OR (approved_by <> drawn_up_by)) AND ((approved_at IS NULL) OR (submitted_at IS NOT NULL)))),
    CONSTRAINT ck_production_order_cancelled CHECK (((((status)::text = 'CANCELLED'::text) = (cancelled_at IS NOT NULL)) AND ((cancelled_at IS NULL) = (cancelled_by IS NULL)) AND ((cancelled_at IS NULL) = (cancellation_reason IS NULL)) AND ((cancellation_reason IS NULL) OR (btrim((cancellation_reason)::text) <> ''::text)))),
    CONSTRAINT ck_production_order_closed CHECK (((((status)::text = 'CLOSED'::text) = (closed_at IS NOT NULL)) AND ((closed_at IS NULL) = (closed_by IS NULL)) AND ((closed_at IS NULL) = (closing_reason IS NULL)) AND ((closing_reason IS NULL) OR (btrim((closing_reason)::text) <> ''::text)))),
    CONSTRAINT ck_production_order_code CHECK (((code)::text ~ '^PRD-[0-9]{8}-[0-9]{4,}$'::text)),
    CONSTRAINT ck_production_order_expected_completion CHECK (((expected_completion_date IS NULL) OR ((status)::text <> ALL ((ARRAY['DRAFT'::character varying, 'PENDING_APPROVAL'::character varying, 'SENT'::character varying])::text[])))),
    CONSTRAINT ck_production_order_price CHECK (((unit_price IS NULL) OR (unit_price >= (0)::numeric))),
    CONSTRAINT ck_production_order_returned CHECK ((((status)::text <> 'DRAFT'::text) OR (submitted_at IS NULL) OR (returned_reason IS NOT NULL))),
    CONSTRAINT ck_production_order_sample CHECK ((sample_approval_required OR (NOT sample_required_by_default) OR (sample_waiver_reason IS NOT NULL))),
    CONSTRAINT ck_production_order_sample_pending CHECK ((((status)::text <> 'SAMPLE_PENDING'::text) OR sample_approval_required)),
    CONSTRAINT ck_production_order_sent CHECK ((((sent_at IS NULL) = (approved_at IS NULL)) AND ((((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'PENDING_APPROVAL'::character varying])::text[])) = (sent_at IS NULL)) OR ((status)::text = 'CANCELLED'::text)))),
    CONSTRAINT ck_production_order_started CHECK (((((status)::text = ANY ((ARRAY['IN_PRODUCTION'::character varying, 'PARTIALLY_RECEIVED'::character varying, 'RECEIVED'::character varying])::text[])) <= (production_started_at IS NOT NULL)) AND ((production_started_at IS NULL) OR ((status)::text = ANY ((ARRAY['IN_PRODUCTION'::character varying, 'PARTIALLY_RECEIVED'::character varying, 'RECEIVED'::character varying, 'CLOSED'::character varying])::text[]))))),
    CONSTRAINT ck_production_order_status CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'PENDING_APPROVAL'::character varying, 'SENT'::character varying, 'ACCEPTED'::character varying, 'SAMPLE_PENDING'::character varying, 'IN_PRODUCTION'::character varying, 'PARTIALLY_RECEIVED'::character varying, 'RECEIVED'::character varying, 'CANCELLED'::character varying, 'CLOSED'::character varying])::text[]))),
    CONSTRAINT ck_production_order_submitted CHECK ((((status)::text <> 'PENDING_APPROVAL'::text) OR (submitted_at IS NOT NULL))),
    CONSTRAINT ck_production_order_texts CHECK ((((sample_waiver_reason IS NULL) OR (btrim((sample_waiver_reason)::text) <> ''::text)) AND ((note IS NULL) OR (btrim((note)::text) <> ''::text)) AND ((returned_reason IS NULL) OR (btrim((returned_reason)::text) <> ''::text))))
);

--
-- Name: TABLE production_order; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON TABLE ordering.production_order IS 'What a producer makes for one delivery batch of a confirmed order of a contract (kltn-docs 17 §4.3, §5.3): drawn up by the Production Coordinator, approved by someone else, sent, received into the order''s shipping warehouse.';

