    CONSTRAINT ck_production_order_sample_round_reprint CHECK ((((round_no = 1) = (reprint_reason IS NULL)) AND ((reprint_reason IS NULL) OR ((reprint_reason)::text = ANY ((ARRAY['PRINT_DEFECT'::character varying, 'CUSTOMER_CHANGE'::character varying])::text[]))))),
    CONSTRAINT ck_production_order_sample_round_result CHECK (((result IS NULL) OR ((result)::text = ANY ((ARRAY['APPROVED'::character varying, 'REPRINT_REQUESTED'::character varying])::text[]))))
);

