    CONSTRAINT ck_quote_converted CHECK ((((status)::text = 'CONVERTED'::text) = ((converted_order_id IS NOT NULL) AND (converted_at IS NOT NULL)))),
    CONSTRAINT ck_quote_feedback CHECK ((((status)::text <> 'CHANGES_REQUESTED'::text) OR (customer_feedback IS NOT NULL))),
    CONSTRAINT ck_quote_response CHECK ((((status)::text <> ALL ((ARRAY['CHANGES_REQUESTED'::character varying, 'ACCEPTED'::character varying, 'CONVERTED'::character varying])::text[])) OR ((responded_at IS NOT NULL) AND (responded_by IS NOT NULL)))),
    CONSTRAINT ck_quote_revision CHECK ((revision >= 1)),
    CONSTRAINT ck_quote_sent CHECK ((((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'CANCELLED'::character varying])::text[])) OR ((sent_at IS NOT NULL) AND (sent_by IS NOT NULL)))),
    CONSTRAINT ck_quote_status CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'SENT'::character varying, 'CHANGES_REQUESTED'::character varying, 'ACCEPTED'::character varying, 'EXPIRED'::character varying, 'CANCELLED'::character varying, 'CONVERTED'::character varying])::text[]))),
    CONSTRAINT ck_quote_validity CHECK ((valid_until > created_at))
);

--
-- Name: COLUMN quote.requested_delivery_date; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.quote.requested_delivery_date IS 'SCRUM-502: the date the customer asks to receive the goods; copied onto every print line of the order the quote becomes. Null = none asked.';

--
-- Name: quote_fee_line; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.quote_fee_line (
    id uuid NOT NULL,
    quote_id uuid NOT NULL,
    kind character varying(16) NOT NULL,
    sku character varying(64),
    amount numeric(19,4),
    tax_class character varying(16),
    tax_rate numeric(5,2),
    CONSTRAINT ck_quote_fee_line_amount CHECK (((((kind)::text = 'PLATE_FEE'::text) OR (amount IS NOT NULL)) AND ((amount IS NULL) OR ((amount >= (0)::numeric) AND (amount = trunc(amount)) AND (((kind)::text = 'PLATE_FEE'::text) OR (amount > (0)::numeric)))))),
    CONSTRAINT ck_quote_fee_line_kind CHECK (((kind)::text = ANY ((ARRAY['PLATE_FEE'::character varying, 'SHIPPING_FEE'::character varying])::text[]))),
    CONSTRAINT ck_quote_fee_line_sku CHECK ((((kind)::text = 'PLATE_FEE'::text) = (sku IS NOT NULL))),
    CONSTRAINT ck_quote_fee_line_tax CHECK ((((tax_class IS NULL) = (tax_rate IS NULL)) AND ((tax_class IS NULL) OR (((tax_class)::text = ANY ((ARRAY['STANDARD'::character varying, 'REDUCED'::character varying, 'EXEMPT'::character varying])::text[])) AND (tax_rate >= (0)::numeric) AND (tax_rate < (100)::numeric)))))
);

--
-- Name: quote_line; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.quote_line (
    id uuid NOT NULL,
    quote_id uuid NOT NULL,
    line_no integer NOT NULL,
    blank_sku character varying(64),
    design_snapshot_id uuid,
    print_spec character varying(2000),
    quantity integer,
    accepted_quantity integer,
    accepted_unit_price numeric(19,4),
    sku character varying(64),
    uom_conversion_id uuid,
    cartons integer,
    units_per_carton integer,
    accepted_cartons integer,
    tax_class character varying(16),
    tax_rate numeric(5,2),
    CONSTRAINT ck_quote_line_accepted CHECK (((COALESCE(accepted_quantity, accepted_cartons) IS NULL) = (accepted_unit_price IS NULL))),
    CONSTRAINT ck_quote_line_accepted_values CHECK ((((accepted_quantity IS NULL) OR (accepted_quantity > 0)) AND ((accepted_cartons IS NULL) OR ((accepted_cartons > 0) AND (((accepted_cartons)::bigint * units_per_carton) <= 10000000))) AND ((accepted_unit_price IS NULL) OR ((accepted_unit_price > (0)::numeric) AND (accepted_unit_price = trunc(accepted_unit_price)))))),
    CONSTRAINT ck_quote_line_cartons CHECK (((cartons IS NULL) OR ((cartons > 0) AND (((cartons)::bigint * units_per_carton) <= 10000000)))),
    CONSTRAINT ck_quote_line_no CHECK ((line_no >= 1)),
    CONSTRAINT ck_quote_line_quantity CHECK ((quantity > 0)),
    CONSTRAINT ck_quote_line_shape CHECK ((((sku IS NULL) AND (uom_conversion_id IS NULL) AND (cartons IS NULL) AND (units_per_carton IS NULL) AND (accepted_cartons IS NULL) AND (blank_sku IS NOT NULL) AND (design_snapshot_id IS NOT NULL) AND (quantity IS NOT NULL)) OR ((sku IS NOT NULL) AND (uom_conversion_id IS NOT NULL) AND (cartons IS NOT NULL) AND (units_per_carton IS NOT NULL) AND (blank_sku IS NULL) AND (design_snapshot_id IS NULL) AND (quantity IS NULL) AND (print_spec IS NULL) AND (accepted_quantity IS NULL)))),
    CONSTRAINT ck_quote_line_tax CHECK ((((tax_class IS NULL) = (tax_rate IS NULL)) AND ((tax_class IS NULL) OR ((sku IS NOT NULL) AND ((tax_class)::text = ANY ((ARRAY['STANDARD'::character varying, 'REDUCED'::character varying, 'EXEMPT'::character varying])::text[])) AND (tax_rate >= (0)::numeric) AND (tax_rate < (100)::numeric))))),
    CONSTRAINT ck_quote_line_units_per_carton CHECK (((units_per_carton IS NULL) OR (units_per_carton > 1)))
);

--
-- Name: COLUMN quote_line.sku; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.quote_line.sku IS '4B-2: the customer''s own SKU the line quotes (14 BR-04); null on a line drafted before, which names blank_sku and design_snapshot_id.';

--
-- Name: COLUMN quote_line.cartons; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.quote_line.cartons IS '4B-2: cartons Sales proposes (14 BR-08); the customer accepts accepted_cartons, at or above the line''s MOQ in cartons.';

--
-- Name: COLUMN quote_line.units_per_carton; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.quote_line.units_per_carton IS '4B-2: pieces per carton, the carton unit''s factor when the line was written, fixed on the line (14 BR-08, 01 BR-10).';

--
-- Name: quote_price_tier; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.quote_price_tier (
    quote_line_id uuid NOT NULL,
