    unit_price numeric(19,4) NOT NULL,
    CONSTRAINT ck_quote_price_tier_price CHECK (((unit_price > (0)::numeric) AND (unit_price = trunc(unit_price)))),
    CONSTRAINT ck_quote_price_tier_quantity CHECK ((min_quantity > 0))
);

--
-- Name: COLUMN quote_price_tier.min_quantity; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.quote_price_tier.min_quantity IS 'Where the tier starts: cartons on a carton line (14 BR-07), units on a line drafted before 4B-2. The price is per piece.';

--
-- Name: quote_status_history; Type: TABLE; Schema: ordering; Owner: -
--

