    CONSTRAINT ck_quote_status_history_offer CHECK ((((to_status)::text <> 'SENT'::text) OR (offer IS NOT NULL)))
);

--
-- Name: return_number_sequence; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.return_number_sequence (
