    CONSTRAINT ck_return_number_sequence_value CHECK ((last_value >= 0))
);

--
-- Name: return_request; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.return_request (
    id uuid NOT NULL,
    rma_number character varying(30) NOT NULL,
    order_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    status character varying(24) NOT NULL,
    reason_code character varying(24) NOT NULL,
    note character varying(2000),
    requested_at timestamp with time zone NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    rejection_reason character varying(500),
    received_at timestamp with time zone,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    order_number character varying(32) NOT NULL,
    request_id uuid NOT NULL,
    channel character varying(16) NOT NULL,
    requested_by uuid NOT NULL,
    requested_resolution character varying(16) DEFAULT 'REFUND'::character varying NOT NULL,
    currency character varying(3) DEFAULT 'VND'::character varying NOT NULL,
    decision_note character varying(1000),
    return_required boolean,
    return_deadline timestamp with time zone,
    received_by uuid,
    receiving_location_code character varying(64),
    window_override_reason character varying(500),
    money_mode character varying(16),
    settlement_amount numeric(19,4) DEFAULT 0 NOT NULL,
    proposed_by uuid,
    proposed_at timestamp with time zone,
    resolution_note character varying(1000),
    settled_by uuid,
    settled_at timestamp with time zone,
    refunded_amount numeric(19,4) DEFAULT 0 NOT NULL,
    offset_amount numeric(19,4) DEFAULT 0 NOT NULL,
    vat_adjustment_required boolean DEFAULT false NOT NULL,
    cancelled_by uuid,
    cancellation_reason character varying(500),
    closed_at timestamp with time zone,
    goods_receipt_id uuid,
    CONSTRAINT ck_return_request_amounts CHECK (((settlement_amount >= (0)::numeric) AND (refunded_amount >= (0)::numeric) AND (offset_amount >= (0)::numeric) AND (((status)::text <> 'RESOLVED'::text) OR ((refunded_amount + offset_amount) = settlement_amount)) AND (((status)::text = 'RESOLVED'::text) OR ((refunded_amount = (0)::numeric) AND (offset_amount = (0)::numeric))))),
    CONSTRAINT ck_return_request_approval_four_eyes CHECK ((((channel)::text <> 'BACK_OFFICE'::text) OR (return_required IS NULL) OR (decided_by <> requested_by))),
    CONSTRAINT ck_return_request_approved CHECK ((((status)::text <> ALL ((ARRAY['AWAITING_RETURN'::character varying, 'RECEIVED'::character varying, 'INSPECTED'::character varying, 'SETTLEMENT_PENDING'::character varying, 'RESOLVED'::character varying, 'EXPIRED'::character varying])::text[])) OR (return_required IS NOT NULL))),
    CONSTRAINT ck_return_request_awaiting CHECK ((((status)::text <> ALL ((ARRAY['AWAITING_RETURN'::character varying, 'RECEIVED'::character varying, 'EXPIRED'::character varying])::text[])) OR return_required)),
    CONSTRAINT ck_return_request_cancelled CHECK ((((status)::text = 'CANCELLED'::text) = ((cancelled_by IS NOT NULL) AND (cancellation_reason IS NOT NULL)))),
    CONSTRAINT ck_return_request_channel CHECK (((channel)::text = ANY ((ARRAY['PORTAL'::character varying, 'BACK_OFFICE'::character varying])::text[]))),
    CONSTRAINT ck_return_request_closed CHECK ((((status)::text = ANY ((ARRAY['RESOLVED'::character varying, 'REJECTED'::character varying, 'CANCELLED'::character varying, 'EXPIRED'::character varying])::text[])) = (closed_at IS NOT NULL))),
    CONSTRAINT ck_return_request_currency CHECK (((currency)::text ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT ck_return_request_deadline CHECK (((return_required IS TRUE) = (return_deadline IS NOT NULL))),
    CONSTRAINT ck_return_request_four_eyes CHECK (((settled_by IS NULL) OR (settled_by <> proposed_by))),
    CONSTRAINT ck_return_request_goods_back CHECK ((((goods_receipt_id IS NULL) OR ((received_at IS NOT NULL) AND (received_by IS NOT NULL) AND (receiving_location_code IS NOT NULL))) AND (((status)::text <> ALL ((ARRAY['RECEIVED'::character varying, 'SETTLEMENT_PENDING'::character varying])::text[])) OR (goods_receipt_id IS NOT NULL)))),
    CONSTRAINT ck_return_request_money_mode CHECK ((((money_mode IS NULL) OR ((money_mode)::text = 'REFUND'::text)) AND ((settlement_amount > (0)::numeric) = (money_mode IS NOT NULL)))),
    CONSTRAINT ck_return_request_other_note CHECK ((((reason_code)::text <> 'OTHER'::text) OR (note IS NOT NULL))),
    CONSTRAINT ck_return_request_proposed CHECK ((((proposed_at IS NULL) = (proposed_by IS NULL)) AND (((status)::text <> ALL ((ARRAY['SETTLEMENT_PENDING'::character varying, 'RESOLVED'::character varying])::text[])) OR (proposed_at IS NOT NULL)))),
    CONSTRAINT ck_return_request_reason CHECK (((reason_code)::text = ANY ((ARRAY['PRINT_DEFECT'::character varying, 'DESIGN_MISMATCH'::character varying, 'DAMAGED_IN_TRANSIT'::character varying, 'WRONG_ITEM'::character varying, 'SHORT_DELIVERY'::character varying, 'CHANGED_MIND'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT ck_return_request_rejected CHECK ((((status)::text = 'REJECTED'::text) = (rejection_reason IS NOT NULL))),
    CONSTRAINT ck_return_request_resolution CHECK (((requested_resolution)::text = 'REFUND'::text)),
    CONSTRAINT ck_return_request_reviewed CHECK ((((status)::text = ANY ((ARRAY['REQUESTED'::character varying, 'CANCELLED'::character varying])::text[])) OR ((decided_by IS NOT NULL) AND (decided_at IS NOT NULL)))),
    CONSTRAINT ck_return_request_settled CHECK ((((settled_at IS NULL) = (settled_by IS NULL)) AND (((status)::text = 'RESOLVED'::text) = (settled_at IS NOT NULL)))),
    CONSTRAINT ck_return_request_status CHECK (((status)::text = ANY ((ARRAY['REQUESTED'::character varying, 'AWAITING_RETURN'::character varying, 'RECEIVED'::character varying, 'SETTLEMENT_PENDING'::character varying, 'RESOLVED'::character varying, 'REJECTED'::character varying, 'CANCELLED'::character varying, 'EXPIRED'::character varying])::text[]))),
    CONSTRAINT ck_return_request_unreviewed CHECK ((((status)::text <> 'REQUESTED'::text) OR ((decided_at IS NULL) AND (return_required IS NULL)))),
    CONSTRAINT ck_return_request_vat CHECK ((vat_adjustment_required = (((status)::text = 'RESOLVED'::text) AND (settlement_amount > (0)::numeric)))),
    CONSTRAINT ck_return_request_window_override CHECK (((window_override_reason IS NULL) OR ((channel)::text = 'BACK_OFFICE'::text)))
);

--
-- Name: COLUMN return_request.note; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.return_request.note IS 'The customer''s description of the problem (required for reason OTHER).';

--
-- Name: COLUMN return_request.settlement_amount; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.return_request.settlement_amount IS 'What the accepted units not replaced are worth (unit price x credited units): refunded, credited, or set off against the order''s receivables.';

--
-- Name: COLUMN return_request.refunded_amount; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.return_request.refunded_amount IS 'A resolved return: what was paid already and is to be refunded (payment.order_settlement GOODS_RETURNED).';

--
-- Name: COLUMN return_request.offset_amount; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.return_request.offset_amount IS 'A resolved return: what its refund took off what the order''s installments still owed (team plan 4D-3); for a return of the QC era, what was set off against receivables or kept as credit.';

--
-- Name: COLUMN return_request.goods_receipt_id; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.return_request.goods_receipt_id IS 'The RETURN goods receipt whose confirmation brought the goods back (team plan 4D-3, kltn-docs 03 §4.2); set once.';

--
-- Name: return_request_discrepancy; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.return_request_discrepancy (
    id uuid NOT NULL,
    return_request_id uuid NOT NULL,
    return_request_line_id uuid,
    kind character varying(16) NOT NULL,
    sku character varying(64),
    quantity integer NOT NULL,
    note character varying(500),
    recorded_by uuid NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    CONSTRAINT ck_return_request_discrepancy_kind CHECK (((kind)::text = ANY ((ARRAY['SHORT'::character varying, 'EXCESS'::character varying, 'WRONG_ITEM'::character varying, 'UNEXPECTED_ITEM'::character varying])::text[]))),
    CONSTRAINT ck_return_request_discrepancy_line CHECK ((((kind)::text = 'UNEXPECTED_ITEM'::text) = (return_request_line_id IS NULL))),
    CONSTRAINT ck_return_request_discrepancy_quantity CHECK ((quantity > 0)),
    CONSTRAINT ck_return_request_discrepancy_unexpected CHECK ((((kind)::text <> 'UNEXPECTED_ITEM'::text) OR (sku IS NOT NULL) OR (note IS NOT NULL)))
);

--
-- Name: return_request_evidence; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.return_request_evidence (
    id uuid NOT NULL,
    return_request_id uuid NOT NULL,
