    content_type character varying(100) NOT NULL,
    size_bytes bigint NOT NULL,
    uploaded_by uuid NOT NULL,
    uploaded_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    CONSTRAINT ck_return_request_evidence_size CHECK ((size_bytes > 0)),
    CONSTRAINT ck_return_request_evidence_stage CHECK (((stage)::text = ANY ((ARRAY['CLAIM'::character varying, 'RECEIPT'::character varying, 'INSPECTION'::character varying])::text[])))
);

--
-- Name: return_request_line; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.return_request_line (
    id uuid NOT NULL,
    return_request_id uuid NOT NULL,
    order_line_id uuid NOT NULL,
    quantity integer NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    sku character varying(64) NOT NULL,
    custom_printed boolean NOT NULL,
    unit_price numeric(19,4) NOT NULL,
    approved_quantity integer,
    received_quantity integer,
    refund_quantity integer DEFAULT 0 NOT NULL,
    refund_amount numeric(19,4) DEFAULT 0 NOT NULL,
    CONSTRAINT ck_return_request_line_approved CHECK (((approved_quantity IS NULL) OR ((approved_quantity >= 0) AND (approved_quantity <= quantity)))),
    CONSTRAINT ck_return_request_line_price CHECK ((unit_price >= (0)::numeric)),
    CONSTRAINT ck_return_request_line_qty CHECK ((quantity > 0)),
    CONSTRAINT ck_return_request_line_received CHECK (((received_quantity IS NULL) OR (received_quantity >= 0))),
    CONSTRAINT ck_return_request_line_refund CHECK (((refund_quantity >= 0) AND (refund_amount >= (0)::numeric) AND (refund_quantity <= COALESCE(approved_quantity, 0)) AND (refund_quantity <= COALESCE(received_quantity, 0)) AND ((refund_quantity > 0) OR (refund_amount = (0)::numeric))))
);

--
-- Name: COLUMN return_request_line.refund_quantity; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.return_request_line.refund_quantity IS 'Units refunded (team plan 4D-3): at most approved and at most received on the return receipt.';

--
-- Name: COLUMN return_request_line.refund_amount; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON COLUMN ordering.return_request_line.refund_amount IS 'What the units refunded are worth with their VAT, as the order line charged them (kltn-docs 15 §4.5).';

--
-- Name: return_request_status_history; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.return_request_status_history (
    id uuid NOT NULL,
    return_request_id uuid NOT NULL,
    from_status character varying(24),
    to_status character varying(24) NOT NULL,
