    occurred_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    CONSTRAINT ck_return_request_status_history_change CHECK (((from_status)::text IS DISTINCT FROM (to_status)::text)),
    CONSTRAINT ck_return_request_status_history_status CHECK ((((to_status)::text ~ '^[A-Z_]{1,24}$'::text) AND ((from_status IS NULL) OR ((from_status)::text ~ '^[A-Z_]{1,24}$'::text))))
);

--
-- Name: sales_contract; Type: TABLE; Schema: ordering; Owner: -
--

CREATE TABLE ordering.sales_contract (
    id uuid NOT NULL,
    contract_number character varying(40) NOT NULL,
    order_id uuid NOT NULL,
    status character varying(16) NOT NULL,
    seller_name character varying(200) NOT NULL,
    seller_tax_code character varying(14) NOT NULL,
    seller_address character varying(500) NOT NULL,
    seller_representative character varying(200) NOT NULL,
    seller_representative_title character varying(100) NOT NULL,
    buyer_name character varying(200) NOT NULL,
    buyer_tax_code character varying(14),
    buyer_address character varying(500) NOT NULL,
    buyer_representative character varying(200) NOT NULL,
    buyer_representative_title character varying(100) NOT NULL,
    free_sample_rounds integer NOT NULL,
    sent_at timestamp with time zone,
    sent_by uuid,
    sent_document_key character varying(512),
    signed_on date,
    signed_file_key character varying(512),
    signed_file_name character varying(255),
    signed_at timestamp with time zone,
    signed_by uuid,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    cancellation_reason character varying(500),
    completed_at timestamp with time zone,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_sales_contract_cancelled CHECK (((((status)::text = 'CANCELLED'::text) = (cancelled_at IS NOT NULL)) AND ((cancelled_at IS NULL) = (cancelled_by IS NULL)) AND ((cancelled_at IS NULL) = (cancellation_reason IS NULL)) AND ((cancellation_reason IS NULL) OR (btrim((cancellation_reason)::text) <> ''::text)))),
    CONSTRAINT ck_sales_contract_completed CHECK ((((status)::text = 'COMPLETED'::text) = (completed_at IS NOT NULL))),
    CONSTRAINT ck_sales_contract_free_sample_rounds CHECK (((free_sample_rounds >= 0) AND (free_sample_rounds <= 100))),
    CONSTRAINT ck_sales_contract_sent CHECK ((((sent_at IS NULL) = (sent_by IS NULL)) AND ((sent_at IS NULL) = (sent_document_key IS NULL)) AND (((status)::text <> 'DRAFT'::text) OR (sent_at IS NULL)) AND (((status)::text <> ALL ((ARRAY['SENT'::character varying, 'SIGNED'::character varying, 'COMPLETED'::character varying])::text[])) OR (sent_at IS NOT NULL)))),
    CONSTRAINT ck_sales_contract_signed CHECK (((((status)::text = ANY ((ARRAY['SIGNED'::character varying, 'COMPLETED'::character varying])::text[])) = (signed_at IS NOT NULL)) AND ((signed_at IS NULL) = (signed_by IS NULL)) AND ((signed_at IS NULL) = (signed_on IS NULL)) AND ((signed_at IS NULL) = (signed_file_key IS NULL)) AND ((signed_at IS NULL) = (signed_file_name IS NULL)) AND ((signed_on IS NULL) OR (signed_on <= ((signed_at AT TIME ZONE 'Asia/Ho_Chi_Minh'::text))::date)))),
    CONSTRAINT ck_sales_contract_status CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'SENT'::character varying, 'SIGNED'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying])::text[])))
);

--
-- Name: TABLE sales_contract; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON TABLE ordering.sales_contract IS '4B-4 (14 §4.3, §5.2, BR-12, BR-14, BR-18): the sales contract of an order; goods, prices and totals are the order''s.';

--
-- Name: tax_rate; Type: TABLE; Schema: ordering; Owner: -
--

