    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_tax_rate_class CHECK (((tax_class)::text = ANY ((ARRAY['STANDARD'::character varying, 'REDUCED'::character varying, 'EXEMPT'::character varying])::text[]))),
    CONSTRAINT ck_tax_rate_rate CHECK (((rate >= (0)::numeric) AND (rate < (100)::numeric)))
);

--
-- Name: TABLE tax_rate; Type: COMMENT; Schema: ordering; Owner: -
--

COMMENT ON TABLE ordering.tax_rate IS '4B-3 (QD-9): the VAT rate of each product tax class; a quote line copies it with its price (14 BR-21).';

--
-- Name: installment; Type: TABLE; Schema: payment; Owner: -
--

CREATE TABLE payment.installment (
    id uuid NOT NULL,
    contract_id uuid NOT NULL,
    contract_installment_id uuid,
    order_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    contract_number character varying(40) NOT NULL,
    order_number character varying(32) NOT NULL,
    seq smallint NOT NULL,
    name character varying(100) NOT NULL,
    milestone character varying(16) NOT NULL,
    delivery_batch_id uuid,
    delivery_batch_seq smallint,
    amount numeric(19,4) NOT NULL,
    paid_amount numeric(19,4) DEFAULT 0 NOT NULL,
    currency character varying(3) NOT NULL,
    due_days integer,
    reached_at timestamp with time zone,
    due_date date,
    status character varying(16) NOT NULL,
    paid_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    reduced_amount numeric(19,4) DEFAULT 0 NOT NULL,
    CONSTRAINT ck_installment_amounts CHECK (((amount > (0)::numeric) AND (amount = trunc(amount)) AND (paid_amount >= (0)::numeric) AND (paid_amount = trunc(paid_amount)) AND (reduced_amount >= (0)::numeric) AND (reduced_amount = trunc(reduced_amount)) AND ((paid_amount + reduced_amount) <= amount))),
    CONSTRAINT ck_installment_batch CHECK (((((milestone)::text <> 'ON_SIGNING'::text) OR (delivery_batch_id IS NULL)) AND ((delivery_batch_id IS NULL) = (delivery_batch_seq IS NULL)) AND ((delivery_batch_seq IS NULL) OR ((delivery_batch_seq >= 1) AND (delivery_batch_seq <= 20))))),
    CONSTRAINT ck_installment_due_date CHECK (((due_date IS NOT NULL) = ((reached_at IS NOT NULL) AND ((milestone)::text <> 'BEFORE_DELIVERY'::text)))),
    CONSTRAINT ck_installment_due_days CHECK (((((milestone)::text = 'BEFORE_DELIVERY'::text) = (due_days IS NULL)) AND ((due_days IS NULL) OR ((due_days >= 0) AND (due_days <= 365))))),
    CONSTRAINT ck_installment_fee_item CHECK (((((milestone)::text = 'CANCELLATION_FEE'::text) = (contract_installment_id IS NULL)) AND (((milestone)::text <> 'CANCELLATION_FEE'::text) OR ((due_days = 0) AND (reached_at IS NOT NULL) AND (delivery_batch_id IS NULL) AND (reduced_amount = (0)::numeric) AND ((status)::text <> 'CANCELLED'::text))))),
    CONSTRAINT ck_installment_milestone CHECK (((milestone)::text = ANY ((ARRAY['ON_SIGNING'::character varying, 'BEFORE_DELIVERY'::character varying, 'AFTER_DELIVERY'::character varying, 'CANCELLATION_FEE'::character varying])::text[]))),
    CONSTRAINT ck_installment_name CHECK ((btrim((name)::text) <> ''::text)),
    CONSTRAINT ck_installment_seq CHECK (((((milestone)::text = 'CANCELLATION_FEE'::text) AND ((seq >= 21) AND (seq <= 40))) OR (((milestone)::text <> 'CANCELLATION_FEE'::text) AND ((seq >= 1) AND (seq <= 20))))),
    CONSTRAINT ck_installment_status CHECK (((status)::text = ANY ((ARRAY['NOT_DUE'::character varying, 'DUE'::character varying, 'PARTIALLY_PAID'::character varying, 'PAID'::character varying, 'OVERDUE'::character varying, 'CANCELLED'::character varying])::text[]))),
    CONSTRAINT ck_installment_status_facts CHECK ((((((status)::text = 'NOT_DUE'::text) AND (reached_at IS NULL) AND (paid_amount = (0)::numeric) AND (reduced_amount < amount)) OR (((status)::text = 'DUE'::text) AND (reached_at IS NOT NULL) AND (paid_amount = (0)::numeric) AND (reduced_amount < amount)) OR (((status)::text = 'PARTIALLY_PAID'::text) AND (paid_amount > (0)::numeric) AND ((paid_amount + reduced_amount) < amount)) OR (((status)::text = 'OVERDUE'::text) AND (due_date IS NOT NULL) AND ((paid_amount + reduced_amount) < amount)) OR (((status)::text = 'PAID'::text) AND (paid_amount > (0)::numeric) AND ((paid_amount + reduced_amount) = amount)) OR (((status)::text = 'CANCELLED'::text) AND (paid_amount < amount))) AND (((status)::text = 'PAID'::text) = (paid_at IS NOT NULL)) AND (((status)::text = 'CANCELLED'::text) = (cancelled_at IS NOT NULL))))
);

--
-- Name: TABLE installment; Type: COMMENT; Schema: payment; Owner: -
--

COMMENT ON TABLE payment.installment IS 'A signed contract''s payment installments (kltn-docs 15 §4.1, §5.1): made when the contract is signed, due when its milestone comes, paid by payment receipts; unpaid ones of a cancelled order are CANCELLED.';

--
-- Name: COLUMN installment.contract_installment_id; Type: COMMENT; Schema: payment; Owner: -
--

COMMENT ON COLUMN payment.installment.contract_installment_id IS 'The signed plan row it was made from; null only for a CANCELLATION_FEE item (15 §4.6 step 18), which has none.';

--
-- Name: COLUMN installment.paid_amount; Type: COMMENT; Schema: payment; Owner: -
--

COMMENT ON COLUMN payment.installment.paid_amount IS 'What RECORDED payment receipt lines pay it (check_installment_paid at commit).';

--
-- Name: COLUMN installment.reduced_amount; Type: COMMENT; Schema: payment; Owner: -
--

COMMENT ON COLUMN payment.installment.reduced_amount IS 'What closures of the rest took off it (installment_reduction; 15 §4.6 step 19): it owes amount - reduced - paid.';

