);

--
-- Name: TABLE installment_reduction; Type: COMMENT; Schema: payment; Owner: -
--

COMMENT ON TABLE payment.installment_reduction IS 'What one closure of the rest took off one installment (15 §4.6 step 19): the tied and latest installments first.';

--
-- Name: order_settlement; Type: TABLE; Schema: payment; Owner: -
--

CREATE TABLE payment.order_settlement (
    id uuid NOT NULL,
    order_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    order_number character varying(32) NOT NULL,
    contract_number character varying(40) NOT NULL,
    kind character varying(20) NOT NULL,
    source_id uuid NOT NULL,
    currency character varying(3) NOT NULL,
    collected_amount numeric(19,4) NOT NULL,
    closed_amount numeric(19,4) DEFAULT 0 NOT NULL,
    reduced_amount numeric(19,4) DEFAULT 0 NOT NULL,
    surplus_amount numeric(19,4) NOT NULL,
    fee_amount numeric(19,4) DEFAULT 0 NOT NULL,
    fee_percent numeric(5,2),
    fee_reason character varying(500),
    fee_detail character varying(2000),
    fee_covered_amount numeric(19,4) DEFAULT 0 NOT NULL,
    refundable_amount numeric(19,4) DEFAULT 0 NOT NULL,
    fee_owed_amount numeric(19,4) DEFAULT 0 NOT NULL,
    fee_installment_id uuid,
    settled_by uuid,
    settled_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_order_settlement_amounts CHECK (((collected_amount >= (0)::numeric) AND (collected_amount = trunc(collected_amount)) AND (closed_amount >= (0)::numeric) AND (closed_amount = trunc(closed_amount)) AND (reduced_amount >= (0)::numeric) AND (reduced_amount = trunc(reduced_amount)) AND (surplus_amount >= (0)::numeric) AND (fee_amount >= (0)::numeric) AND (fee_amount = trunc(fee_amount)))),
    CONSTRAINT ck_order_settlement_fee_split CHECK (((fee_covered_amount = LEAST(fee_amount, surplus_amount)) AND (refundable_amount = (surplus_amount - fee_covered_amount)) AND (fee_owed_amount = (fee_amount - fee_covered_amount)) AND ((fee_owed_amount > (0)::numeric) = (fee_installment_id IS NOT NULL)))),
    CONSTRAINT ck_order_settlement_fee_terms CHECK ((((fee_reason IS NULL) = (fee_detail IS NULL)) AND (NOT ((fee_percent IS NOT NULL) AND (fee_reason IS NOT NULL))) AND ((fee_reason IS NULL) OR ((btrim((fee_reason)::text) <> ''::text) AND (btrim((fee_detail)::text) <> ''::text) AND (fee_amount > (0)::numeric))) AND ((fee_percent IS NULL) OR ((fee_percent > (0)::numeric) AND (fee_percent <= (100)::numeric) AND (fee_amount = round(((collected_amount * fee_percent) / (100)::numeric))))) AND ((fee_amount = (0)::numeric) OR (fee_percent IS NOT NULL) OR (fee_reason IS NOT NULL)))),
    CONSTRAINT ck_order_settlement_kind CHECK (((kind)::text = ANY ((ARRAY['ORDER_CANCELLED'::character varying, 'REMAINDER_CLOSED'::character varying, 'GOODS_RETURNED'::character varying])::text[]))),
    CONSTRAINT ck_order_settlement_surplus CHECK (((((kind)::text = 'ORDER_CANCELLED'::text) AND (source_id = order_id) AND (closed_amount = (0)::numeric) AND (reduced_amount = (0)::numeric) AND (surplus_amount = collected_amount)) OR (((kind)::text = 'REMAINDER_CLOSED'::text) AND (closed_amount > (0)::numeric) AND (reduced_amount <= closed_amount) AND (surplus_amount = (closed_amount - reduced_amount)) AND (surplus_amount <= collected_amount) AND (fee_percent IS NULL)) OR (((kind)::text = 'GOODS_RETURNED'::text) AND (closed_amount > (0)::numeric) AND (reduced_amount <= closed_amount) AND (surplus_amount = (closed_amount - reduced_amount)) AND (surplus_amount <= collected_amount) AND (fee_amount = (0)::numeric) AND (fee_percent IS NULL) AND (fee_reason IS NULL))))
);

--
-- Name: TABLE order_settlement; Type: COMMENT; Schema: payment; Owner: -
--

COMMENT ON TABLE payment.order_settlement IS 'What a cancellation, or a closure of the rest, did with a contract order''s money (kltn-docs 15 §4.5, §4.6): the fee paid from the surplus first, the rest refundable, a shortfall owed on a CANCELLATION_FEE installment. Never changed.';

--
-- Name: COLUMN order_settlement.closed_amount; Type: COMMENT; Schema: payment; Owner: -
--

COMMENT ON COLUMN payment.order_settlement.closed_amount IS 'REMAINDER_CLOSED: what the goods closed were worth with VAT; GOODS_RETURNED: what the goods refunded on a return were worth with VAT (team plan 4D-3); 0 for a cancellation.';

--
-- Name: payment_receipt; Type: TABLE; Schema: payment; Owner: -
--

CREATE TABLE payment.payment_receipt (
    id uuid NOT NULL,
    customer_id uuid NOT NULL,
    reference character varying(100) NOT NULL,
    received_on date NOT NULL,
    amount numeric(19,4) NOT NULL,
    currency character varying(3) NOT NULL,
    note character varying(500),
