    recorded_by uuid NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    voided_by uuid,
    voided_at timestamp with time zone,
    void_reason character varying(500),
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_payment_receipt_amount CHECK (((amount > (0)::numeric) AND (amount = trunc(amount)))),
    CONSTRAINT ck_payment_receipt_note CHECK (((note IS NULL) OR (btrim((note)::text) <> ''::text))),
    CONSTRAINT ck_payment_receipt_received CHECK ((received_on <= ((recorded_at AT TIME ZONE 'Asia/Ho_Chi_Minh'::text))::date)),
    CONSTRAINT ck_payment_receipt_reference CHECK ((((reference)::text = btrim((reference)::text)) AND ((reference)::text <> ''::text))),
    CONSTRAINT ck_payment_receipt_status CHECK (((status)::text = ANY ((ARRAY['RECORDED'::character varying, 'VOIDED'::character varying])::text[]))),
    CONSTRAINT ck_payment_receipt_voided CHECK (((((status)::text = 'VOIDED'::text) = (voided_at IS NOT NULL)) AND ((voided_at IS NULL) = (voided_by IS NULL)) AND ((voided_at IS NULL) = (void_reason IS NULL)) AND ((void_reason IS NULL) OR (btrim((void_reason)::text) <> ''::text)) AND ((voided_at IS NULL) OR (voided_at >= recorded_at))))
);

--
-- Name: TABLE payment_receipt; Type: COMMENT; Schema: payment; Owner: -
--

COMMENT ON TABLE payment.payment_receipt IS 'Money the accountant matched to the bank statement and recorded against installments (kltn-docs 15 §4.2, §5.3): never edited; a wrong one is VOIDED with a reason and kept (BR-04).';

