    CONSTRAINT ck_refund_record_reference CHECK ((((reference)::text = btrim((reference)::text)) AND ((reference)::text <> ''::text))),
    CONSTRAINT ck_refund_record_refunded_on CHECK ((refunded_on <= ((recorded_at AT TIME ZONE 'Asia/Ho_Chi_Minh'::text))::date)),
    CONSTRAINT ck_refund_record_status CHECK (((status)::text = ANY ((ARRAY['RECORDED'::character varying, 'VOIDED'::character varying])::text[]))),
