COMMENT ON TABLE payment.refund_record IS 'A refund the accountant made outside the system and recorded (kltn-docs 15 §4.5 step 16, BR-14): never edited; one recorded wrong is VOIDED with a reason and kept. The live records of an order never exceed what its settlements made refundable.';

