    CONSTRAINT ck_audit_action CHECK (((action)::text = ANY ((ARRAY['CREATE'::character varying, 'UPDATE'::character varying, 'DELETE'::character varying, 'APPROVE'::character varying, 'REJECT'::character varying, 'EXPORT'::character varying, 'TRANSITION'::character varying, 'LOGIN'::character varying, 'LOGOUT'::character varying, 'GRANT'::character varying, 'REVOKE'::character varying])::text[]))),
    CONSTRAINT ck_audit_outcome CHECK (((outcome)::text = ANY ((ARRAY['SUCCESS'::character varying, 'FAILURE'::character varying])::text[])))
);

