    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT ck_idempotency_completed CHECK (((((status)::text = 'IN_PROGRESS'::text) AND (completed_at IS NULL) AND (response_status IS NULL)) OR (((status)::text = 'COMPLETED'::text) AND (completed_at IS NOT NULL) AND (response_status IS NOT NULL)))),
    CONSTRAINT ck_idempotency_status CHECK (((status)::text = ANY ((ARRAY['IN_PROGRESS'::character varying, 'COMPLETED'::character varying])::text[])))
);

