--
-- Name: TABLE legacy_archive; Type: COMMENT; Schema: platform; Owner: -
--

COMMENT ON TABLE platform.legacy_archive IS 'Rows of tables dropped by contracts C1-C4 (V20261011000200), by the removal of in-house production (V20261108000100), of receiving QC (V20261108000200), of transfers between warehouses (V20261108000300), of parcel shipping, the delivery-mode choice and COD (V20261108000400) and of the design check at packing (V20261108000500), the customization templates and print areas as they were before templates got a model (V20261108000600), design statuses renamed when customers began designing (V20261108000800), the staff design workflow''s assignments, its designs left waiting for confirmation and its permission (V20261108001000), the parcel carriers'' status before they were retired (V20261108001300), and purchasing - purchase orders, suppliers, supplier invoices, reorder proposals, subcontracting, the purchase columns of receipts and items, and the QC photos of receipts (V20261113000200). Read-only history.';

--
-- Name: legacy_archive_id_seq; Type: SEQUENCE; Schema: platform; Owner: -
--

ALTER TABLE platform.legacy_archive ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
