);

--
-- Name: TABLE goods_receipt_return_cartons; Type: COMMENT; Schema: procurement; Owner: -
--

COMMENT ON TABLE procurement.goods_receipt_return_cartons IS 'The cartons scanned on a RETURN goods receipt (kltn-docs 03 §4.2 step 10): each keeps the LPN, SKU, count and lot it was shipped with (BR-03, BR-14); condition_note is what the warehouse saw of its outside (dented, wet, opened). Scanned (created_at) and removed only while the receipt is a DRAFT.';

--
-- Name: goods_receipts; Type: TABLE; Schema: procurement; Owner: -
--

CREATE TABLE procurement.goods_receipts (
    id uuid NOT NULL,
    receipt_number character varying(30) NOT NULL,
    warehouse_id uuid NOT NULL,
    status character varying(16) DEFAULT 'DRAFT'::character varying NOT NULL,
    received_at timestamp with time zone NOT NULL,
    received_by uuid NOT NULL,
    confirmed_at timestamp with time zone,
    confirmed_by uuid,
    delivery_note character varying(100),
    note text,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    closed_at timestamp with time zone,
    receipt_type character varying(16) NOT NULL,
    production_order_id uuid,
    customer_order_id uuid,
    return_shipment_id uuid,
    return_request_id uuid,
    quarantine_location_id uuid,
    CONSTRAINT ck_goods_receipts_cancelled CHECK ((((status)::text <> 'CANCELLED'::text) OR (confirmed_at IS NULL))),
    CONSTRAINT ck_goods_receipts_closed CHECK ((((status)::text = 'CLOSED'::text) = (closed_at IS NOT NULL))),
    CONSTRAINT ck_goods_receipts_confirmed CHECK ((((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'CANCELLED'::character varying])::text[])) OR ((confirmed_by IS NOT NULL) AND (confirmed_at IS NOT NULL)))),
    CONSTRAINT ck_goods_receipts_production_order CHECK ((((receipt_type)::text = 'PRODUCTION'::text) = (production_order_id IS NOT NULL))),
    CONSTRAINT ck_goods_receipts_return_source CHECK (
CASE
    WHEN ((receipt_type)::text = 'RETURN'::text) THEN ((customer_order_id IS NOT NULL) AND (quarantine_location_id IS NOT NULL) AND (num_nonnulls(return_shipment_id, return_request_id) = 1) AND (production_order_id IS NULL))
    ELSE ((customer_order_id IS NULL) AND (quarantine_location_id IS NULL) AND (return_shipment_id IS NULL) AND (return_request_id IS NULL))
END),
    CONSTRAINT ck_goods_receipts_return_status CHECK ((((receipt_type)::text <> 'RETURN'::text) OR ((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'CANCELLED'::character varying])::text[])) OR (((status)::text = 'CLOSED'::text) AND (confirmed_at IS NOT NULL) AND (closed_at = confirmed_at)))),
