-- Name: product_change_log; Type: TABLE; Schema: product; Owner: -
--

CREATE TABLE product.product_change_log (
    id uuid NOT NULL,
    product_id uuid NOT NULL,
    change_type character varying(32) NOT NULL,
    subject_type character varying(20) DEFAULT 'PRODUCT'::character varying NOT NULL,
    subject_id uuid,
    from_status character varying(32),
    to_status character varying(32),
    reason character varying(500),
    changed_fields text[] DEFAULT '{}'::text[] NOT NULL,
    actor_id uuid,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_product_change_log_reason CHECK (((reason IS NULL) OR (btrim((reason)::text) <> ''::text))),
    CONSTRAINT ck_product_change_log_reason_required CHECK ((((change_type)::text <> ALL ((ARRAY['SUSPENDED'::character varying, 'DISCONTINUED'::character varying])::text[])) OR (reason IS NOT NULL))),
    CONSTRAINT ck_product_change_log_status CHECK (((((subject_type)::text = 'PRODUCT'::text) AND ((from_status IS NULL) OR ((from_status)::text = ANY ((ARRAY['DRAFT'::character varying, 'PENDING_APPROVAL'::character varying, 'APPROVED'::character varying, 'PUBLISHED'::character varying, 'INACTIVE'::character varying, 'DISCONTINUED'::character varying])::text[]))) AND ((to_status IS NULL) OR ((to_status)::text = ANY ((ARRAY['DRAFT'::character varying, 'PENDING_APPROVAL'::character varying, 'APPROVED'::character varying, 'PUBLISHED'::character varying, 'INACTIVE'::character varying, 'DISCONTINUED'::character varying])::text[])))) OR (((subject_type)::text = 'VARIANT'::text) AND ((from_status IS NULL) OR ((from_status)::text = ANY ((ARRAY['DRAFT'::character varying, 'ACTIVE'::character varying, 'BLOCKED'::character varying, 'OBSOLETE'::character varying])::text[]))) AND ((to_status IS NULL) OR ((to_status)::text = ANY ((ARRAY['DRAFT'::character varying, 'ACTIVE'::character varying, 'BLOCKED'::character varying, 'OBSOLETE'::character varying])::text[])))) OR (((subject_type)::text <> ALL ((ARRAY['PRODUCT'::character varying, 'VARIANT'::character varying])::text[])) AND (from_status IS NULL) AND (to_status IS NULL)))),
    CONSTRAINT ck_product_change_log_type CHECK (((((subject_type)::text = 'PRODUCT'::text) AND ((change_type)::text = ANY ((ARRAY['CREATED'::character varying, 'UPDATED'::character varying, 'SUBMITTED'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying, 'SUSPENDED'::character varying, 'RESUMED'::character varying, 'DISCONTINUED'::character varying])::text[]))) OR (((subject_type)::text = 'VARIANT'::text) AND ((change_type)::text = ANY ((ARRAY['VARIANT_ADDED'::character varying, 'VARIANT_UPDATED'::character varying, 'VARIANT_STATUS'::character varying])::text[]))) OR (((subject_type)::text = 'MEDIA'::text) AND ((change_type)::text = 'MEDIA'::text)) OR (((subject_type)::text = 'LOGISTICS'::text) AND ((change_type)::text = 'LOGISTICS'::text)) OR (((subject_type)::text = 'INVENTORY_CONTROL'::text) AND ((change_type)::text = 'INVENTORY_CONTROL'::text)) OR (((subject_type)::text = 'PURCHASING'::text) AND ((change_type)::text = 'PURCHASING'::text)) OR (((subject_type)::text = 'UOM_CONVERSION'::text) AND ((change_type)::text = 'UOM_CONVERSION'::text)) OR (((subject_type)::text = 'SALES_UNIT'::text) AND ((change_type)::text = 'SALES_UNIT'::text))))
);

