    suspended_at timestamp with time zone,
    suspend_reason character varying(500),
    self_approved boolean DEFAULT false NOT NULL,
    CONSTRAINT ck_products_approved CHECK ((((status)::text <> ALL ((ARRAY['APPROVED'::character varying, 'ACTIVE'::character varying, 'PUBLISHED'::character varying, 'INACTIVE'::character varying])::text[])) OR ((approved_by IS NOT NULL) AND (approved_at IS NOT NULL)))),
    CONSTRAINT ck_products_approver_not_submitter CHECK ((self_approved OR (approved_by IS NULL) OR (submitted_by IS NULL) OR (approved_by <> submitted_by))),
    CONSTRAINT ck_products_brand_on_submit CHECK ((((status)::text <> 'PENDING_APPROVAL'::text) OR (brand_id IS NOT NULL))),
    CONSTRAINT ck_products_code CHECK (((code)::text ~ '^[A-Z0-9][A-Z0-9_-]{0,49}$'::text)),
    CONSTRAINT ck_products_discontinue_reason CHECK ((((status)::text <> 'DISCONTINUED'::text) OR ((discontinue_reason IS NOT NULL) AND (btrim((discontinue_reason)::text) <> ''::text)))),
    CONSTRAINT ck_products_discontinued CHECK ((((status)::text <> 'DISCONTINUED'::text) OR (discontinued_at IS NOT NULL))),
    CONSTRAINT ck_products_inactive CHECK ((((status)::text <> 'INACTIVE'::text) OR ((suspended_at IS NOT NULL) AND (suspend_reason IS NOT NULL) AND (btrim((suspend_reason)::text) <> ''::text)))),
    CONSTRAINT ck_products_kind CHECK (((kind)::text = 'CUSTOMIZABLE'::text)),
    CONSTRAINT ck_products_published CHECK ((((status)::text <> 'PUBLISHED'::text) OR (published_at IS NOT NULL))),
    CONSTRAINT ck_products_self_approved CHECK (((NOT self_approved) OR ((approved_by IS NOT NULL) AND (approved_by = submitted_by)))),
    CONSTRAINT ck_products_slug CHECK (((slug)::text ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text)),
    CONSTRAINT ck_products_status CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'PENDING_APPROVAL'::character varying, 'APPROVED'::character varying, 'ACTIVE'::character varying, 'PUBLISHED'::character varying, 'INACTIVE'::character varying, 'DISCONTINUED'::character varying])::text[]))),
    CONSTRAINT ck_products_submitted CHECK ((((status)::text <> 'PENDING_APPROVAL'::text) OR ((submitted_by IS NOT NULL) AND (submitted_at IS NOT NULL)))),
    CONSTRAINT ck_products_suspended_pair CHECK (((suspended_at IS NULL) = (suspend_reason IS NULL))),
    CONSTRAINT ck_products_tax_class CHECK (((tax_class IS NULL) OR ((tax_class)::text = ANY ((ARRAY['STANDARD'::character varying, 'REDUCED'::character varying, 'EXEMPT'::character varying])::text[]))))
);

