);

--
-- Name: product_sales_summary; Type: TABLE; Schema: reporting; Owner: -
--

CREATE TABLE reporting.product_sales_summary (
    id uuid NOT NULL,
    sku character varying(64) NOT NULL,
    period character varying(10) NOT NULL,
    quantity_sold integer DEFAULT 0 NOT NULL,
    revenue numeric(18,2) DEFAULT 0 NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    cartons_sold integer DEFAULT 0 NOT NULL,
    CONSTRAINT ck_product_sales_summary_cartons CHECK ((cartons_sold >= 0)),
    CONSTRAINT ck_product_sales_summary_quantity CHECK ((quantity_sold >= 0)),
    CONSTRAINT ck_product_sales_summary_revenue CHECK ((revenue >= (0)::numeric))
);

--
-- Name: COLUMN product_sales_summary.period; Type: COMMENT; Schema: reporting; Owner: -
--

COMMENT ON COLUMN reporting.product_sales_summary.period IS 'The day, ISO date (yyyy-MM-dd): one row per SKU per Asia/Ho_Chi_Minh day. Months are summed by the reader.';

--
-- Name: COLUMN product_sales_summary.cartons_sold; Type: COMMENT; Schema: reporting; Owner: -
--

COMMENT ON COLUMN reporting.product_sales_summary.cartons_sold IS '4B-3 (D33): cartons of the SKU on order lines placed by the carton, less cancelled orders; ranks a SKU after revenue.';

