    last_modified_by character varying(100),
    CONSTRAINT ck_sales_daily_summary_orders_count CHECK ((orders_count >= 0)),
    CONSTRAINT ck_sales_daily_summary_revenue CHECK ((revenue >= (0)::numeric))
);

--
-- Name: area; Type: TABLE; Schema: warehouse; Owner: -
--

CREATE TABLE warehouse.area (
    id uuid NOT NULL,
    warehouse_id uuid NOT NULL,
    location_id uuid,
    code character varying(20) NOT NULL,
    type character varying(32) NOT NULL,
    name character varying(200) NOT NULL,
    x numeric(10,3) NOT NULL,
    y numeric(10,3) NOT NULL,
    width numeric(10,3) NOT NULL,
    length numeric(10,3) NOT NULL,
    rotation integer NOT NULL,
    is_obstacle boolean NOT NULL,
    status character varying(32) NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_area_code CHECK (((code)::text ~ '^[A-Z0-9]{1,20}$'::text)),
    CONSTRAINT ck_area_position CHECK (((x >= (0)::numeric) AND (y >= (0)::numeric))),
    CONSTRAINT ck_area_rotation CHECK ((rotation = ANY (ARRAY[0, 90, 180, 270]))),
    CONSTRAINT ck_area_size CHECK (((width > (0)::numeric) AND (length > (0)::numeric))),
    CONSTRAINT ck_area_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'BLOCKED'::character varying, 'MAINTENANCE'::character varying, 'INACTIVE'::character varying])::text[]))),
    CONSTRAINT ck_area_storage CHECK (((((type)::text = 'NON_STORAGE'::text) AND (location_id IS NULL)) OR (((type)::text <> 'NON_STORAGE'::text) AND (location_id IS NOT NULL)))),
    CONSTRAINT ck_area_type CHECK (((type)::text = ANY ((ARRAY['RECEIVING'::character varying, 'QUARANTINE'::character varying, 'DISPATCH'::character varying, 'STAGING'::character varying, 'OVERFLOW'::character varying, 'PRODUCTION'::character varying, 'NON_STORAGE'::character varying])::text[])))
);

--
-- Name: TABLE area; Type: COMMENT; Schema: warehouse; Owner: -
--

COMMENT ON TABLE warehouse.area IS 'Floor space that is not a shelf. Storage areas own a storage_location; NON_STORAGE ones do not.';

--
-- Name: bin; Type: TABLE; Schema: warehouse; Owner: -
--

