    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_bin_code CHECK (((code)::text ~ '^[A-Z0-9]{1,20}$'::text)),
    CONSTRAINT ck_bin_position CHECK (((x >= (0)::numeric) AND (y >= (0)::numeric))),
    CONSTRAINT ck_bin_rotation CHECK ((rotation = ANY (ARRAY[0, 90, 180, 270]))),
    CONSTRAINT ck_bin_size CHECK (((width > (0)::numeric) AND (length > (0)::numeric))),
    CONSTRAINT ck_bin_type CHECK (((type)::text = ANY ((ARRAY['STANDARD'::character varying, 'PALLET'::character varying, 'SMALL_PARTS'::character varying])::text[])))
);

