--
-- Name: boundary; Type: TABLE; Schema: warehouse; Owner: -
--

CREATE TABLE warehouse.boundary (
    id uuid NOT NULL,
    warehouse_id uuid NOT NULL,
    type character varying(32) NOT NULL,
    start_x numeric(10,3) NOT NULL,
    start_y numeric(10,3) NOT NULL,
    end_x numeric(10,3) NOT NULL,
    end_y numeric(10,3) NOT NULL,
    is_passable boolean NOT NULL,
    operational_status character varying(32),
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_boundary_kind CHECK (((((type)::text = 'WALL'::text) AND (NOT is_passable) AND (operational_status IS NULL)) OR (((type)::text = 'DOOR'::text) AND (operational_status IS NOT NULL) AND ((operational_status)::text = ANY ((ARRAY['OPEN'::character varying, 'CLOSED'::character varying])::text[]))))),
    CONSTRAINT ck_boundary_length CHECK (((start_x <> end_x) OR (start_y <> end_y))),
    CONSTRAINT ck_boundary_position CHECK (((start_x >= (0)::numeric) AND (start_y >= (0)::numeric) AND (end_x >= (0)::numeric) AND (end_y >= (0)::numeric))),
    CONSTRAINT ck_boundary_type CHECK (((type)::text = ANY ((ARRAY['WALL'::character varying, 'DOOR'::character varying])::text[])))
);

--
-- Name: move_task; Type: TABLE; Schema: warehouse; Owner: -
--

CREATE TABLE warehouse.move_task (
    id uuid NOT NULL,
    task_number character varying(30) NOT NULL,
    warehouse_id uuid NOT NULL,
    origin character varying(16) NOT NULL,
    reason character varying(16),
    sku character varying(64) NOT NULL,
    lot_number character varying(64),
    from_location_id uuid NOT NULL,
    to_location_id uuid NOT NULL,
    requested_qty integer NOT NULL,
    picked_qty integer,
    placed_qty integer,
    status character varying(16) DEFAULT 'PENDING'::character varying NOT NULL,
    priority integer DEFAULT 0 NOT NULL,
    assigned_user_id uuid,
    approved_by uuid,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    note character varying(1000),
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_move_task_approved CHECK ((((origin)::text <> 'RESLOTTING'::text) OR ((status)::text = ANY ((ARRAY['SUGGESTED'::character varying, 'REJECTED'::character varying])::text[])) OR (approved_by IS NOT NULL))),
    CONSTRAINT ck_move_task_assigned CHECK ((((status)::text <> ALL ((ARRAY['ASSIGNED'::character varying, 'IN_PROGRESS'::character varying])::text[])) OR (assigned_user_id IS NOT NULL))),
    CONSTRAINT ck_move_task_completed CHECK ((((status)::text = 'COMPLETED'::text) = (completed_at IS NOT NULL))),
    CONSTRAINT ck_move_task_discrepancy CHECK ((((status)::text <> 'DISCREPANCY'::text) OR ((picked_qty IS NOT NULL) AND (placed_qty IS NOT NULL) AND (picked_qty <> placed_qty)))),
    CONSTRAINT ck_move_task_done_qty CHECK ((((status)::text <> 'COMPLETED'::text) OR ((picked_qty IS NOT NULL) AND (placed_qty IS NOT NULL)))),
    CONSTRAINT ck_move_task_locations CHECK ((from_location_id <> to_location_id)),
    CONSTRAINT ck_move_task_origin CHECK (((origin)::text = ANY ((ARRAY['REPLENISHMENT'::character varying, 'RESLOTTING'::character varying, 'MANUAL'::character varying])::text[]))),
    CONSTRAINT ck_move_task_qty CHECK (((requested_qty > 0) AND ((picked_qty IS NULL) OR ((picked_qty >= 0) AND (picked_qty <= requested_qty))) AND ((placed_qty IS NULL) OR (placed_qty >= 0)))),
    CONSTRAINT ck_move_task_reason CHECK (((reason IS NULL) OR ((reason)::text = ANY ((ARRAY['REPLENISHMENT'::character varying, 'RESLOTTING'::character varying, 'CONSOLIDATION'::character varying, 'FIX'::character varying, 'UNBLOCK'::character varying, 'OTHER'::character varying])::text[])))),
    CONSTRAINT ck_move_task_status CHECK (((status)::text = ANY ((ARRAY['SUGGESTED'::character varying, 'PENDING'::character varying, 'ASSIGNED'::character varying, 'IN_PROGRESS'::character varying, 'ON_HOLD'::character varying, 'DISCREPANCY'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'REJECTED'::character varying])::text[]))),
    CONSTRAINT ck_move_task_suggested CHECK ((((status)::text <> 'SUGGESTED'::text) OR ((origin)::text = 'RESLOTTING'::text)))
);

--
-- Name: putaway_task; Type: TABLE; Schema: warehouse; Owner: -
--

CREATE TABLE warehouse.putaway_task (
    id uuid NOT NULL,
    goods_receipt_id uuid,
    sku character varying(64) NOT NULL,
    quantity integer NOT NULL,
    target_location_id uuid,
    status character varying(32) NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    goods_receipt_line_id uuid,
    stock_package_id uuid,
    source character varying(32) DEFAULT 'RECEIPT'::character varying NOT NULL,
    CONSTRAINT ck_putaway_quantity CHECK ((quantity > 0)),
    CONSTRAINT ck_putaway_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'IN_PROGRESS'::character varying, 'DONE'::character varying, 'CANCELLED'::character varying])::text[]))),
    CONSTRAINT ck_putaway_task_receipt_pair CHECK (((goods_receipt_id IS NULL) = (goods_receipt_line_id IS NULL))),
    CONSTRAINT ck_putaway_task_source CHECK (((((source)::text = 'RECEIPT'::text) AND (goods_receipt_line_id IS NOT NULL)) OR (((source)::text = 'QUARANTINE_RELEASE'::text) AND (goods_receipt_line_id IS NULL) AND (stock_package_id IS NOT NULL))))
);

--
-- Name: COLUMN putaway_task.goods_receipt_line_id; Type: COMMENT; Schema: warehouse; Owner: -
--

COMMENT ON COLUMN warehouse.putaway_task.goods_receipt_line_id IS 'The goods-receipt line of a RECEIPT task; NULL for a QUARANTINE_RELEASE task.';

--
-- Name: COLUMN putaway_task.stock_package_id; Type: COMMENT; Schema: warehouse; Owner: -
--

COMMENT ON COLUMN warehouse.putaway_task.stock_package_id IS 'The stock package this task puts away; NULL for loose stock.';

--
-- Name: COLUMN putaway_task.source; Type: COMMENT; Schema: warehouse; Owner: -
--

COMMENT ON COLUMN warehouse.putaway_task.source IS 'Why the task exists (05 BR-01): RECEIPT - a carton of a confirmed goods-receipt line; QUARANTINE_RELEASE - a carton a warehouse manager released from quarantine. Fixed once set.';

