--
-- Name: storage_location; Type: TABLE; Schema: warehouse; Owner: -
--

CREATE TABLE warehouse.storage_location (
    id uuid NOT NULL,
    warehouse_id uuid NOT NULL,
    kind character varying(16) NOT NULL,
    location_code character varying(64) NOT NULL,
    max_weight numeric(10,3),
    is_pickable boolean NOT NULL,
    is_putaway_target boolean NOT NULL,
    status character varying(32) NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by character varying(100),
    last_modified_at timestamp with time zone,
    last_modified_by character varying(100),
    CONSTRAINT ck_storage_location_code CHECK (((((kind)::text = 'BIN'::text) AND ((location_code)::text ~ '^[A-Z0-9]{1,10}-[A-Z0-9]{1,20}-[1-9][0-9]?-[A-Z0-9]{1,20}$'::text)) OR (((kind)::text = 'AREA'::text) AND ((location_code)::text ~ '^[A-Z0-9]{1,10}-[A-Z0-9]{1,20}$'::text)) OR (((kind)::text = 'SUBCONTRACTOR'::text) AND ((location_code)::text ~ '^[A-Z0-9]{1,10}-SUB-[A-Z0-9]{1,20}$'::text) AND (NOT is_pickable) AND (NOT is_putaway_target)))),
    CONSTRAINT ck_storage_location_kind CHECK (((kind)::text = ANY ((ARRAY['BIN'::character varying, 'AREA'::character varying, 'SUBCONTRACTOR'::character varying])::text[]))),
    CONSTRAINT ck_storage_location_max_weight CHECK (((max_weight IS NULL) OR (max_weight > (0)::numeric))),
    CONSTRAINT ck_storage_location_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'BLOCKED'::character varying, 'MAINTENANCE'::character varying, 'INACTIVE'::character varying])::text[])))
);

