-- Name: stock_movement ck_stock_movement_move_task_carton; Type: CHECK CONSTRAINT; Schema: inventory; Owner: -
--

ALTER TABLE inventory.stock_movement
    ADD CONSTRAINT ck_stock_movement_move_task_carton CHECK ((((movement_type)::text <> 'MOVE'::text) OR ((reference_type)::text <> 'MOVE_TASK'::text) OR ((from_stock_package_id IS NOT NULL) AND (to_stock_package_id IS NOT NULL))));

--
-- Name: CONSTRAINT ck_stock_movement_move_task_carton ON stock_movement; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON CONSTRAINT ck_stock_movement_move_task_carton ON inventory.stock_movement IS 'kltn-docs 11 BR-04: a person moves whole cartons. NOT VALID: loose moves before 4C-2 are history.';

--
-- Name: stock_movement ck_stock_movement_putaway_carton; Type: CHECK CONSTRAINT; Schema: inventory; Owner: -
--

ALTER TABLE inventory.stock_movement
    ADD CONSTRAINT ck_stock_movement_putaway_carton CHECK ((((movement_type)::text <> ALL ((ARRAY['MOVE'::character varying, 'STATUS_CHANGE'::character varying])::text[])) OR ((reference_type)::text <> 'PUTAWAY_TASK'::text) OR (to_stock_package_id IS NOT NULL)));

--
-- Name: CONSTRAINT ck_stock_movement_putaway_carton ON stock_movement; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON CONSTRAINT ck_stock_movement_putaway_carton ON inventory.stock_movement IS 'kltn-docs 05 BR-08: a putaway puts a carton away. NOT VALID: loose putaways before 4C-2 are history.';

--
-- Name: stock_movement ck_stock_movement_receipt_in_carton; Type: CHECK CONSTRAINT; Schema: inventory; Owner: -
--

ALTER TABLE inventory.stock_movement
    ADD CONSTRAINT ck_stock_movement_receipt_in_carton CHECK ((((movement_type)::text <> 'RECEIPT'::text) OR ((reference_type)::text <> 'GOODS_RECEIPT_LINE'::text) OR (to_stock_package_id IS NOT NULL)));

--
-- Name: CONSTRAINT ck_stock_movement_receipt_in_carton ON stock_movement; Type: COMMENT; Schema: inventory; Owner: -
--

COMMENT ON CONSTRAINT ck_stock_movement_receipt_in_carton ON inventory.stock_movement IS 'kltn-docs 03 BR-12: every unit received is in a carton. NOT VALID: loose receipt lines before 4C-2 are history.';

