--
-- Name: CONSTRAINT ck_putaway_task_receipt_carton ON putaway_task; Type: COMMENT; Schema: warehouse; Owner: -
--

COMMENT ON CONSTRAINT ck_putaway_task_receipt_carton ON warehouse.putaway_task IS 'kltn-docs 05 BR-08: a putaway task of a receipt line is one carton. NOT VALID: loose tasks before 4C-2 are history.';

