--
-- Name: CONSTRAINT ck_shelf_level_usable_height_required ON shelf_level; Type: COMMENT; Schema: warehouse; Owner: -
--

COMMENT ON CONSTRAINT ck_shelf_level_usable_height_required ON warehouse.shelf_level IS 'kltn-docs 06 BR-19: a level carries its clear height, which bin volumes are computed from. NOT VALID on purpose: legacy levels without one stay until edited (06 §4.6); every row written from V20261112000100 on must have one.';

